INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('17af225b3c92c30b65f182cc5789da97', 'okendo', 'tabitha mayne', 'Best ever!', 'I wanted a slightly sweet snack to help curb cravings to avoid higher sugar items, only problem is these are addictive 🤣 sticking with a single serving is hard when they taste that good. They are a bit crumbly, more like dusty if that makes sense but you get used to it. The taste was good at first but by my second bag the next week it was even better and I was hooked. I guess it grew on me. I only wish that a quarter of the bag wasn’t completely crumbled inside but there is probably no way to avoid that and I just use it as a yogurt topping etc, no waste here.', 5, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2026-06-20', 0, 'Yes', '', '', '["addictive","broken_crumbs"]', 'taste,addictive', 'texture,crumbling', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
