INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('801db1e2024f8dc0d74d4f98506c042a', 'okendo', 'Brian Likosar', 'So delicious that I steal them from my GF wife!', 'I love pretzels and I have them almost daily with hummus. My wife recently discovered that she does better when she doesn''t have gluten, and would almost always seem jealous of me still having them. I discovered these and ordered them for her as a gift. She let me try some, and now it''s the only pretzel in our house. You get the satisfying crunch, the pretzel flavor, and the slight saltiness that works so well with something sweet (like chocolate!)', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-06-10', 1, 'Yes', '', '', '["great_taste","crunch_texture"]', 'crunch,flavor,saltiness,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
