INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5efd30b60f2efa35c7a2f257f431be18', 'okendo', 'Andrew Sproul', 'The ultimate snack for my autistic child', 'This is the most allergen friendly snack I can pack for my child to school. He''s on a gut healing journey with functional MD and he is allergic to seed oils. This is far most the cleanest snack for anyone who has gut sensitivities. The taste is just wow ! Highly recommend this stuff.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-04-19', 0, 'Yes', '', '', '["allergy_friendly"]', 'taste,clean', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('74f28c25b9369f5325dfa1093789e3ec', 'okendo', 'Terri Totzke', 'best!', 'These are my favorite snack - they are perfect alone, or when I need a little sweet something after a meal. Not too sweet and a perfect size so just a couple gives me a good fix. I feel better about eating these than just part of a processed ingredient cookie', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-04-15', 0, 'Yes', '', '', '[]', 'sweetness,size,taste,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('21de015f39d9fee7c97281e29d58c3b8', 'okendo', 'halfkorean', 'My Favorite Cookie', 'The Ginger Cinnamon Cookie Bites is my favorite cookie for not only its taste, but also for its ingredients. I love ginger and cinnamon, but it''s hard to find REAL ginger and REAL cinnamon as ingredients in something this delicious. Yes, they''re expensive if you are comparing them to other brands, but that wouldn''t be a fair comparison, as they don''t really have any competition when accounting for both flavor and ingredients. They''re just the right texture, not soft and chewy, but not break-your-teeth crunchy. My mother also loves them as someone with dietary restrictions. We tend to eat a few after a meal to let the Ginger Cinnamon Cookie Bites act as a digestive aid. Their other Cookie Bites are delicious, too, but the Ginger Cinnamon flavor is my favorite. I highly recommend these to anyone that loves real ginger and real cinnamon and seeks out such ingredients in their food.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-04-15', 1, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,ingredients,texture,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
