INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('70092ff8889024122442b4223febfaea', 'okendo', 'Elaina H.', 'Like a bland cheez it', 'I loved the ingredients in this product as I have celiacs, I was a little disappointed in how thin they were because you just barely touched it and it would crush. The taste was alright, it would’ve been nice if they were a little more salty but I would still buy these if needed.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-04-12', 0, 'No', '', '', '["bland_flavor"]', 'ingredients', 'thickness,saltiness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
