INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('104623c1ee12d01fd0b4a6ee1ef7d558', 'okendo', 'Shanna A.', 'Tiny cookies mighty flavor', 'These really do taste like a chocolate chip cookie. There is no substituting flavor of this healthy cookie. Resealable package works well so product does not get stale. They are not hard (not soft) they crumble but are a very nice texture. They are a small snack size cookie tasty and surprisingly on the healthier side. I would definitely purchase them in the future.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-04-01', 0, 'No', '', '', '["great_taste","crunch_texture","packaging","stale"]', 'taste,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ac21e007e4a90be1a22d348957c1ad22', 'okendo', 'Shanna A.', 'Crispy with hint of salt', 'Edible “cheese” crackers. They are thin and crispy with a hint of salt otherwise not a ton of flavor. They are a decent cheese-less snack replacement for other cheesy crackers and have healthy ingredients. I like that they are baked too. Resealable packaging holds up as they did not get stale even after being open for over a month.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-04-01', 0, 'No', '', '', '["crunch_texture","good_replacement","packaging","stale"]', 'texture,ingredients,baked,packaging', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
