INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('87a6a64d43c710035647e080e580c4d6', 'okendo', 'Felicity F.', 'Great little chip for thoughtful eaters.', 'Love these little crackers! They’re very tasty and the texture and flavor are great. They’re especially good with dips like guac and queso. Reasonable price for what you get for sure.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-31', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,flavor,dips,price', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d1cd0b6053f73a01062b1310a617aad1', 'okendo', 'Massiel P.', 'Vegan gluten free', 'Delicious! The texture on these are great! They are crunchy and you won’t even miss the junk like cheese it! They are vegan friendly which are a plus in my household with a kid who’s lactose intolerant. Perfect snack! Love the container they are I. Easy to store in pantry!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-31', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","stale"]', 'texture,crunchy,vegan,container', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('aae16579c11a353cacc819ec0e407eb1', 'okendo', 'Michele Boris', 'Disappointed', 'I had the crackers and was happy with olive oil being the oil. I assumed that the cranberry cookies and the pretzels would also have olive oil in them. I guess it’s my fault. I didn’t read the ingredients, but I thought all of your products were seed oil free. So I’m not real happy that palm seed oil is one of the ingredients', 3, 'neutral', 7, 'Cranberry Vanilla Cookie Bites', '2026-03-30', 0, 'Yes', '', '', '[]', 'olive oil,crackers', 'palm oil,ingredients', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('84766d1a86d9e85fbf5214ab60f90cd8', 'okendo', 'Ashley R.', 'Very crunchy', '17 chips in a serving for a decent size snack. Very crunchy and nice level of salt. Easy to open bag and resealable. Tastes like traditional cheese crackers but without the dairy. Has a slightly bitter aftertaste but overall very good.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-30', 0, 'No', '', '', '["crunch_texture","packaging"]', 'crunchy,salt level,packaging,taste', 'aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a3f1b4bf8cabe3f02e13a4726bd0a4a3', 'okendo', 'Ashley R.', 'Bite size', 'Fun little bite size cookies. A great alternative for allergy free households. Can definitely taste the maple syrup but you know it’s naturally sweetened that way. Fairly sweet, but what I’d expect for a cookie. Can’t taste the chocolate as much though. Leaves a maple syrup aftertaste.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-30', 0, 'No', '', '', '["allergy_friendly","good_replacement"]', 'size,maple flavor', 'chocolate flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
