INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('328a6777480293cfbe24570d14913166', 'okendo', 'David', 'Yummmmm', 'My wife has food allergies and these are her comfort snack when she is looking for something sweet. Buying them straight from the company is the freshest way to go.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-03-28', 0, 'Yes', '', '', '["allergy_friendly"]', 'freshness,sweetness,comfort snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('05dce50a07c43b06075bac491fa5a78f', 'okendo', 'Dayane D.', 'Tasty but a little on the dry side', 'I really liked the ingredients in these cookies bites. There are made of simple ingredients like cassava flour and chocolate chips, and I love that they are gluten free and vegan. The aroma is nice and slight sweet when u open the bag. The texture is churchy and the dough flavor is good, but I personally wish there were a little bit softer because they felt a little dry on me. The bites are small and the portion is easy for snacking, which I like. Overall they taste good and feel like a cleaner snack option, I just prefer a soft cookie texture.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-27', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","clean_ingredients","bland_flavor"]', 'ingredients,aroma,flavor,portion', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7eab0fc4e6aa5cbe4bff8f6bc58318a9', 'okendo', 'Christina F.', 'Gluten free, Vegan, and Allergy friendly', 'I love cheese so I was so excited to receive these Every Body Eat Cheese-Less thins in exchange for my honest review. I think the packaging is great it gives all the nutrition Information in a great easy to read package. I was impressed by the cheese color and size of the thins! I loved that the serving was 17 crackers which to me was a good amount! To me the taste was pretty good! They did t have the bursting with cheese flavor that I wanted it the did have a cheese flavor and were good. For a vegan snack it was really good! It is hard to find vegan snacks!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-27', 0, 'No', '', '', '["gluten_free","dairy_free_vegan","allergy_friendly","packaging"]', 'packaging,size,serving,vegan', NULL, 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ed1985ba7b053f35269646f18be38afb', 'okendo', 'Christina F.', 'Gluten free, Vegan, and allergy friendly', 'We were excited to try the new Every Body Eat Chocolate Chip Cookie Bites! The cookies taste great! I love the fact that they are small snack sized! I think they taste just as good as a regular chocolate chip cookie. To me the best part of the cookies is the fact that they are gluten free, vegan, and allergy friendly and still taste good!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-27', 0, 'No', '', '', '["gluten_free","dairy_free_vegan","allergy_friendly"]', 'taste,size,gluten free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
