INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('afe85d456f6150c644ecd4296702fab6', 'okendo', 'Leslie K.', 'Gluten free cheese-less cracker', 'These crackers aren’t too bad if you’re looking for a healthier gluten free option. Super crisp and thin, decent flavor. Nice addition to a charcuterie board.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-19', 0, 'No', '', '', '["crunch_texture","gluten_free"]', 'texture,flavor,charcuterie', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('19feb312819623aa548504973c412b3d', 'okendo', 'Trish M.', 'Great little salty snack', 'Love these as a chip replacement. They have just the right amount of salt, and the nutrition is on point. I only eat a few at a time and satisfy my craving for a salty snack.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-03-19', 0, 'No', '', '', '["good_replacement"]', 'salt level,nutrition,portion size,chip alternative', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('29c074d3132f189db302295adb7a671a', 'okendo', 'Trish M.', 'Perfect light snack', 'These things are so good! They are a little chewy, which I like. The ginger gives them a little spice, but is mostly sweet. They are pretty healthy for a snack as well.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-03-19', 1, 'No', '', '', '["great_taste"]', 'chewy,ginger,sweet,spice', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c24b1fa572d29fda2f391783d1540499', 'okendo', 'Lauren J.', 'Yummy sweet treat', 'I was fully expecting the every body eat chocolate chip cookie bites to be underwhelming. I was pleasantly surprised that they tasted very similar to what you would expect from a packaged chocolate chip cookie. I love the clean ingredients too. Would definitely purchase in the future.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-19', 0, 'No', '', '', '["great_taste","clean_ingredients","packaging"]', 'taste,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('70ad734d13fe69bd9c282aef550babe0', 'okendo', 'Lauren J.', 'Tasty chip substitute', 'The every body eat chess less thins are thin and crispy. They satisfy the salty and crunchy cravings. It’s a convenient snack to throw in a work bag. My only comment is that I don’t taste any cheese flavor. It comes off more as a corn chip. So while yummy, it doesn’t taste as expected.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-19', 0, 'No', '', '', '["great_taste","crunch_texture","good_replacement"]', 'texture,crunchiness,convenience', 'cheese flavor', 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('edb2d8b66419cfbf4cb1966b9e67cde4', 'okendo', 'Mimi A.', 'Yummy cookie', 'I tried the everybody eats chocolate chip cookie bites and was surprised by how good they were. Another great option for people with food allergies and my toddler loved them (wheat allergy).', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-18', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'taste,texture,kid friendly', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d237cf914af2b5e21083a6434445eb41', 'okendo', 'Mimi A.', 'Great cracker for food allergies', 'I tried the everybody eats cheese less crackers and they are a great option for people with food allergies. They’re nice and thin with a satisfying crunch. They have a cheesy flavor without the cheese but left a bit of an aftertaste.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-18', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'texture', 'aftertaste', 'flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5cf178b63f0ad356b58423d3eb1798ff', 'okendo', 'Meghan O.', 'Love!', 'My family loved these cookie bites!!! I couldn’t even get a photo of them before they were gone!!! They are a healthy alternative for a sweet snack! My husband, 18 year old son and 9 year old daughter loved them!!! We will be buying these soon!!!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-17', 0, 'No', '', '', '["good_replacement","stale"]', 'taste,texture,popularity,snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0af573a85b762486783789a2f6400c41', 'okendo', 'Meghan O.', 'Love!', 'These were so yummy that my family ate them before I could even get a picture! Lol. My husband, 18 year old son and 9 year old daughter loved them!!! We will definitely be buying these to have again!!! They lasted as long as they could in my house.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-17', 0, 'No', '', '', '["great_taste","stale"]', 'taste,family appeal', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ee291efce65b3e7551f35f7de7bf8cde', 'okendo', 'Katy L.', 'So good you won’t want to share!', 'These chocolate chip cookie bites are addictive! They deliver that salty, slightly dusty, chocolatey shortbread cookie flavor you know and love. I can even pick up hints of maple, which adds an unexpected bit of complexity to what’s usually a simple comfort snack.  It’s kind of crazy that these are only $5.99 for a 5 oz bag, because at that price I’m definitely going to stock up. Affordable and delicious is a rare combination when it comes to specialty diet foods, which often miss the mark on one or both. These are a huge win across the board.  You don’t have to be gluten-free to enjoy these. Anyone could end up fiendishly snacking on them in the middle of the night, lights off, goblin-style, because they’re just that good. Shareable? Honestly, not really. Not. At. All.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-16', 0, 'No', '', '', '["great_taste","gluten_free","repeat_purchase","addictive","value_price"]', 'flavor,texture,price,addictive,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4174b582847220b5df6bc8ff7a507187', 'okendo', 'Katy L.', 'Great dupe for cheddar-flavor!', 'I’m seriously shocked these crackers are cheese-less. You could have fooled me.  They’re thin, crispy, and deliciously salty. The flavor really does resemble sharp cheddar, with the flaked sea salt coming through strongly at the finish. Texture-wise, they’re thinner than most snack crackers but somehow keep an even crispier crunch than the usual options. In my opinion, they actually hold their own against many of the top brands.  Flavor-wise, they’re top-tier for diet food, and I mean that as a compliment. I would happily eat these even if I wasn’t dieting. They’re genuinely tasty, though of course you shouldn’t expect them to completely beat the fully indulgent versions. Still, they come surprisingly close.  Then there’s the most shocking part: the price. At $5.99 for a fully packed 4 oz bag, it actually feels like a great deal for a specialty snack like this.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-16', 0, 'No', '', '', '["great_taste","crunch_texture","stale"]', 'texture,flavor,price,saltiness,crunch', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d47f0f31fe2bc092a57717d7c9d6f15f', 'okendo', 'Sarah B.', 'Chocolate Chip Cookie Bites- My Favorite!', 'I absolutely loved the Every Body Eat Chocolate Chip Cookie Bites. The texture was a perfectly crunchy with just the right amount of sweetness. I appreciate that they’re gluten-free, vegan, and allergy-friendly without sacrificing flavor. The chocolate chips give them a classic cookie taste, but they feel lighter and more wholesome than traditional cookies. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fb159f7f2601705583f0996012aa3230', 'okendo', 'Sarah B.', 'Cheese-less Thins', 'The Every Body Eat Cheese-less Thins are a great savory option, especially if you’re looking for a clean-ingredient, allergy-friendly cracker alternative. They have a nice crunch and a subtle cheesy flavor from the nutritional yeast. I love that they’re baked, not fried, and made with simple ingredients like brown rice flour and olive oil. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('07cb4cb65f6a50ad0b2e9b51735d7b67', 'okendo', 'Erin', 'Enjoyable flavors', 'Unfortunately it''s hard for me to give a good review. I personally have not tried them. They are easy to order and have mailed to my daughter in another state. She says that she does like all of the flavors and it helps her and I have peace in knowing that they are dairy and gluten free.', 5, 'positive', 9, 'Cookie Bites Variety Pack', '2026-03-15', 0, 'Yes', '', '', '["gluten_free"]', 'flavors,dairy free,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d1701a7e9eca22ec095df3ed2a82983a', 'okendo', 'Amanda L.', 'Wonderful allergen free cookies', 'Perfect little chocolate chip cookie bites. It’s amazing what they can do while keeping common allergens out of the recipe. I love the flavor. The texture is a little bit crumbly but I like it. Would go great with some almond milk.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-13', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'flavor,texture,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d7bec65b37d72242d64f346d603d3459', 'okendo', 'Amanda L.', 'Crunchy, tasty. Would have liked more flavor', 'These are just wonderful crackers for being dairy free and gluten free and vegan.   The taste is slightly cheesy because of the added nutritional yeast but i would have like even more flavor. Great size, easy to grab and go, and have a couple servings on hand. They look perfectly delicious and if you’re on a restricted diet you should definitely give these a try', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-13', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan"]', 'size,convenience,appearance', NULL, 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d8735b0986947c16560f2fc489e95840', 'okendo', 'Angela', 'Yummy and crunchy', 'My whole family loves these lightly cheesy GF Vegan snack crackers!! They are light and crispy and satisfying!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-13', 0, 'Yes', '', '', '["great_taste","crunch_texture","dairy_free_vegan"]', 'texture,taste,satisfying', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ea48c142eef8c9989dd0ace435ad0b0b', 'okendo', 'Amanda C.', 'Awful', 'I spat this out. I am allergic to dairy, wheat, nuts, sesame, and a host of other foods. I would not pay money for these. They taste like what I would imagine dryer lint would taste like. They some how are negative flavor, like it''s less than zero.', 1, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-03-13', 0, 'No', '', '', '["allergy_friendly"]', NULL, 'taste,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('955807d09aa94eacbf5e6e90ff9f7985', 'okendo', 'Amanda C.', 'They are tolerable', 'I would call these cheese adjacent. They aren''t terrible but also aren''t amazing. My kids will willingly eat them mixed into a snack mix so that has to say something. They vaguely taste like cheese and are also very thin. They remind me if communion wafers came on cheese flavored.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-13', 0, 'No', '', '', '[]', NULL, 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e154fd459c24494851208ceeaf5e9b67', 'okendo', 'Sarah S.', 'Great snack!', 'I love these snacks! They are vegan, gluten free and have few ingredients.  They aren''t overly sweet and have a nice crunchy chocolate chip cookie taste.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-13', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan"]', 'taste,sweetness,texture,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('33cb06fe5e4feded81042e4e02e02359', 'okendo', 'Sarah S.', 'Great snack!', 'I enjoy these cheese crackers as a snack: they taste fresh and crunchy. I appreciate they are cheese-less and have minimal ingredients. They don''t have an aftertaste either.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-13', 0, 'No', '', '', '["crunch_texture","clean_ingredients"]', 'taste,texture,ingredients,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5b4c9c342d74b290afc5f54a9419d553', 'okendo', 'Charlotte G.', 'Enjoyed', 'Packaging is eye catching. My son and I liked the cookie ones more. The cookie had a light crisp to it and a great alternative. They had a less fake tasting to it. IYKYK. But I’d buy these for sure.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-12', 0, 'No', '', '', '["crunch_texture","good_replacement","packaging"]', 'packaging,texture,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('24b5f93b3108f24b0970415ebef73887', 'okendo', 'Charlotte G.', 'Not in love', 'Appearance is eye catching,  great packaging! I am always looking for healthy snacks and for this particular one, I was not a fan. However, my family gobbled them up.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-12', 0, 'No', '', '', '["packaging"]', 'appearance,packaging', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6c6d6845f1e2f49b4cfce4d5a298c3b1', 'okendo', 'Keriston P.', 'Good cookie', 'The packaging was great. Very easy to open. The cookies were very crispy and there is a good amount in the package. Overall it was as a good cookie. I didn’t find the texture appealing.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-11', 0, 'No', '', '', '["crunch_texture","packaging"]', 'packaging,crispy,quantity', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('53625eb78e0e9b3a0f8324c5064bbd03', 'okendo', 'Keriston P.', 'Just ok', 'This thins were very fresh. It was very crunchy the ingredients were sensitivity friendly. The bag is easy to close and keeps the product fresh. I just believe that Im not the target audience for these.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-03-11', 0, 'No', '', '', '["crunch_texture","false_advertising"]', 'freshness,texture,ingredients,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a26c5f2df3bd4a7f956fedfe0061d8a6', 'okendo', 'Zaynab C.', 'Great', 'I tried EVERY BODY EAT cheese snack and I love it, it’s light, crunchy, and full of flavor. I appreciate that it’s made with a mix of healthy ingredients like brown rice, olive oil, and paprika… made you fell happy while enjoying this healthy snack. And also it’s vegan, gluten free and allergy friendly. The packaging is eye catching. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2c564f6fb4652fb42e98818504232086', 'okendo', 'Zaynab C.', 'Great!', 'I tried t this chocolate chip cookie bites and they actually taste good. I like that they are gluten free, vegan and made with healthier ingredients, you don’t feel guilty enjoying them.  
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9cbb7beb4b94a483cabea3aec42b5bb5', 'okendo', 'Sierra F.', 'These are pretty good!', 'These are crunchy, savory, salty snd have a cheese vibe to them without the cheese! My toddlers and older kids devoured them and I had to buy more to do this review, haha, so YES, they are good! I totally recommend these to anyone looking for a better cheeze-it! The bag is fine, it seals nicely, easy to store just about anywhere and as far as cleanup goes, there isn’t any because you’re going to eat every last crumb haha! They’re so good and make a great snack.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-11', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'crunchy,salty,cheese flavor,taste,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fae794c89a45f0cc24ef6d545f08c09c', 'okendo', 'Anna W.', 'Great Option for Clean Snacking', 'I really appreciate the clean and simple ingredient list on these cookie bites. They’re free from top 14 allergens, plus they’re gluten, dairy free and vegan. They’re a solid option for anyone looking for a clean snack. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bc37450a2b980a38c1ddbe7dc1104c5a', 'okendo', 'Anna W.', 'Clean Ingredients and Allergen Friendly', 'I really appreciate the ingredient list on these crackers. They’re made with simple ingredients, use olive oil instead of seed oils and are gluten and dairy free and vegan. Awesome option if you are looking for a cleaner snack option! 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ebc88149622b73ea91de04b8ccbd965e', 'okendo', 'Kristen U.', 'Nope', 'Not a fan! Waaay too dry almost to the point of a sandy consistency. Flavor is barely detected as the chocolate is overpowered by the strong taste of the flour. Unfortunately, not a hit with me or the kiddos. I would buy from this brand, just would not try this particular product again.', 1, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-03-11', 0, 'No', '', '', '["bland_flavor"]', NULL, 'texture,flavor,chocolate', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('46fc5b1e06cfcf21798538b19462d231', 'okendo', 'Kristen U.', 'A hit with the fam!', 'Crunchy and tasty with just the right amount of salt - love the clean ingredients that make these a guilt free snacking option! Whole family agreed that they were yummy but I took one star because there is a weird aftertaste that is a little bit ‘fake’ tasting. All in all, an affordable and healthier option so I’d totally buy them or at least try another flavor!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-11', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","value_price"]', 'texture,taste,salt level,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1907e8566d42cf54c0b5b035002d76b6', 'okendo', 'Shakira W.', 'Love these cinnamon gingers!', 'Amazing sweetness taste! The aroma really adds to the flavor and the crumb was amazing, I dipped this in some milk and it was amazing! The consistency is great and it’s so fresh.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-03-11', 0, 'No', '', '', '[]', 'taste,aroma,crumb,consistency,freshness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f916188bf7f5e483218a71879ef32361', 'okendo', 'Shakira W.', 'Love this product omg!', 'So good I wanted more! The freshness, the texture and the amazing flavor/taste! The ingredients are healthy and it’s the perfect amount of saltiness. The after taste is so good!', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-03-11', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'freshness,texture,flavor,saltiness,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1013c79eb078fe02b3d93a7d816cccd6', 'okendo', 'Martina A.', '⭐⭐⭐⭐⭐ Every Body Eat Pretzel Thins (4oz)', 'These pretzel thins are absolutely delicious! They have the perfect crunch and just the right amount of salt. They’re light, crispy, and great for snacking on their own or pairing with dips and spreads. The quality is excellent and they taste fresh in every bite. A great snack to keep around—definitely recommend!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-03-11', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunch,salt,texture,quality,freshness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('da948485d49f236075d9175413c06799', 'okendo', 'Martina A.', '⭐⭐⭐⭐⭐ Every Body Eat Ginger Cinnamon (5oz)', 'These ginger cinnamon cookies are amazing! The flavor is warm and perfectly balanced with just the right amount of spice and sweetness. They have a great texture and taste homemade. Perfect with coffee or tea, and they make a really satisfying snack. I’ll definitely be buying these again!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-03-11', 0, 'No', '', '', '["crunch_texture"]', 'flavor,texture,taste,spice,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7a5e00e08e90ac49c914f2835ffdb910', 'okendo', 'Sierra F.', 'You’ve been warned about how amazing these are', 'I seriously bought 12 bags of these from Walmart because I needed to take photos for the review and MY FAMILY KEPT EATING THEM. I am not kidding! I had to wait until everyone was at school and order more to be delivered today just so that I could do this review!! 😳 so, yeah, obviously they’re good.. a little too good! My husband calls them “brown sugar cookies” and they do totally have a brown sugar taste in the best way. They’re equal parts soft and crunchy, amazing buttery brown sugar chocolate chip cookie flavor & they have SUCH great ingredients that I don’t mind letting everyone have a treat- knowing they’re getting whole food ingredients. The package is a zip seal and that was fine- it seals decently- but seriously, what matters is the taste and these are so freaking good and addictive! I don’t think I’ve repurchased anything that influenster has sent to me AS MUCH as I’ve purchased these. I need an intervention.. and YOU need to try them lol.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-11', 1, 'No', '', '', '["crunch_texture","repeat_purchase","clean_ingredients","addictive","packaging"]', 'taste,texture,ingredients,addictive', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('601959d50113d81b03cc86d9d33ddf86', 'okendo', 'Karla G.', 'Good snack', 'Not my favorite taste. Texture is grainy. Packaging is good to carry in your bag for a quick and sweet snack. Good and fresh ingredients.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1ccdd023c3c852abc76c6d343e61d1f4', 'okendo', 'Karla G.', 'Tasty snack', 'Not mind blowing, but I really like the taste. They are like healthy Cheez it. Perfect for a quick snack to carry in your bag. Convenient packaging, nice aesthetic, tasty snack! Learned that a snack could be healthy.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-11', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,packaging,portability,healthy', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ca9f8bd6225e8919e7d565558de1c10a', 'okendo', 'Melissa W.', 'Delicious', 'I liked these, a lot! They taste great! They are a crispy cookie. I’m usually a soft cookie fan, but these were delicious and I will definitely purchase these again. They do crumble and fall apart pretty easy, but the taste makes up for the texture.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,crispiness', 'crumbling', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
