INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7bb55fa2b5687082645765c00c9d2b95', 'okendo', 'Kelsie S.', 'Not great', 'I appreciate that the product is without gluten and May common allergens but I find it unappetizing. It is very gritty and chalky and without a good flavor. There are better options for sweets.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["allergy_friendly"]', NULL, 'texture,flavor,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
