INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('404f6b65be2c6d235e1b2b91c557d724', 'okendo', 'Karissa C.', 'satisfy your cheese craving!', 'These snack thins are seriously impressive. They have that savory, cheesy flavor you crave but without any actual dairy, which makes them perfect if you’re vegan or avoiding allergens. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e8ad3d7fe131c0b23a39810bde10ed74', 'okendo', 'Jetlira N.', 'They’re okay.', 'They didn’t taste the best but they weren’t bad, a little too dry for my liking but if you’re carving something sweet these are okay. There’s really no smell to them but they are chewy', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["bland_flavor"]', NULL, 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b98cc4c829726afac108c0e5797653ff', 'okendo', 'Jetlira N.', 'It’s a no from me', 'I wanted to like these so so bad because they’re a healthier choice but they just don’t taste good. I hate leaving reviews like this and I’m sure other people feel differently but they just weren’t it for me. I’m sorry', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '[]', NULL, 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('64b02630835e2e061ac236f5a706c599', 'okendo', 'Carol W.', 'Perfect bite size GF treat', 'The cookies are the perfect bite size!  They have a really good chocolate flavor and are crunchy but not crumbly.  You can eat just one or a few for a snack.  They don’t leave an aftertaste or have a weird taste like some gluten free snacks.  
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('13cbfbdce803ff34c9f740487c070263', 'okendo', 'Carol W.', 'Thin, Crispy, and Full of Flavor', 'I’m a big fan of these!  They are super thin and crispy with a nice cheesy flavor.  Unlike many gluten free snacks they are not gritty.  They are salty, but not in an overwhelming way, almost a perfect balance.  I think there is a slight hint of red chile flavor but that could also just be the New Mexican in me.  
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4ebbd2070af83c9801d9b530e7b28727', 'okendo', 'Claire P.', 'Yummy', 'I like these cookies. I think they would go really well with tea or coffee or milk, since they are a bit dry and crumbly. They aren''t too hard though and they do have ok flavor! I would probably buy these for a snack!', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["great_taste","bland_flavor","texture_issue"]', 'pairing', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('06f086484e5f060439ed70ef11a0c549', 'okendo', 'Claire P.', 'Crunchy and filling', 'The taste is ok, the look is a little weird. The crunch is great! It is a nice thing to have as a snack or alongside a sandwich! I would probably take these more as a to go snack than an indulgent one to have on the couch.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '["crunch_texture"]', 'crunch,portability', 'appearance', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8eb77f46b4658975356c80d2b6e648f2', 'okendo', 'Alyse N.', 'Just okay', 'These were just okay for me.  Not the worst gluten free cookies I''ve had, but definitely not the best.  The texture was very crumbly for me.  Not my favorite.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["crunch_texture","gluten_free"]', NULL, 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c9e37e9740f1b8a235cbd123b5e2f295', 'okendo', 'Alyse N.', 'Just okay', 'These are just okay for me.  I don''t feel like they have a ton of flavor.  I think this would be better with some kind of dip, but alone they were just mehh.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '[]', NULL, 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ecdf74c497c0e4f33ecf4fdb1be1b4df', 'okendo', 'Jennifer S.', 'Tasty and good for you!', 'Addictive. These mini cookies without gluten or dairy actually taste and look like a cookie. They are crunchy without being dry, they taste like a dang good cookie, and have ingredients you can read and understand. I have to tell myself to not eat the whole bag when I grab some, they are just that good!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["great_taste","crunch_texture","addictive","bland_flavor"]', 'taste,texture,ingredients,addictive', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('183f8ba4400ebc30103d659fca4c4f87', 'okendo', 'Jennifer S.', 'Tasty cheese-less crackers!', 'A tasty snack that you can read and pronounce every ingredient? Yes please! For a dairy and gluten sensitive house, these are perfect. The first bite, I was a little skeptical but then the flavor grew on me. These cheese crackers taste like cheese. They also have a nice texture and crunch them.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,ingredients,texture,crunch', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('36862073a89f408150db41971e9d48e3', 'okendo', 'Jenn R.', 'The crumbly texture is probably my favorite part', 'The crumbly texture is probably my favorite part! They remind me of the mini chocolate crumbly cookies you’d get in the vending machine,, but a healthy version. They aren’t overpoweringly sweet and the amount of chocolate chips are perfect. I may or may not have eaten a whole bag in a day.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["crunch_texture"]', 'texture,sweetness,chocolate chips,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('373843854f8d96ab5409d56835ef2160', 'okendo', 'Jenn R.', 'gluten free, healthier alternative for snacks', 'It’s like a healthy version of the one we all know.  It’s bigger in size and way more crunchy which I loved for a cracker.  The sodium content is lower than an average cracker, which I appreciated and it didn’t leave a film on the top of my mouth like the others do. Love the strong ziplock-like sealing bag for easy snacking and storage. I’d definitely recommend if you’re looking for a gluten free, healthier alternative for snacks.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '["crunch_texture","gluten_free","good_replacement","packaging"]', 'size,crunchiness,packaging,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8d4d7e96265c19cd8070b10c673bc5b6', 'okendo', 'Kacee S.', 'A decent treat with good flavor', 'These cookies had decent flavor.  I think they would be an okay treat. The consistency was overall pretty good.  I probably would not pay for these independently.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '[]', 'flavor,consistency', 'value', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b0d9468c6530354d81c5900cffced1e6', 'okendo', 'Kacee S.', 'Decent crunch and okay flavor', 'I had such high hopes for these, but I did not like the flavor at all. The texture and consistency was pretty good though.  I probably would not purchase.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '["crunch_texture"]', 'texture,consistency', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('30b571ef2ffa86fb96b31ef7bfe4b4e4', 'okendo', 'amy B.', 'Sweet treat', 'If you go into this knowing it’s a good for you cookie, you’ll love them. They are close to a soft coomor texture and a soft chewy texture. They smell great! They are sweet but not too much and are a great healthy sweet treat!', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-10', 0, 'No', '', '', '["crunch_texture"]', 'texture,smell,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0a9e4fcfd88f95a091f12c1cf56376bd', 'okendo', 'amy B.', 'As close to cheese as you can get.', 'I was very skeptical of these but they were good! They are not your typical cracker but they are light and feel close  to cheese as you can get. They crunch like a cracker normally would. They were pretty good!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-10', 0, 'No', '', '', '["crunch_texture"]', 'texture,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('04f4b8456ad1bb23a00da68df6b1bb55', 'okendo', 'Holly V.', 'Great snack!', 'These are a great snack that isn’t bad for you. Could have a better taste but it’s not bad. My kids seemed to like them way more than me. So a fun snack for them!', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-09', 0, 'No', '', '', '[]', 'kids,snack', NULL, 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('42061e4090618b3e3441026cecc4312c', 'okendo', 'Holly V.', 'Needs a better flavor but good product for a quick', 'I am not a huge fan of the flavor but they are big horrible. I like that they are baked and not fried. Easy portion size the texture is good and doesn’t scrap your mouth.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-09', 0, 'No', '', '', '["crunch_texture"]', 'baked,portion size,texture', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b0fe187c4484504d3080248662be99e4', 'okendo', 'Angela S.', 'Delicious Cookies', 'I ate these cookies so quickly that I didn’t even have a chance to take a picture of them.  The texture is a little crumbly and it has great flavor.  I loved how small they were as a I could eat a few of them and not feel guilty at all.  They sure are addicting.  I loved that it has crispy edges.  My 7 year old daughter loved them and so did I.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-09', 0, 'No', '', '', '["great_taste","crunch_texture","stale"]', 'flavor,size,edges,addictive', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('194d7da82238a8357695f0f9a19640d1', 'okendo', 'Angela S.', 'So good', 'These cheese-less thins were delicious.  They had a very crispy exterior and left me feeling full.  I loved the shape and texture.  I finished the whole bag in one sitting as it is that addictive. I would definitely recommend this product.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-09', 0, 'No', '', '', '["great_taste","crunch_texture","addictive"]', 'taste,crispiness,texture,filling,addictive', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cf4ffde28cce5bf9b5b28b22c1fe84d3', 'okendo', 'Aneta K.', 'Crispy dairy free cracker', 'Great alternative for a dairy free cheese less cracker. Tastes almost like real cheese. The salt sprinkled on top makes for a better flavor. Super crispy,light, and delicious snack.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-09', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan","good_replacement"]', 'taste,flavor,texture,lightness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c95d5a771702b82728fc16d3900a259c', 'okendo', 'Tania A.', 'Crunchy, Healthy and Made with Real Ingredients', 'These Every Body Eat Cheese-Less Thins are a great healthier alternative to traditional cheese crackers. They’re gluten-free, dairy free, and made with just 8 real ingredients, which is something I always appreciate when choosing snacks for my family. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8baf40e0ef71320d8cc43946eba3fbb1', 'okendo', 'Tania A.', 'Finally - An Allergen-Friendly Cookie My Kids Love', 'As a mom to a daughter with severe tree nut allergies, treats are something we always have to be extra cautious about. Finding a cookie that’s safe and delicious is rare — but these chocolate chip cookie bites from Every Body Eat nailed it. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7f3eabfb88a51c1581cced14a0ad8e1e', 'okendo', 'Nadia L.', 'Tastes just like a real cookie!', 'I love eating chocolate chip cookies and always crave for it. I know having a lot is not good for my diet, but the Every Body Eats brand chocolate chip cookies is a good healthy alternative for  my sweet cravings. It’s a perfect bite size. Balance of sweet and a hint of saltiness, not so much on the chewy side, it’s more crunchy, but I love both.  It didn’t leave any aftertaste in my mouth even with all the healthy ingredients in a cookie!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-09', 0, 'No', '', '', '["crunch_texture","good_replacement"]', 'bite size,sweetness,texture,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5323bb2c39e850300d7eb35c2291f39f', 'okendo', 'Nadia L.', 'Love that it’s vegan and gluten free!', 'I’ve never tried Every Body Eats brands before and am very surprised that it’s gluten free, vegan and allergy friendly. I didn’t know all these while taking a first bite thinking it contains cheese like the other cheese thins brands. The best part is that is baked and not fried.  Looks like a regular cheese thins, tastes great and best value for the product. I left it opened for a few days and it remained crispy. This little bag goes a long way.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-09', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly"]', 'taste,value,crispiness,baked,portion', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c3a769ca9f242b500c0446ebea96c6d9', 'okendo', 'Jamie J.', 'Yum, yum, yum!', 'I’m gonna hype this up because they are so good! It says crunchy on the bag, and normally I don’t like crunchy, but these are just the right amount of crunch meaning there’s still some softness to them. They have kind of a buttery texture and not too sugary… It’s just right. I don’t like super sweet things. The bag is resealable too. They melt in your mouth!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-09', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'texture,sweetness,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9287a4be28d3224a265a899ec353b7ae', 'okendo', 'Jamie J.', 'Wow!', 'I’m not even exaggerating! – These are amazing! I have to eat gluten-free foods and normally things are pretty bland, but this is perfect. They are crunchy and very pleasing in every way. Plus, the bag is resealable.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-09', 0, 'No', '', '', '["crunch_texture","gluten_free","bland_flavor","packaging"]', 'taste,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
