INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d1d61a5a1b2be405c5543ac1febc27af', 'okendo', 'Merrilee A.', 'Amazing Gluten free cookie option', 'The Every Body Eat Chocolate Chip snack is amazingly addictive.   They are light, fluffy and have an amazing flavor that makes it impossible to have just one. The resealable package keeps them nice and fresh.  It you are avoiding Gluten but have a sweet tooth these will certainly hit the spot.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-08', 0, 'No', '', '', '["gluten_free","addictive","packaging"]', 'addictive,texture,flavor,packaging,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
