INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4d6da0909cd8e1e6fe9ec1c1067943eb', 'okendo', 'Lindsay S.', 'So weirdly addictive', 'I love these little crackers as a snack. They have a nice short ingredient list and work well for me with my dairy allergy. They have the best little crunch and taste like real cheese. They easy to grab for a snack when you’re hungry without killing your diet.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-08', 0, 'No', '', '', '["crunch_texture","allergy_friendly","addictive"]', 'crunch,taste,ingredients,snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9c2da7a4c958d6867a158d67c5074a94', 'okendo', 'Mariel R.', 'Healthy and Delicious!', 'I recently tried Chocolate Chip Cookie Bites by Every Body Eat, and they are a delightful little treat. Each bite is perfectly sized, making them great for snacking or satisfying a sweet craving without feeling like you''re overindulging. These cookies are made with wholesome ingredients and have just the right amount of chocolate chips in every bite.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-06', 0, 'No', '', '', '["great_taste"]', 'size,snacking,ingredients,chocolate chips', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ec28d23dea2eac72d8178f627bd842e7', 'okendo', 'Mariel R.', 'Healthy and Delicious!', 'I recently tried Cheese-Less thins by Every Body Eat, and they are delicious! These crackers are light, crispy, and savory. The thin texture makes them especially satisfying-they have a nice crunch without feeling heavy, which makes them easy to snack on. They are healthy and delicious!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-06', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,crispiness,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
