INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('251a0480d11e13bd576d9dbd0d83ee08', 'okendo', 'Alexis N.', 'Not for me', 'This snack just wasn’t for me. I can appreciate the clean ingredients. Being gf, vegan and allergy friendly is wonderful but I didn’t get any cheesy vibes from it. It doesn’t compare to any similar looking cheese cracker snacks. The bag had a great seal and the product was fresh and crispy.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-03-05', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","allergy_friendly","clean_ingredients","packaging"]', 'ingredients,texture,packaging', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0e6862d035cdc21f4029ad77d6bde9d9', 'okendo', 'Alexis N.', 'Better than expected', 'I don’t normally expect healthy options to taste as good as what we’re used to but this was a very pleasant surprise. The cookie was a little powdery but overall I had great flavor. This is a delicious, calorie friendly option when reaching for a sweet treat.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-05', 0, 'No', '', '', '["great_taste"]', 'taste,flavor,calories', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
