INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f8fe188bcc32593bb555cdea5c741e40', 'okendo', 'Kacie M.', 'Good and yummy', 'I really liked these. The taste was nice, even with all of the allergy free items and ingredients they were made of. No word after taste. Just enough sweetness, and a perfect size to pop in your mouth. Crunchy, too. I was really impressed with these.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-04', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'taste,sweetness,size,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4ed318a430617a5de6bf5fb3b8a76139', 'okendo', 'Kelly H.', 'Crunchy, tasty, allergen friendly cookies!', 'Excellent allergy friendly option for a sweet treat! Love the ingredients and I feel good about enjoying them as a snack for myself or my kids. They have a crunchy texture, but have chocolate chips, too, which always satisfies my sweet tooth. I would definitely buy these again!', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-04', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'texture,chocolate chips,ingredients,sweet treat', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
