INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('000fd46b4e3cbb1a743cb0664cb53fbf', 'okendo', 'Kacie M.', 'Good and tasty!', 'These were nice and thin to snack on. Even with the size, they were full of cheese flavor. I like the ingredients, as they are allergy friendly. You get a lot for the serving size!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-04', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'thickness,cheese flavor,serving size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c992bee43c15e00a1dd6b121b75de323', 'okendo', 'Rebecca M.', 'Tasty, gluten-free cookies!', 'These cookies taste great, which is a hard accomplishment for also being gluten-free. The cookie itself is super cute and bite-sized. My only hesitation is that the cookies are a bit on the dry side.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-04', 0, 'No', '', '', '["great_taste","gluten_free","bland_flavor"]', 'taste,gluten-free,size', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e993bee03b11f4b75ac7960929d42227', 'okendo', 'Rebecca M.', 'Healthy, gluten-free. . . Delicious!', 'Shocking to me how healthy these crackers are as they taste amazing! The taste is similar to a Cheese-it but this is gluten-free (yay!) and much healthier! Only downside is that I cannot stop eating them!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-04', 0, 'No', '', '', '["great_taste","gluten_free"]', 'taste,gluten-free', NULL, 'addictive', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a9df6de560a48730e1cc6dc5b325bfe5', 'okendo', 'LYNND', 'Very good snack', 'I received this product in exchange for my honest review.  These are a game changer for a good snack. Fresh and crispy and fulll of flavor. The package is resealable and worked to keep these nice and fresh', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["crunch_texture","packaging"]', 'freshness,flavor,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('eeb578d78aa86b0de62736a585f09298', 'okendo', 'LYNND', 'My husband loved these', 'I received this product in exchange  for my honest  review .  They are very light and crispy which I did enjoy. I am not a huge cheese person so these would not be my first choice. But my husband did enjoy them.. the packing is top notch and let them nice and fresh .  The bag was resealable which we liked as well', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["crunch_texture","packaging"]', 'texture,packaging,resealable', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('33cf68588c236b81f9aa656eebbdac9f', 'okendo', 'Christine M.', 'Yummy gluten-free cheezy cracker', 'I''m always on the search for yummy gluten free snacks that don''t taste like cardboard.  These did not disappoint!  The cheese flavor was very good, mildly bland, but did the trick!  I plan to try the other flavors. The bag did get squashed during shipping so I mostly had small pieces and crumbs.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["great_taste","gluten_free","broken_crumbs","bland_flavor"]', 'gluten free,taste', 'texture', 'cheese flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2053ff86bbcb5eded4586921439a941d', 'okendo', 'Cristina C.', 'Crunchy and chocolaty!', 'I love chocolate chip cookies but they always bother my stomach. These ones taste great, they have fiber and very healthy ingredients that give you nutrition and no tummy issues! They are super crunchy and chocolate without being too sweet. I love themN', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["crunch_texture"]', 'taste,texture,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2b398adfc87dd4a64f063104b24c6e8f', 'okendo', 'Cristina C.', 'Nice cheese crackers', 'I was very excited to try these gluten free cheese cookies and they didn''t disappoint. They are very crunchy and great for dipping! I love all the ingredients and love that they don''t bother my stomach! I would just love that for the price they give more quantity but I think for the quality of the product, they are worth it.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["crunch_texture","gluten_free","value_price"]', 'texture,dipping,ingredients,quality', 'quantity', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5abfa096437019eb902cb0dd24e68da9', 'okendo', 'Aneta K.', 'Molasses chocolate cookie bites', 'These cookie bites are delicious, 5 are only 140 calories. Gluten-free and made in an allergy friendly facility. In every bite, you taste the molasses and grape flavors. Great healthy snack, whether it''s with some coffee in the morning or for dessert later on. I can''t stop eating them they have such a rich crunch to them.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","allergy_friendly","addictive"]', 'taste,calories,texture,snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8da7129d4d9782680c97eac2810d29fb', 'okendo', 'Alba M.', 'Good', 'These toasts are delicious  have a wonderful cheesy flavor, i really enjoyed, them, which is great because i can''t eat too many  carbohydrates and they help', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["great_taste"]', 'taste,cheese flavor,carbohydrates', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('606b364abc9ef8a29022b5121f68c479', 'okendo', 'Tiffany C.', 'Great Taste!! Don’t miss a thing!', 'These are amazing little snack thins!! I can’t believe they don’t have cheese! These are great for people with allergies or even food sensitivity! Taste great and have a wonderful flavor and crunch!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","false_advertising"]', 'taste,flavor,crunch', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5294fa935f0972ed93462f75e135a048', 'okendo', 'Amy L.', 'Tiny cookies packing a punch of crispy goodness', 'These cookies were awesome- yes, “were”!! Past tense, because they were eaten quickly! Crunchy, fresh, taste little chocolate chip nuggets of goodness. Clean eating at their best!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["crunch_texture"]', 'crunchy,fresh,taste,chocolate chip', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d7beefe6ad606fab8e44bb3cee9a85fb', 'okendo', 'Megan G.', 'Guilt free goodness!!', 'Hello guilt free indulgence! I am a sucker for cookies! I really have to stay away from gluten though. These are so good! I have made these my go to when I need something sweet! Excited to try other options this brand has to offer!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["great_taste"]', 'taste,gluten free,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f703b00006bb17c957ccc9ccfa03e353', 'okendo', 'Megan G.', 'So good', 'So good! I love this clean allergen friendly alternative!  I have always loved the typical name brand cheese chip but i really need to stay away from gluten. This has been my go to crispy snack!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","good_replacement"]', 'taste,gluten-free,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('489d144268fa19846bae90c1bfe9e24f', 'okendo', 'Kelly M.', 'Good bite size snack', 'For a cheezits type cracker replacement it was pretty good. the cracker was pretty thin which was good bc it wasn’t super chalky tasting. If I was looking for a gluten-free cheesy cracker again I do think I would repurchase..', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["gluten_free","good_replacement","repeat_purchase"]', 'texture,taste,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('83b0bb1f162dfb9ef705fabd4d08bf7b', 'okendo', 'Nikki Y.', 'They were okay.', 'Received these in exchange for my honest review. These were okay. Literally just okay. The texture was a bit dry and crumbly, the flavor was pretty bland. I didn’t hate them but also didn’t really love them.  They were about what I’ve come to expect for a mass produced vegan cookie.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","bland_flavor"]', NULL, 'texture,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
