INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d118090821a633704d9d3bf86c726204', 'okendo', 'Meredee B.', 'Decent', 'I can''t make up my mind about these cookies. On one hand, they taste pretty similar to those little boxes of cookies they used to sell at McDonald''s, and on the other hand they have a little bit of an aftertaste. I like them enough that it still feels like a treat that isn''t too bad for you. Packaging is nice and attractive. The cookies are decent for the concept.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["packaging"]', 'packaging', 'aftertaste', 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0306774539788057730c3481e43421a5', 'okendo', 'Meredee B.', 'Not yummy', 'These do not taste very good. I could not eat more than a couple. The packaging is nice and I love the idea of the simple ingredients but it just did not taste good.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["great_taste","clean_ingredients","packaging"]', 'packaging,ingredients', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('416935dc2ea5ec0a173f49db639aa43a', 'okendo', 'Nichole J.', 'Yummy', 'These are quite good. They melt in my mouth and have just enough chocolate to be delicious. Looking at them I was worried they would be sandy but they are not. They taste good and are the perfect bite size to just grab a handful and enjoy!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["great_taste"]', 'texture,chocolate,taste,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('316f7a2f7188eca8d86a6cf10626b1c4', 'okendo', 'Nichole J.', 'Excellent crunch', 'These have excellent crunch and texture. I however did not like the orangish color and them being cheese less. The color had me expecting cheese and they were not. Excluding that, they were good. Some of the pieces were already broken in the bag but that could be from shipping. Love they are seed and gluten free!', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["crunch_texture","gluten_free","broken_crumbs"]', 'crunch,texture,seed free', 'color,broken pieces', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e1ad2750a43426d3be8c5ef97deff3c4', 'okendo', 'Stephanie R.', 'Great healthy alternative', 'These were on the dryer side but will go great with any type of milk as a snack. The package stays sealed great to keep fresh. Perfect amount of sweet but not too sweet.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["good_replacement","packaging"]', 'packaging,sweetness', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1ada011393605787d87aa88442f3ce34', 'okendo', 'Stephanie R.', 'Not a fan', 'I wanted to like these but they were a miss for me. They tasted like fake cheese on top of shaved sweet potato skins. The packaging was nice and had a great seal.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["packaging"]', 'packaging', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6352523cd2c7b762f3b636127753c8dc', 'okendo', 'Shoshi R.', 'Light and airy', 'Great ingredients, great portion size and great mouthfeel to these cheese-less thins by Every Body Eat. Cute packaging and excellent nutrition information as well. It almost has a nutty flavoring to it-even though there is no nuts in the product. You can use these as a chip dipper or eat them straight out of the bag. Whatever way that you decide to eat them, enjoy!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-03', 0, 'No', '', '', '["packaging"]', 'ingredients,portion size,mouthfeel,packaging,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8a7f4b78b50d993db12ddb9a6e6393a8', 'okendo', 'Shoshi R.', 'Oats everyday', 'Love these bite size cookies from Every Body Eat. They are chocolate chip cookie bites made with oatmeal. So it’s like a delicious mouthful bite after bite. Great mouthfeel as well and I love the consistency of the cookie. It is a very substantial and filling bite even though the size is bitty. I would definitely like to try the other varieties from their product line as well.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-03', 0, 'No', '', '', '["great_taste"]', 'size,texture,filling,flavor,oatmeal', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('981092d679cca66630b4abcbc7397c15', 'okendo', 'Julia M.', 'The crunch and texture reminds me of a specific bl', 'First of all, my younger kids (6 & 8) got in to these before I could even get a chance to open the bag. They ate a few and said they were good. The 6 year old has crumbled one over her yogurt a few times now and says it’s really good. The little ones are not strictly dairy free like I am (due to allergies and SIBO). 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3f51c2a4438508ae825ad5e29d64491a', 'okendo', 'Julia M.', 'Good vegan ‘cheesy’ swap for crunch snack crackers', 'I am allergic to shellfish with a mild allergy to dairy, garlic and egg white (mild on labs from allergist) and have non celiac gluten sensitivity. And thanks to a long bout of SIBO for the past two+ years, dairy is a serious no go for that condition. I was excited to try these as I am a savory snacker and am limited tremendously these days. I ate the whole bag in one night, with my sons while watching a show. I paired it with a store bought dairy free dip but we didn’t even need it to hide any gross flavor, that we were expecting. They were good, thin and very crunchy….all my favorite things about a savory snack and I will purchase these when I see them for snacks. The addition of the salt pieces were needed for flavor to replicate a salty savory snack.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-02', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","allergy_friendly","good_replacement"]', 'texture,flavor,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('48872f30212210e1bd430ac608e723b8', 'okendo', 'Marki B.', 'Good cookies', 'Very good cookies that taste great. Good size package that is resealable. Good ingredients list that are perfect for anybody even those with allergies', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-03-02', 0, 'No', '', '', '["allergy_friendly","packaging"]', 'taste,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ff757a8c04e44ac9408c90ab6e35e3b3', 'okendo', 'Marki B.', 'Very good snack', 'Package all emptied in one time. It was a good snack and the ingredients list is good. Perfect for anybody and those with dairy allergies since it is a dairy free snack.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-03-02', 0, 'No', '', '', '["dairy_free_vegan","allergy_friendly","packaging"]', 'taste,ingredients,dairy free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('116a8279c58d72a44b23699860d91cca', 'okendo', 'Manisha P.', 'Addictive and delicious!', 'Theses cookies are bit sized and can be eaten as a snack or dessert. I love that there are clean ingredients so you dont feel as guilty eating them. They taste similar to the Siete chocolate chip cookies. The texture is crispy, hard at first, but they crumble in your mouth.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b9e98a2b771c91d454455dc071c5221c', 'okendo', 'Sarah B.', 'Sweet tooth snack', 'These are super yummy and a great alternative to store bought cookies! They’re bite sized which is nice and they definitely are good when you’re having a sweet tooth. They’re bite sized look a little off putting, they’re definitely not “perfectly” shaped but they taste good. They have a slight aftertaste but nothing too crazy and definitely easy to ignore if you are prepared for it', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-03-02', 0, 'No', '', '', '["great_taste","good_replacement"]', 'taste,size', 'appearance,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5c96d11a5b97a12b64bdbb152ea48488', 'okendo', 'Denise P.', 'A good gluten free substitute.', 'The cookies were okay. I thought they tasted nice but they were powdery and disintegrated pretty easily. They came in bite sized pieces. The texture was slightly grainy it tasted like a gluten-free cookie. If I had to have it again I would but if I had another choice I wouldn''t.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2026-03-02', 0, 'No', '', '', '["crunch_texture","gluten_free","good_replacement"]', 'taste', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5dc2d595f732993c4a95b7b54393b26f', 'okendo', 'Zamira N.', 'Very yummy snacks to go', 'Nice warm cinnamon and ginger flavor. Not too sweet with good chewy texture. Great as quick snack or coffee. Overall my whole family liked it and ate the whole thing.  They taste very good not to sweet for those who don’t like sweet snacks or on strict diet.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-28', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'flavor,sweetness,texture,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
