INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dd740798fb8edadafab6a56694c2b258', 'okendo', 'Pri B.', 'Very healthy crispy snack', 'I loved this snack so much in recent times. It is healthy tasty and super filling. I like to eat these on the go as well as with a dip. It goes well with any type pf dip. The package could contain a little more quantity in my opinion but overall a great pick for the health conscious people', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-28', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'taste,filling,portability,versatility', 'quantity', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('38f4bf8100ed4fb07ce87a854a514bdb', 'okendo', 'Denise U.', 'Delicious Chocolate Cookies', 'I absolutely loved this product! I couldn’t stop eating them, because of the crunch. Every bite was delicious and had a good amount of chocolate chips. When you open the bag you can smell the chocolate aroma. I would definitely recommend this product.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-28', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunch,taste,chocolate chips,aroma', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('95e8690740cd9dfbe942ad93f44c040d', 'okendo', 'Denise U.', 'Cheese-less thins', 'I received this product in exchange for my fair review. The product packaging was a plus. It’s kept the product fresh, however I didn’t like the taste. When I first opened the bag you could smell the garlic. I really wanted to like the product but the overwhelming taste of garlic was not good.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-28', 0, 'No', '', '', '["packaging"]', 'packaging', 'taste,garlic', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
