INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('712f437f012fefaa92198d990fefe635', 'okendo', 'Susie W.', 'Mid', 'These crackers are thin and crispy and smells cheesey. It has a cheesey taste at first bite, but I did not enjoy the after taste. I know it’s a healthy version of any type of cheese snacks so you won’t get an explosion of flavor. I wouldn’t buy it again.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-28', 0, 'No', '', '', '["crunch_texture"]', 'texture,smell', 'flavor', 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0d311da0f907b01ab623d7564667b249', 'okendo', 'Tina D.', 'Crunchy little bites of joy-simple, light and snac', 'These crunchy cookies are definitely true their name-firm, crisp and allergy-friendly. The texture is satisfying and they make an easy grab-and-go snack. The flavor is mild and simple, more of light treat than a rick cooki but they work well if you want something crunchy without heaviness.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-27', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'texture,convenience,heaviness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('481175af85d7e4513b7a33b26cbe7b62', 'okendo', 'Alise H.', 'Healthier sweet treat!', 'Every Body Eats Chocolate Chip Cookie Bites are a great alternative to regular cookies. The ingredients are healthier than a typical cookie which make for the perfect sweet treat!', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-26', 0, 'No', '', '', '["good_replacement"]', 'taste,ingredients,alternative', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
