INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d5bda3bf1de0f9580c16f0a55a0725f7', 'okendo', 'Ashley G.', 'Covered in crumbs, but tastes great!', 'These look like cookie dough bites due to the shape and the huge amount of crumbs clinging to them. They taste like a very famous cookie brand with the name “chips” in it. Overall a great chocolate chip cookie. Will probably buy again.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-26', 0, 'No', '', '', '["repeat_purchase","broken_crumbs"]', 'appearance,taste,texture', 'crumbs', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c029abde630f2b5593ecc7a6a693635b', 'okendo', 'Ashley G.', 'Crispy and salty', 'These ALMOST taste like they’re made with cheese. They are crispy and salty. I love that they’re made with allergy safe ingredients. When they arrived, they were mostly crushed, so I only got to eat a few whole crackers. My picky kid actually likes them.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-26', 0, 'No', '', '', '["crunch_texture","allergy_friendly","broken_crumbs"]', 'taste,texture,kid appeal', 'packaging', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1cf20b1c5ef56c4ae7597c5d66e9a486', 'okendo', 'Andrea D.', 'Great dairy free alternative', 'These crackers have a very cheesy flavor and crunchy texture while be dairy and gluten free.  A great alternative for a cheesy, crunchy cracker for those of us that can’t have dairy or gluten.  They have that thin, baked texture and just a handful is a satisfying snack.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-25', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","good_replacement"]', 'cheesy flavor,crunchy texture,dairy free,gluten free,satisfying snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('36d88b1e82c16d7802b50d5a141244f5', 'okendo', 'Andrea D.', 'So good!', 'These cookies are so good!  They taste just like those other bite size “famous” cookies!  I love that they are gluten and dairy free too.  Great flavor and crunchy texture.  My only issue is finding them in stores so I can get more!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-25', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan"]', 'taste,flavor,texture,gluten free,dairy free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
