INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('debf7df2cfbf3dcf624f027f61889e6f', 'okendo', 'Alyse W.', 'GF/DF friendly option for a sweet treat.', 'For a GF/DF option, these aren’t that bad. My little guy loved them so much, he finished the entire bag over the course of a week as his after-school snack. Same texture & crumb as a regular cookie. Was nice & crunchy yet chewy at the same time. Not sure we’d buy them in our own, but they were great for a treat.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-24', 0, 'No', '', '', '["crunch_texture"]', 'texture,taste,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4f8ff6d97830e708fb291a46aa6ea95d', 'okendo', 'Jennifer G.', 'Decent allergy friendly snack.', 'The Every Body Eats Chocolate Chip Cookie Bites is an okay snack especially if you are looking for gluten and dairy free. Size is great for snacking but they can taste a bit dry.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-24', 0, 'No', '', '', '["dairy_free_vegan","allergy_friendly","bland_flavor"]', 'size,gluten free,dairy free', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
