INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cc64371c89259f2605c0b10c1ba5020c', 'okendo', 'Cozy B.', 'Love these', 'LOVE THESE!!!  I am a huge ingredient reader, and these pass my test!! I love that they have no seed oils. I feel comfortable eating these and sharing them with my toddler, too!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-24', 0, 'No', '', '', '[]', 'ingredients,seed oils', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('51aed60553a97243aec08d454b9882d2', 'okendo', 'Mayra M.', 'Chocolate chip', 'Very good cookies, love that they are a very clean in ingredients so the tastes of the cookies are true and trustworthy. They definitely do not have an aftertaste and you just want to eat more and more of them. 10/10 definitely recommend.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-23', 0, 'No', '', '', '[]', 'taste,ingredients,quality', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2702b167647722f89525344c2414d3e0', 'okendo', 'Sara H.', 'Not very cheesy', 'I personally did not love the cheese-less thins from Every Body Eat. The texture was a little weird to me and they were very garlicky. They definitely are not the worse thing, just not for me. The pros of this snack is it is gluten free, vegan, and allergy friendly. Also 17 crackers is only 140 calories which is a pretty large serving size. Overall I think these crackers would appeal to some people, just don’t expect a very cheesy taste.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-23', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly"]', 'calories', 'texture,garlic,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6d821d41f19ea63f69bb2ffdf527f0af', 'okendo', 'Sara H.', 'Great healthy alternative', 'For a healthy cookie that is gluten free, vegan, and allergy friendly, I think the Every Body Eat cookies are pretty good. The texture is a little weird at first, kind of powdery, but didn’t really bother me. I appreciate that 5 cookies is only 140 calories. The resealable bag makes this an easy snack to take with you on the go. For healthy alternative cookies, I think this is one of the better options on the market.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-23', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","good_replacement","packaging"]', 'calories,packaging,taste', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f8ba8ac43dcf68f16292354dc0ae7774', 'okendo', 'Bethany M.', 'Healthier alternative', 'These were ok but we didn’t love the texture and after taste. They are a healthier alternative to snacking but you definitely notice the difference.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-22', 0, 'No', '', '', '["crunch_texture","good_replacement"]', NULL, 'texture,aftertaste,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
