INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('343db6c3f26a85d255d0e1b389bff8b7', 'okendo', 'Mariyam F.', 'Chocolate chip cookies bites size', 'This chocolate cookie bites are very tasty chewy bites, and perfectly sweet. Each bites rich worth chocolate chips that melts in mouth giving home made taste great lunchbox bite size satisfying for sweet cravings. The rich taste and texture is moist without being greasy and the sweetness is balanced.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-22', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,sweetness,size,chocolate', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b2c17e912ff3fd621d7b96c589366dbf', 'okendo', 'Mariyam F.', 'Choose no Cheese', 'Cravings no way easy snacks for light hunger. cheese less and fully bold cheese flavored without cheese plant based snacks & salty taste crisp bites. They are perfect crisp, not too oily and make a tasty guilt free snacks.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-22', 0, 'No', '', '', '["great_taste","crunch_texture","stale"]', 'cheese flavor,crisp texture,oily,salty taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
