INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b51f1ce4a87b2676b22fb949bf45149e', 'okendo', 'Laynie L.', 'Like a Healthy Chips Ahoy', 'The chocolate chip cookie bites from Every Body Eats are okay. They kind of remind me of a chips ahoy, but less flavorful. I do like the amount of chocolate chips in them and the crunchy texture. They make a pretty okay snacks if you are craving cookies but want something a bit healthier.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-20', 0, 'No', '', '', '["crunch_texture"]', 'chocolate chips,texture', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('998ff58fdf7414179caccaa68d38e340', 'okendo', 'Laynie L.', 'Not Very Flavorful', 'None of my family really enjoyed the Every Body Eat Cheese-less Thins. They’re pretty flavorless. My husband commented that they need more salt and paprika. I just sat here and mindlessly ate a bunch and they left me unsatisfied. But they do have a tiny bit of spice. I do not see me buying these as a snack for me or my family.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-20', 0, 'No', '', '', '["bland_flavor"]', 'spice', 'flavor,salt,paprika,satisfaction', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('577b39347c88eee97bf8c5f09c3c4310', 'okendo', 'Kenadie Hess', 'The Best', 'I don''t usually eat snacks in general till my mom bought these and wanted me to try them. I''m obsessed with these now! I now snack on these and eat them as an dessert as well!', 5, 'positive', 9, 'Cookie Bites Variety Pack', '2026-02-20', 1, 'Yes', '', '', '[]', 'taste,snacking,dessert', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('91ed10f1d85e6d734dc79601c258dc84', 'okendo', 'Dinorah M.', 'Sugar needs to be reduced', 'The packaging is pretty nice and the crunchy consistency is also a good reason to eat them, so they do not melt thats easy. one thing is that even do it seems like a healthy snack one of the ingredients which is the sugar should be reduced. Also it has a small fake flavor but overall if you have food allergies this snack can be your option.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-20', 0, 'No', '', '', '["crunch_texture","allergy_friendly","packaging"]', 'packaging,texture,melting', 'sugar,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
