INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('618047e14199c13c2bbe43606fa39831', 'okendo', 'Janell L.', 'So delicious', 'Love this product from taste to texture ,size/shape and cheesiness. Bold packaging gives a very appealing look. The bag is great for on the go and storing . Very durable and appetite friendly', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-20', 0, 'No', '', '', '["great_taste","crunch_texture","packaging","stale"]', 'taste,texture,size,cheesiness,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2cc06ab4bf9e1dd1a8c32efebd77b54e', 'okendo', 'Mahya B.', 'Crispy but strange after taste', 'These crisps were okay. I loved the crisp to them but they leave a strange aftertaste. They are lightweight and have decent flavor. They aren’t my favorite but they are okay.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-20', 0, 'No', '', '', '["crunch_texture"]', 'crispiness,weight', 'aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d5e7c8504629e87b14d3221799ac3f2b', 'okendo', 'Erica D.', 'Not bad', 'These cookies were not bad tasting. They taste and have the consistency of Tates cookies. Not a bad choice for a “healthier” cookie and if you have certain allergies.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-19', 0, 'No', '', '', '["allergy_friendly"]', 'consistency', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e8d8d2500fcfd3fa4d8a484cd8a5ad60', 'okendo', 'Erica D.', 'Disgusting', 'These crackers tasted nothing like cheese. My kids refused to eat them and I didn’t enjoy them either. Ended up throwing the box away. I couldn’t get past the flavor and after taste.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-19', 0, 'No', '', '', '[]', NULL, 'cheese flavor,flavor,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('92b2676cba452ba69bca1ee2f52b479d', 'okendo', 'Kathryn Smith', 'New favorite', 'I just love these flatbread crackers. They are nice and crunchy and have so many flavors mixed into one yummy cracker. They''re sweet, slightly salty, nutty, with a hint of cinnamon. Just a great combination. I hope i never run out again!', 5, 'positive', 10, 'Cranberry Crispbread Crackers', '2026-02-19', 0, 'Yes', '', '', '["great_taste","crunch_texture"]', 'texture,flavor,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('161f3e359eac5dff3c35b4af7307351b', 'okendo', 'Kelly D.', 'Crumbly but tasty. Needs more chocolate', 'I was a bit hesitant taking one out of the bag. It has the texture of sawdust on the surface. But alas, the taste was surprisingly delicious. I like miniature size.  They have almost a nutty flavor but don’t have nuts. The packaging is misleading on the amount of chocolate chips.  You might see one per cookie, but advertising is always misleading. It’s nice that they aren’t filled with a bunch of junk and preservatives, but they are nice and crunchy in their zipper bag. This is a great option for those with gluten issues.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-19', 0, 'No', '', '', '["great_taste","crunch_texture","packaging","false_advertising"]', 'taste,size,gluten free', 'chocolate chips', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0dfac102374e15aa29963f7055d1bf2b', 'okendo', 'Kelly D.', 'Very bland, but allergy friendly', 'I think a Hallmark card would be probably be just as tasty. These are bland and chalky.  I was hoping for a salty, cheesy flavor, but nope.  They are very crispy, but so is a wood chip. It’s nice that they are baked, not fried, but that didn’t help the taste.  They really don’t have much flavor or order.  Just bleh.  I’m sure if you had allergy issues maybe this could be a nice option, especially if you dip them in something.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-19', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","bland_flavor"]', NULL, 'taste,flavor', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('239686fdac86f8711d0235c13ea1781c', 'okendo', 'Jennifer W.', 'Great ingredients', 'These cookie bites were sweet and a little crunchy. I liked them being bite sized. I also love that they are gluten free and have simple ingredients listed. This is a nice healthier cookie.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-19', 0, 'No', '', '', '["crunch_texture","gluten_free","clean_ingredients"]', 'sweetness,texture,size,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
