INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f8fbb5baddf9356d43e89582a933138e', 'okendo', 'Lina M.', 'The tastiest thins', 'These cheese less thins taste incredible. Super crunchy and crispy. The aroma is on point the taste a little less heavy than regular ones but soo good. We ate them in a day', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-19', 0, 'No', '', '', '["crunch_texture"]', 'taste,texture,aroma', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d4460edfee4f70b90a7e02dc4e2190f3', 'okendo', 'ANGELLAC', 'Perfect for when you need something sweet', 'Healthier chocolate chip cookies! These taste very very similar to the popular brands but with better ingredients. The texture, crumbling, the flavor, the aftertaste... All very similar to the popular brands we are all familiar with. The difference is that it appears to be healthier for you. There is no shocking aftertaste or bitterness. These are just as sweet as the other popular brands and hit the spot when you have a sweet tooth!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-19', 0, 'No', '', '', '["crunch_texture"]', 'taste,texture,flavor,aftertaste,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e4b5c880ecdc0c5c87185e27c5373ec3', 'okendo', 'ANGELLAC', 'Great healthy cheese crackers!', 'I love cheese crackers and these definitely hit the spot! Super crunchy- almost akin to vegetable chips but with extra crunchiness with the cheesy hit. They''re perfectly salted and appear much thinner than other cheese crackers I''ve seen. The packaging is surprisingly sturdy enough to keep the squares intact. Recommend!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-19', 0, 'No', '', '', '["crunch_texture","packaging"]', 'crunchiness,cheese flavor,salt level,thickness,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
