INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d9caf86b690f19327e13311d594cc053', 'okendo', 'Christine M.', 'My new favorite Gluten free/clean ingredient cooki', 'Not much to look at but these little cookies are DELICIOUS! I couldn''t stop eating them and almost devoured the entire bag of cookies before I took this picture. These cookies are a bit crunchy, which I typically don''t prefer, with an addictive flavorful taste.  I''m excited to have discovered these gluten free cookies with clean ingredients!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-19', 1, 'No', '', '', '["great_taste","crunch_texture","gluten_free","clean_ingredients","addictive"]', 'taste,gluten free,ingredients', 'texture,appearance', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('85363a325d4fddce8643709bd6437284', 'okendo', 'Hiral B.', 'Tiny little tasty bites', 'Tiny little guilt free and tasty bites option. We all loved it and packed conveniently to take on the go as well. Very crunchy and nice bite size. Definitely made with the quality ingredients and tastes great afterwards. Chunky chocolate chips are loved by my kids.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-19', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,portability,ingredients,chocolate chips', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
