INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('096a14860b7906b8a0dada260a3b34a4', 'okendo', 'Becky R.', 'Taste amazing!', 'The Every Body Eat Cheese-less Thins are truly a new standard for inclusive snacking. As a vegetarian with multiple family members who have allergies or dietary restrictions, I love that we can all eat these. As an added bonus, these taste amazing with no aftertaste. I think they taste just like regular cheese crackers but with a crisper, crunch. The ziplock pack is super convenient as well.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-18', 0, 'No', '', '', '["crunch_texture","allergy_friendly","packaging"]', 'taste,texture,packaging,vegetarian', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
