INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('12044bd58445031f63bf601b8cbe9484', 'okendo', 'Nhai N.', 'I love it', 'The ingredients are clearly listed and all are good. Packaging so nice and easy to use. The cake is soft. The cake is soft and crispy. Delicious flavor.  The cookie crumb were all over my mouth', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-18', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'ingredients,packaging,texture,flavor', 'crumbs', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5c1cba0fe8474dd40499142fc7bf8faf', 'okendo', 'Nhai N.', 'I like it', 'The cookies are crispy and easy to eat. So good. The product is good for your health. Beautiful packaging and easy to use. The ingredients are clearly listed and all are good.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-18', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'crispy,packaging,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bb866b0fec27b28ad6ab8382537d0a46', 'okendo', 'Tram N.', 'Yummy', 'Chocolate chip cookie bites are the perfect treat when you are craving something sweet but don’t want a full-sized dessert. Each bite is packed with rich chocolate chips that melt perfectly in your mouth.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-18', 0, 'No', '', '', '["great_taste"]', 'size,chocolate chips,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('36e8210194f02590c3662442b7c32a1e', 'okendo', 'Tram N.', 'Yummy', 'If you are looking for a light, crispy snack, that still delivers bold favor, cheese thin chips are a fantastic choice. From the first bite, you get a satisfying crunch followed by a rich, savory cheese taste.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-18', 0, 'No', '', '', '["great_taste","crunch_texture","stale"]', 'texture,flavor,crunch', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7621b3791cd14bb8075935bb2cff7783', 'okendo', 'Tracie A.', 'Delicious, melt in your mouth, gluten free delight', 'Gluten Free, bite size Chocolate Chip Cookies that won’t make you feel like you need to hit the gym? Yes PLEASE!! These little gems are AMAZING! I am usually hard pressed to find a good gluten free cookie that’s not akin to a hockey puck, and these cookies just melt in your mouth. They are the perfect size to have a few when you just need that little something sweet. So delicious!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-18', 0, 'No', '', '', '["great_taste","gluten_free"]', 'gluten free,texture,size,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('99cb69aada8ae36799721bf77d1a764a', 'okendo', 'Tracie A.', 'Amazing “Cheesy”, Crunchy, “Non” Guilty Pleasure!', 'As a someone who has a gluten sensitivity, and is a strict vegetarian, I was super impressed with the flavor and texture of these gluten free, vegan crackers! They were so delicious and crunchy! They satisfied that need for a cheesy snack without the guilt. Fantastic, clean ingredients, with a side of “non”guilty pleasure!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-18', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","clean_ingredients"]', 'flavor,texture,ingredients,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a1927d8bb3da9299380813f27f77d025', 'okendo', 'Amna M.', 'Pretzel', 'In my home every body eat a pretzel, this yhin give a delightful delicious taste. They are gluten free grain free and allergic people its a great option enjoy this crunchy aromatic saltiness pretzel with your favourite dips.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-17', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","allergy_friendly"]', 'taste,texture,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('070422827ba4c4596b04894f8f62acc2', 'okendo', 'Amna M.', 'Ginger cinnamon', 'These ginger cinnamon cookies are like a treat,a blend with ginger and cinnamon is like a warm and the combination of crunchy and chewy make a satisfying bites on every time, to cookies are good portion for small treat this flavour is mouthfeel good.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-17', 0, 'No', '', '', '["crunch_texture"]', 'flavor,texture,portion', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bc3862c21e482db29f33934f92169a97', 'okendo', 'Annette Bjorling', 'Great introductory sampler for friends', 'I have been loving these everybody eat thins for several years now. And I want to introduce as many friends as possible to them… I love this variety pack for this purpose. I showcases great different flavors, and there should be at least something to like for everyone…. I also like ordering them for myself, since I want a bit of variety at home.', 5, 'positive', 5, 'Snack Thins Variety Pack', '2026-02-17', 0, 'Yes', '', '', '[]', 'flavors,variety pack,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6be19423765eef2e097578318b3dee9f', 'okendo', 'Annette Bjorling', 'Fabulous new snack,  better than  “conventional ”Brezel Thins', 'I loved them from the first bite. Crunchy, and such a great Brezel-flavor.  And I liked them better than formerly “conventional” Brezel-Thins, made with flour and other less-good-for-you ingredients. Yes, I might miss the Brezel-shape, but flavor and texture and healthy ingredients well make up for that…  — Will buy those again and again…', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-17', 3, 'Yes', '', '', '["crunch_texture"]', 'crunchy,flavor,texture,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c85e90fe93056641bb123159b63c8648', 'okendo', 'Mehreen A.', 'Cheesy without the cheese', 'I tried the cheese less thins and they are good . They are perfectly crispy and light with a bold “cheesy” flavor . I love that they are baked and not fried , They feel lighter but super satisfying. They are great on their own or with dips . overall good but I really don’t like the afterwards taste but my family loves it .', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-17', 0, 'No', '', '', '["crunch_texture","stale"]', 'crispy,flavor,baked', 'aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7df4385254d6f6316dc4abb13e851074', 'okendo', 'Mehreen A.', 'So crunchy and Guilt free', 'I have recently tried this chocolate chip cookies bites and I love it . The texture is perfectly crunchy without being too hard and the chocolate chip add just right amount of sweetness in every bite . They taste clean and not overly sugary also I like that they are gluten free . The melts on your tongue gives a perfect flavor. They bite size pieces are great for portion control . Do try it guys .', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-17', 1, 'No', '', '', '["crunch_texture","gluten_free","texture_issue"]', 'texture,sweetness,taste,flavor,portion size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('97250e96ac074fc43dc1a90c0d9cf3ca', 'okendo', 'Jessica B.', 'Good and Tasty', 'Crispy and crunchy!  They are pretty good, and good for you. They are gluten and allergy free, so that’s a good thing.  I’m not a crunchy cookie fan, but these were pretty decent. It was a good size package. It’s probably not something that I would eat on a regular basis, but would buy if it was on sale.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-17', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","packaging"]', 'texture,taste,package size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('65d462abb0c9a00c9a06e995b49cddfe', 'okendo', 'Jessica B.', 'Crispy and crunchy!', 'They were very crunchy. They had a kind of cheesy taste. It wouldn’t be something that I would eat on a regular basis, but maybe if it was on sale. They don’t have a lot of preservatives in them, so that’s good. Crispy and crunchy!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-17', 0, 'No', '', '', '["crunch_texture"]', 'crunchy,preservatives', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
