INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('45531e948b3e3f426fd4de99b17ce1ca', 'okendo', 'Karen D.', 'Surprisingly Good for Dairy-Free!', 'They’re light, crispy, and have that savory, cheesy vibe without any dairy. Perfect for snacking on their own or pairing with dips. Super simple, clean ingredients too which I love.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-17', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","clean_ingredients"]', 'texture,flavor,dairy-free,ingredients,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a5372a63fb0649e846918661b53656fe', 'okendo', 'Parm K.', 'Nice bite size cookies!', 'These cookies are bite size. They were exactly the same texture looking feel as they were on the packaging. They were mostly intact. The reason I gave it four stars and not five because I’m not a very big fan of tasting oatmeal. But I have to say they were nicely sweet not overly sweet.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-17', 0, 'No', '', '', '["crunch_texture","packaging"]', 'texture,sweetness', 'oatmeal', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5eb44c82a5c1f0c6d30d82a76d5a41fb', 'okendo', 'Parm K.', 'Nice thin chips !', 'These are exactly as they are advertised. First time ever I found a product that’s exactly the same size. Feel look in texture as it is pictured. The bag itself is easy to close after use. Chips were mostly intact. They do tasted like real cheese and light.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-17', 0, 'No', '', '', '["crunch_texture"]', 'size,texture,packaging,condition,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2c57de1c738e887e0d00a6e71abc27e7', 'okendo', 'Krystal R.', 'So good, they were gone too fast', 'I wish I had a picture of these, but my son ate them so fast I didn’t have a chance to get one! He said they were perfect crispness and described the taste as a cheesy tortilla chip. Would definitely purchase these in the future.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-16', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crispness,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4ea6951a50e4a6e19f95ed7b3611faf9', 'okendo', 'Krystal R.', 'Bite sized and crispy', 'Very crunchy. Bite sized pieces with just enough chocolate to add flavor. They kind of crumble as you eat them and left a weird aftertaste for me. I’m not really a fan, but they were okay.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-16', 0, 'No', '', '', '["crunch_texture"]', 'size,chocolate', 'aftertaste', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7394cb2b4d634e91ef3306af3bdad78d', 'okendo', 'Mayra M.', 'Clean ingredients', 'OK, these snacks were fabulous. However, I did not appreciate that. My phone did not record the video I made about this product. They are crispy. They do taste like cheddar yet with sweet potato. It’s a given a whole different kind of vibe of combination of flavors but for it to be clean the way it is cleaning ingredients. I appreciate it and I like it.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-16', 0, 'No', '', '', '["crunch_texture","clean_ingredients"]', 'crispy,cheddar flavor,sweet potato,flavor combination,clean ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7ec7b55100f528d3e9098179d891d92a', 'okendo', 'Amy K.', 'Pretty good.', 'These were pretty good for a crunchy gluten free cookie. The little bite-sized cookie was easy to eat for a quick snack. The aftertaste isn’t awful. They look and smell like a real cookie just without the allergens.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-16', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly"]', 'texture,size,appearance,smell', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b6336dc54ff73946829f2ff9684d1d07', 'okendo', 'Amy K.', 'Not a fan.', 'I was not a fan of these. I didn’t think the “cheese” flavor was even close to an actual cheese. It also left an aftertaste that wasn’t great. They are thin and crunchy which is nice.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-16', 0, 'No', '', '', '["crunch_texture"]', 'texture', 'cheese flavor,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b555f3f6490407a7952abc6b4d78767b', 'okendo', 'Caryn H.', 'Tasty snack', 'I just tried Everybody Eat Chocolate Chip Cookie Bites and they did not disappoint. They’re soft, chewy, and packed with real chocolate flavor in every little bite. I love that they’re perfectly portioned so I can grab a few without overdoing it, but let’s be honest, it’s hard to stop at just a handful. Such a good sweet treat when I’m craving something chocolatey but not too heavy. These are very crunchy cookies by the way. Not Moist.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-16', 0, 'No', '', '', '["great_taste","crunch_texture","addictive"]', 'chocolate flavor,portion size,heaviness', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dd06f85cd3183f9a51d3c803f0f1eb9c', 'okendo', 'Caryn H.', 'Tasty', 'I just tried Everybody Eat Cheese Less Thins and I’m honestly impressed. They’re super light and crispy with that savory, cheesy vibe without actually being heavy or greasy. I love that they give me that crunchy snack fix without feeling weighed down after. Perfect on their own or dipped in hummus. Definitely a new go to in my snack stash. I love that they are baked and not fried!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-16', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture,taste,heaviness,versatility,preparation', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f98893a98fd3df94a2f43be77ead0824', 'okendo', 'Susan S.', 'It meant all my allergy needs without missing the', 'Amazing ingredients the crumbling was just the perfect aroma off the chain the size of portion so generous and so delicious. It’s a no-brainer.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-15', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'ingredients,texture,aroma,portion size,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7e3e68264b66982be927ce7fd1b94124', 'okendo', 'Alice D.', 'Delicious', 'These chocolate chip cookies are excellent because, first of all they are made with clean ingredients . They are easy to digest and taste great:', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-15', 0, 'No', '', '', '["great_taste","clean_ingredients"]', 'ingredients,digestibility,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('172c02a902888276b225d4960115d759', 'okendo', 'Alice D.', 'Great snack', 'I love this snack because it’s excellent and it’s made with extremely clean, toxin-free ingredients  it’s baked which makes extra crispy . I recommend it.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-15', 0, 'No', '', '', '["crunch_texture"]', 'taste,texture,baking', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('31edb839a7ccae3f73b23d94f4213272', 'okendo', 'Oxy R.', 'Good', 'I love this snack. Perfect for long road trips that will fuller your entire family. Kids love it. Crunchy structure is easy to eat even for babies.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-15', 0, 'No', '', '', '["crunch_texture"]', 'taste,portability,texture,kid friendly', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ef2f46d97540f1a503a0906bd2de5000', 'okendo', 'Kerida F.', 'Such a creative way to do a sweet treat', 'This was a crunchy cookie. Not overly sweet and sugary. I can taste the molasses and cassava in this snack. This was so creatively done that I became so interested in trying  the other flavors. My kids enjoyed them too without the sugar rush.i can’t wait for my order to arrive because I had to try the others. You will not be mad for trying this. Some how it just taste like healthier alternative for a cookie lover making better choices or someone who has guest over and want to give a snack with no worries of allergies.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-14', 0, 'No', '', '', '["crunch_texture","allergy_friendly","good_replacement"]', 'texture,sweetness,molasses,cassava,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d5f773eb460a50156ef6a6172da8da1f', 'okendo', 'Kerida F.', 'Really good savory snack without the guilt!', 'I really enjoyed this more then I thought I would. These snacks didn’t stand a chance from the day they were delivered!  It was the prefect savory snack. I really enjoyed the taste of the garlic, sea salt and  white pepper. It is super thin cheese like crackers. It’s made from really cool ingredients everyone can enjoy! The intention was to make something free from allergens most people have and they nailed it. I’ve already ordered more! It can be found on there site and even Walmart.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-14', 0, 'No', '', '', '["allergy_friendly"]', 'taste,texture,flavor,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2e90092ef167e981e09a40d8fea9b75d', 'okendo', 'Sarah B.', 'Good not great', 'These are super interesting! I love the crunch and how satisfying they are, the one thing that throws me off is when it says “cheese less” even though it said that my brain expected some cheese flavor and there definitely isn’t any cheese flavor. They have an interesting flavor and after taste that’s hard to describe but isn’t unpleasant just unique. Overall they’re a great snack to grab if you just want something crunchy that is healthier than chips', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-14', 0, 'No', '', '', '["crunch_texture"]', 'crunch,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2c3aee4757327372369eeb7b36071fe5', 'okendo', 'Mary A.', 'Tastes like cookie dough!', 'So good! Something about these remind me of eating cookie dough the little bites are so satisfying and cute, and such a plus they are seed oil free!! Very crunchy as well', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-14', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,size,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f0f693ab9e4ecd21de177a5b4b5f3474', 'okendo', 'Mary A.', 'So good!', 'These yummy cheese-less thins have a great crunch and such a bold flavor, a perfect after work snack ! I also love packing these to work to much on inbetween patients instead of giving into staff candy or donuts', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-14', 0, 'No', '', '', '["great_taste","crunch_texture","good_replacement","stale"]', 'crunch,flavor,snack,portability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b48a1105d259387d996610a892b0bfdc', 'okendo', 'Susie W.', 'Great for those with allergies', 'My 9 year old son is allergic to almost everything. He ate this bag up in one sitting. It is a great snack size bag and I love that it has clean ingredients.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-14', 0, 'No', '', '', '["allergy_friendly","clean_ingredients","stale"]', 'ingredients,size,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('631cf7411543fd8b51f71a5dc5b5acf2', 'okendo', 'Rehana A.', 'Delicious Every Body Eat™ Chocolate Chip Cookie Bi', 'These cookies are soft, sweet, and packed with chocolate chips real cookies flavor in every bite. Perfect snack anytime. What I love most is that they are made with clean, simple ingredients like oat and cassava flour, maple and cane sugar, flaxseed and chocolate chips no artificial junk or highly processed oils.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-14', 0, 'No', '', '', '["great_taste","clean_ingredients"]', 'texture,taste,chocolate chips,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a40cb5e5ffc291709b73d71701941b55', 'okendo', 'Rehana A.', 'Love these Every Body Eat® Cheese-less Thins!', 'These are crispy, savory and flavorful without the dairy, perfect for snacking pairing with dips. Great plant based option that actually tastes good.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-14', 0, 'No', '', '', '["crunch_texture"]', 'crispy,savory,flavorful,dairy-free,plant based', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a3449265fa0404d8ac96690d86f20ae0', 'okendo', 'Ken Harpster', 'Review', 'Delicious flavor, clean ingredients, great product!', 5, 'positive', 3, 'Fiery Chile Lime Snack Thins', '2026-02-14', 0, 'Yes', '', '', '["great_taste","clean_ingredients"]', 'flavor,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b03aa39b7643b3415cfe19a36eb66bab', 'okendo', 'Angela S.', 'Good little snack', 'These are bite size little snacks that are great for people with allergies or dietary restrictions. The chocolate chips are good quality and creamy texture. The cookie itself is a little powdery in my opinion. That was a little off  putting. They definitely taste fresh, easy to bite.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-14', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'chocolate chips,freshness,bite size', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ec4c92407eec41251367ecbfd0715239', 'okendo', 'Angela S.', 'Still cheesey', 'These were cheesiest than i thought they could be. I dont know how they achieved this flavor without actual cheese but it was comparable to other popular cheesy snacks. The texture was somewhere between a chip and a cracker. They are thin, light and very crunchy. They are a bit too stiff for me. They would be great for dips because they are sturdy. The ingredients are allergy friendly so definitely a great choice for that crowd.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-14', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'flavor,crunchiness,sturdiness', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1c2f26c30ce7e3cb84b44bb5b387c8bc', 'okendo', 'Ashley H.', 'Chocolate chip cookie', 'Fresh. Clean ingredients. Decent consistency. They do taste like a regular chocolate chip cookie. Small little bite sized snack. Came in a resealable bag.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-14', 0, 'No', '', '', '["clean_ingredients","packaging"]', 'freshness,ingredients,consistency,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('087ba5b56060756aad345f2062c60472', 'okendo', 'Ashley H.', 'Cheese less thins', 'These are definitely different. Very thin… would take some getting used to. They are not gross by any means. Very fresh. Clean ingredients. Gluten free, vegan!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-14', 0, 'No', '', '', '["gluten_free","dairy_free_vegan","clean_ingredients"]', 'freshness,ingredients,gluten free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b2589def3241edab122b24a6ad93243b', 'okendo', 'Tina D.', 'Crunch level 10/10. But the taste just isn’t my vi', 'This cheese less thins are impressively crispy and definitely vegan-friendly, but the flavor just doesn’t land for me. The seasoning has an odd aftertaste that takes away from the otherwise great texture. I believe this is a good option for plant based snackers.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-13', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","false_advertising"]', 'texture', 'flavor,seasoning,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a8789677ebfb742b2244095ee9343f2e', 'okendo', 'victoriace986_6094', 'Great treat!', 'Being gluten free I am always looking for good snacks! I love chocolate chip cookies so was excited to try these. The overall taste is good and you can definitely tell that they are a chocolate chip cookie, but I do feel they are a bit dry. It adds an almost chalky taste to them, but doesn’t make them not enjoyable. I think for anyone with the certain specifications for allergens, this is definitely a great cookie. These were received for free in exchange for review.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-13', 0, 'No', '', '', '["gluten_free","allergy_friendly","bland_flavor"]', 'taste,gluten free', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('170b9adfb7cb9e60167cdf2c38375aa6', 'okendo', 'rachelh720_8314', 'Very tasty!', 'Really good! These cookies have a strong ginger flavor and a nice chewy texture. Best of all, they don’t have any weird aftertaste like some allergy friendly and special diet foods! I’d definitely buy them.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-13', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'ginger flavor,texture,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('468acc8543bd8908349c4e6bd515df3d', 'okendo', 'heatherw135_3376', 'Tasty little cookies', 'These tiny cookies are tasty! I love the way the ingredients are listed right in the front of the package so you know what you are eating. They are a bit dry, so are best with a cup of coffee or tea. The chocolate flavor is nice, not too sweet.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-12', 0, 'No', '', '', '["great_taste","bland_flavor","packaging"]', 'taste,chocolate flavor,ingredients', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('96a90646a3b4b6113932184a5fd24435', 'okendo', 'heatherw135_3376', 'Crispy savory crackers', 'These are nice and crispy. The texture though is not flaky, but more of a thin, dense cracker. They taste ok for not having any cheese in them. I love the way the ingredients are listed on the front of the package!', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-12', 0, 'No', '', '', '["crunch_texture","packaging"]', 'crispy,packaging', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('88927a54d20d27dc959dea5a7980cc2a', 'okendo', 'victoriace986_6094', 'Bland taste', 'Being gluten free I am always looking for delicious snacks that I can eat. While I was very excited for these I think they missed the mark. I have had vegan cheese before but this completely misses the flavor that you would normally expect. None of the salt remained on the crackers so the taste was very bland. They tasted l, well, they tasted like nothing. I did eat these alone as I would normally eat a cheese cracker. Perhaps these need to be included with another item to get the most out of them. These were received for free in exchange for review.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-12', 0, 'No', '', '', '["great_taste","gluten_free","dairy_free_vegan","bland_flavor"]', NULL, 'flavor,salt,vegan cheese', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e4e81c5f46196169e6a78aeb29f12719', 'okendo', 'kylieealiciaa_3753', 'Clean ingredients', 'I love that these are clean ingredients. The packaging is pleasing to the eye. I love the size of these pretzels and how crunchy but airy they are. These are good by themselves or with a dip!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-12', 0, 'No', '', '', '["crunch_texture","clean_ingredients","packaging"]', 'ingredients,packaging,size,texture,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bfc798b214cdc207ea879be5c5c723b5', 'okendo', 'kylieealiciaa_3753', 'Strong ginger', 'The packaging draws you to this product first off. They are very crunchy when you bite them but I personally did not like the ginger aftertaste at all. I also had my family try them and they said the same thing. If you like ginger then you should like them.', 1, 'negative', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-12', 0, 'No', '', '', '["crunch_texture","packaging"]', 'packaging,crunchiness', 'ginger taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2ef5be26a96dbdf9e3137cde0d6ad95c', 'okendo', 'sunitapanjabi_4723', 'Love', 'So so good!! Perfect bite sized deliciousness- they taste like a nutty chocolate chip cookie and I love that they are gluten free and have good ingredients I can read and understand.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["great_taste","gluten_free"]', 'taste,size,gluten free,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4c1897aa803cca5720673d5631e9fbb0', 'okendo', 'sunitapanjabi_4723', 'Delicious', 'Yum! These smell so delicious and cheesy when I opened the bag, and love how thin they are. Very moreish I could eat the whole bag in one sitting. Will be buying the other flavors soon', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["great_taste"]', 'smell,thickness,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('adcd7a8079c393aba9181d55270436c3', 'okendo', 'katieladycritiques_5623', 'Clean Ingredient Snack that''s Light & Crispy', 'I''ve been loving these Cheese-Less Snack Thins Super light, crispy, and packed with bold, savory flavor. Hit that cheesy craving perfectly without any dairy! Such a satisfying crunch every time. The crackers are made with super  clean ingredients: gluten-free, vegan, allergen-friendly, and made with extra virgin olive oil instead of junk oils. For a  family with food sensitivities, finding a tasty, safe snack can be challenging.  We keep them on hand for our weekly outings—hikes, beach trips, or car rides. They''re the ideal portable refuel: toss in a bag, no mess, no sugar crash, just steady energy to keep everyone going. A quick handful and we''re all happy and recharged.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","good_replacement","clean_ingredients","stale"]', 'texture,flavor,portability,energy', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('238d4c8fe161422e0f10a912f9978721', 'okendo', 'katieladycritiques_5623', 'Crunchy Cookie Great Healthy Snack', 'I''ve been searching forever for a chocolate chip cookie that doesn’t leave me worrying about allergens, and these little bites from Every Body Eat are delciious and healthy, they’re gluten-free, vegan, nut-free, dairy-free, and free from the top 14 allergens.  But You''d never guess from the taste. The cookies have a crunch  but tender base with melty chocolate chips  that feels like a real homemade cookies. They are great to bring as a snack on our weekly outings. I. Sweet, simple, and actually delicious for anyone looking for food with clean ingredients.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","clean_ingredients"]', 'taste,texture,ingredients,portability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('10f08cf91af42757f41f5e7040a8ea12', 'okendo', 'stacyr128_2145', 'Great cookies', 'Everyone in my household approved of the taste and size of these. They fit perfect in your mouth and had the right crispness and bite to them. They were a mouthful with no bad aftertaste.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["crunch_texture","stale"]', 'taste,size,crispness,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d7941cd37f934accdc6f80fa4c08df59', 'okendo', 'stacyr128_2145', 'Great product', 'The appearance and practicality were spot on. I loved the crunch and the light salt added to them. I like the clean ingredients as well. The installation, assembly and usability were spot on.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["crunch_texture","clean_ingredients"]', 'appearance,practicality,crunch,salt,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('afbcfb1ededfe92ad32c70582ab009e2', 'okendo', 'trica_7043', 'Crispy and Delicious!', 'Great packaging! This is a very crisp flat pretzel, which I personally liked. No abundance of sea salt or messy crumbs. Smells just like a pretzel though. I really like the  ingredients are simple, gluten and grain free. I would recommend this product for anyone that is allergic to gluten and grain or trying minimize their intake. It’s a perfect bite alone or with your favorite accompaniment.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","broken_crumbs","packaging"]', 'packaging,texture,crumbs,taste,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6660416fdabd9e75ecc60efc6dff7b4d', 'okendo', 'trica_7043', 'Healthy Snacking', 'First, the smell of this snack had my mouth tasting it before I actually tried it. Second, it has a powdery outside layer that I wasn’t a fan of. The quality was quite fresh and the texture reminds me of biting into a hard cookie then it being soft like an oatmeal raisin. It’s moderately sweet. Nothing heavy. Eye candy packaging for sure. And real wholesome ingredients. Honestly, I really wanted to like this product but I think it’s an acquired taste, you know what I mean? I think I’d have to try it a few more times to really get it. But I do recommend if it’s something new you are looking to try that is made with real ingredients.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-11', 0, 'No', '', '', '["crunch_texture","clean_ingredients","packaging"]', 'smell,texture,sweetness,packaging', 'powdery layer', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4dd08f18e6e6597f95c6a69c036771a8', 'okendo', 'Monique K.', 'Tasty and soooo crispy!', 'These are so delicious! They are very crispy and fresh tasting. They have a little bit of an aftertaste but while you are eating them the crunch is so satisfying. I like that they ate dairy free as I am trying to cut back on dairy a bit. The packaging is nice and compact.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan","packaging"]', 'taste,texture,dairy free,packaging', 'aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8275a51603294c12b32107fde36f3bb3', 'okendo', 'shelbyl155_1564', 'Bland and dry', 'These cookies are ok. They are pretty dry and bland. But I do like that they are healthier and don’t have preservatives or additives. Overall they are ok but would not recommend!', 1, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["bland_flavor"]', 'ingredients', 'texture,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('95c9719eaa8f3f53d7471530e2858024', 'okendo', 'shelbyl155_1564', 'Bland', 'I tried to like these but they are very bland. The texture is more like a chip rather than a cracker. I would not recommend them unless you like bland chips.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', NULL, 'taste,texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d726a8c6e0b76eeb2bdb26bc70308044', 'okendo', 'lauraw484_8103', 'Nice thin crunch!', 'Crunchy with a nice flavor. Nice thin chip without all of the allergens! I wasn’t sure what they’d be like but was pleasantly surprised! Good ingredients and nice taste!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'texture,flavor,ingredients,thickness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0814ca7abb674ea06cc65a16ca48b11a', 'okendo', 'lauraw484_8103', 'Already on bag #2….best crunchy cookie snack!', 'Already bought another bag! 👀😇 They are so good!! Perfect amount of crunchiness with a nice light oat flavor. Absolutely love these and can’t wait to try their other flavors! Perfect sweet treat without tons of sugar. Love it!!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunchiness,oat flavor,sugar content,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b878a382399cc3596b74bfa9e7248e93', 'okendo', 'alexandriaraeb_9793', 'Convenient size but lacking flavor', 'The cookies were a bit of a miss for us. The consistency is dry and the flavor fell flat.  I do appreciate the healthier ingredients and that they are smaller portions that are not too sweet. My toddler enjoyed them!', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["bland_flavor"]', 'ingredients,portions,sweetness', 'consistency,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7f1ae0092fd16d7d4d044e089408dad3', 'okendo', 'alexandriaraeb_9793', 'Great product', 'The cheese-less thins are actually pretty tasty for being made from healthier ingredients. The bag is easy to store and keeps the crackers from breaking. They look like real cheese thins and don’t get too messy, either!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["great_taste"]', 'taste,ingredients,packaging,appearance,messiness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4ee50a2276eab5343647336673b6f476', 'okendo', 'elenak1_4652', 'Must try!', 'love these cookie bites. They aren''t too sweet and the ingredients are very clean. They are perfect when you just want a little something sweet after dinner without eating a bunch of junk. Highly recommend if you are dairy-free or gluten-free.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["gluten_free","dairy_free_vegan"]', 'sweetness,ingredients,portion size,dairy-free,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('682121d3d129e8e5fa63812f5cbb81c1', 'okendo', 'elenak1_4652', 'Yummy', 'really love these! They are super crunchy and have a great ''cheesy'' flavor even though there is no real cheese in them. It’s hard to find snacks that are gluten-free and dairy-free that actually taste this good. I will definitely be buying these again.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan"]', 'crunchy,cheesy flavor,gluten-free,dairy-free,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4ab9e5c231ff74d716c272fe0bcec2f8', 'okendo', 'alinav21_4948', 'Crunchy, flavourful cookie bites with a great choc', 'I really enjoyed trying Every Body Eat Chocolate Chip Cookie Bites. The shape and size are perfect for snacking, and the texture is pleasantly crunchy without being too hard. The aroma is inviting with a nice chocolate scent right after opening the bag. They have a balanced sweetness, and the aftertaste is smooth without being overly sugary. I also appreciate the ingredient list, which feels clean and thoughtfully chosen. Overall, these are a satisfying and tasty snack option.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-11', 0, 'No', '', '', '["great_taste","crunch_texture","texture_issue"]', 'texture,aroma,sweetness,aftertaste,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6d19b0f58585b5836e2da2c5e1051e33', 'okendo', 'alinav21_4948', 'A light, crunchy, and flavorful dairy- free snack', 'I really enjoyed trying Every Body Eat® Cheese-less Thins. The ingredients feel clean and simple, which I appreciate when choosing snacks. They are light, crispy, and flavorful without being heavy or greasy. The freshness was great when opening the bag, and the texture stayed crunchy. Packaging is convenient and easy to reseal, which helps keep the product fresh. Overall, this is a satisfying snack option, especially for anyone looking for a dairy-free alternative.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-11', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","good_replacement","packaging"]', 'ingredients,texture,flavor,freshness,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f728110877f99f5bbf5377c535ca0501', 'okendo', 'suzanneb88_2679', 'Sooo good!', 'I could eat this whole bag in one sitting! they are SO yummy! we love allergy friendly anacka in our house and the ingredient list is short and simple! Opening the package the smell is amazing as well!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","allergy_friendly","packaging"]', 'taste,ingredients,smell', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ba07c505bd581101e80e4ba912e05d1f', 'okendo', 'suzanneb88_2679', 'Yummy!', 'These are such a yummy snack even my kids like it! These cheesy cracks taste very similar to cheez its but these dont have cheese in them! we love allergy friendly foods in our house! there is no strong after taste and they are so easy to eat the whole bag! the packaging is very eye catching too!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["great_taste","allergy_friendly","packaging"]', 'taste,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ba3ef7ab9bbffe6d8637011f2bd6db35', 'okendo', 'swatir6_5284', 'No one can eat just one', 'Love the everybody eats cheese-less thins. I like the ingredients and after taste. It''s gluten free and baked; crispy and tastes great and not chewy at all. I like to eat with my tea or with salsa. Everyone in my home liked it.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["crunch_texture","gluten_free"]', 'ingredients,aftertaste,texture,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8e5ab52d3c710f10b2986edd1b69ceb7', 'okendo', 'pink79_2224', 'Its ok', 'I love the crunch of these cheeseless crackers but I also hate to say it but there just is no flavor to these cracker I though it would have some salt or anything else but they don''t they a very tasty with a dip but by itself I wouldn''t really recommend the size is perfect and easy to seal bag for storage', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["great_taste","crunch_texture","bland_flavor","packaging"]', 'crunch,size,packaging', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f377887f397414814aebb6460388b132', 'okendo', 'pink79_2224', 'They are ik', 'These cookies  have a good crunch but just not my thing tasted more like almonds more than anything to me on the other hand my son enjoyed them so much he had to try it with milk and decided to put them as cereal in a bowl he enjoyed them so I just gave him the bag they smelled like chocolate  chip cookies  but didn''t taste like that', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["crunch_texture"]', 'crunch,chocolate smell', 'almond taste,chocolate taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('07d78e80419420bc7481cd4a4e26fc77', 'okendo', 'dianal74_5631', 'So delicious', 'Thise little chocolate bites are small and you can eating them, maybe with tea, also I think they are perfect even like a cereal, they taste so good, love the cinnamon touch, they are so fresh and the amount of chocolate is perfect, I highly recommend them 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5567185f4723d63b7773450d245a3417', 'okendo', 'sierras182_4427', 'Tasty alternative', 'These are really tasty cookies, considering thehealthy  ingredient list! They’re a perfect bite-size dessert. Texture is not offputting, and there is no aftertaste. We like them.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","crunch_texture","good_replacement"]', 'taste,size,texture,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b099b129d1674836b0e8ebfa21561d91', 'okendo', 'sierras182_4427', 'Pretty Okay', 'These are a pretty good snack. Very limited ingredients, which is fantastic, but definitely don’t expect the taste of the less healthy more junk food type cheese crackers… Very crisp and the perfect amount of salt. Ultimately, we ate the whole bag.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["crunch_texture"]', 'ingredients,texture,saltiness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('12649ef760a79354089b191522d10560', 'okendo', 'samanthav134_7711', 'Eh for the taste', 'I was sent Every Body Eats Chocolate Chip Cookie Bites by influenster in return for my honest review. I am all for my gf cookies but these were not it. Nice good crunch, adorable lil cookies. But for me the taste just was not good.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["crunch_texture"]', 'crunch,size', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e854fccfeab675fd761b8e1deb2041cf', 'okendo', 'samanthav134_7711', 'Must have an Acquired taste for these', 'I was sent Every Body Eat Cheese-Less_thins by influenster in return for my honest review. Sadly these just weren’t it. I am always in search of gf alternatives. But they also must taste good. These gave me a super earthy dirt taste :( just was not my cup of tea. The crunch was good, I could see people enjoying them. But for me “an acquired taste” is needed.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["crunch_texture","good_replacement"]', 'crunch', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d864fa96aed8e974d1681efb318a342b', 'okendo', 'gabbyd46_4712', 'Cookie bites chocolate chip!!', 'The portion of this cookies are perfect, the ingredients combination is very good, is a very good choice for healthy snack, about the chocolate chips it''s great taste, its soft and easy to eat besides you can open and close the packaging so it''s very convenient, I recommend it. Thanks to influenster and every body eat for this opportunity to try this great healthy cookies bites.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","packaging"]', 'portion size,ingredients,chocolate chips,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7b2d97b44dbfe728c03bb2210332b23f', 'okendo', 'gabbyd46_4712', 'Gluten free, vegan snack!!', 'First of all I must say that this chesse-less thins are good of the taste, the aroma is neutral in my personal opinion is something new and more healthy snack choise, the texture is crunchy but not too hard to eat, the storage is very convenient because I can close and open easily when I want,the aftertaste is good enough, so I recommend them. Thanks to influenster and every body eat for this opportunity to try this great snack.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","texture_issue"]', 'taste,texture,storage,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5d319a234e952cf3d0d4e06312448c7d', 'okendo', 'Alba M.', 'Good', 'These are delicious cookies, non-GMO, gluten-free, and very healthy. My daughter loved them; they were soft and tasty, with a chocolate aroma and a soft texture.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,texture,chocolate aroma,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('05af56cc0ec4bb2c6b335e247751aab5', 'okendo', 'Lanni N.', 'Crispy, chocolatey cookie bites that are tasty and', 'Every body eat chocolate chip cookies bites smell warm and chocolatey when you open the bag.The bites have a nice balance of crispness and softness without being too sticky.The chocolate chips are evenly distributed and add great flavor.They look appetizing and are perfect for quick snack or dessert.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'smell,texture,chocolate chips,appearance,convenience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a9cfa0c50bdca697126fe8e768e71189', 'okendo', 'Oanh S.', 'Don’t like', 'I don’t like this cookies, it’s bad, not tasty. It’s a bit powdery, crispy, and sweet. But it doesn’t give me the feeling to want a second bite. Overall, it’s not good', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","crunch_texture"]', NULL, 'taste,texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('258b6b009856b6cbca447294c0d59f97', 'okendo', 'Megan M.', 'Crispy but zero flavor', 'These crackers are a good choice if you''re looking for something that''s free from major allergens and still has a good crunch. They''re made with a blend of alternative flours, which gives them a unique flavor that''s different from traditional wheat crackers. The texture is thin and crispy but just lacks flavor.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["crunch_texture","allergy_friendly","good_replacement"]', 'crunch,texture', NULL, 'flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('293f122281782740316844ed420055eb', 'okendo', 'Megan M.', 'Worth trying', 'This is a good allergy-friendly snack, with a unique taste, the texture is pleasant and melts in your mouth. The package is a perfect size to throw in your work out bag, or purse.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["crunch_texture","allergy_friendly","packaging"]', 'taste,texture,packaging,portability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bb11da935949ed8f69c44f1c0a0a1f31', 'okendo', 'Laura R.', 'Low in sugar and crunchy', 'These cookies are crunchy not chewy. The taste is just like a chocolate chip cookie and since the portion size is small not a lot of crumbs.  The aftertaste is not bad but it is not a taste I would associate with a chiclet chip cookie.  I like the low sugar content.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["crunch_texture","broken_crumbs"]', 'taste,portion size,sugar content', NULL, 'aftertaste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9d448f9febcb4296568716d7596c7d7d', 'okendo', 'Laura R.', 'Gets better as you eat it', 'These crackers are good and the size of bag does the job. The texture is fine and there is odd beginning taste but aftertaste is better. This bag of crackers can be finished in one sitting so no worry about shelf life.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-10', 0, 'No', '', '', '["crunch_texture"]', 'texture,bag size', NULL, 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b71a77bb309d66bfd519588f0b576cbd', 'okendo', 'Kelly M.', 'Delicious and great portion size with clean ingred', 'A little chalk like BUT pretty delicious! I ate majority of the bag In one sweeting! An excellent GF choice without seed oils and cleaner ingredients. Will buy again. Great portion size too!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-10', 0, 'No', '', '', '["great_taste","repeat_purchase"]', 'taste,ingredients,portion size', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ccfd2e4960fada45ada859e36113bf70', 'okendo', 'Susie G.', 'Finally a snack without allergens for gluten that', 'Loved the pretzel thins!!! I am allergic to ingredients used in pretzels in general so it’s been soo long since I’ve eaten pretzel anything. This snack really scratched that itch while being very healthy and transparent with the ingredients. No ingredient that flares up gluten related allergies. I’m very excited for this and I am going to try other flavors as well. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('694b15a4370edc65767df89ec28c4b56', 'okendo', 'Susie G.', 'Crumbly small cookie that packs a punch', 'Crumbly small cookie, it tastes good and melts nicely in the mouth. I personally am not the biggest fan of cinnamon desserts but this is pretty yummy. The ingredients are clean and minimal. Wasn’t completely satisfied cause there are added sugars but other than that, a healthy and tasty treat.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-09', 0, 'No', '', '', '["great_taste"]', 'texture,taste,ingredients', 'sugar', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('69759bdc642f6bdf8fe60a75fd6b98a1', 'okendo', 'Lydia C.', 'Looks can be deceiving!', 'Not gonna lie, when I opened the bag. I was super skeptical. The cookies were not at all like the photo on the bag, as you can see they’re ” crumby” for lack of a better word, so I wasn’t expecting much. Then, I took a bite! Wow! I would not have believed you if you told me these were gluten-free, much less, made with clean ingredients. They were perfectly crispy with just the right amount of sweetness! (the only thing I didn’t really get was chewiness, but not a downside in my opinion!)', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-09', 1, 'No', '', '', '["crunch_texture","gluten_free","clean_ingredients","stale","false_advertising"]', 'texture,sweetness', 'appearance', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ab5e0c626d44de187414670e1feb7064', 'okendo', 'Susan S.', 'They are addicting', 'The packaging, insured, freshness, amazing texture, and what value and consistently always has the best value so many allergies and they make sure I can snack while not having to miss', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-09', 0, 'No', '', '', '["crunch_texture","allergy_friendly","packaging"]', 'packaging,freshness,texture,value', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('52c75d29cae7f2cda1ffdaaeb8644466', 'okendo', 'Be Hien D.', 'Good cookies', 'This is a new kind of snack and I enjoyed it.  It reminded me of eating pretzels but love the twist that these are thins.  I also like they didnt put much salt on them but still flavorful.  I highly recommend this snack.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-09', 0, 'No', '', '', '[]', 'texture,salt,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('43e061270095b00b26f5780fffb6ecb8', 'okendo', 'Be Hien D.', 'Good cookies', 'I thought the cookies tasted decent and had enough sweetness without the overkill. But the flavors are not my go-to, and prefer other flavors.  Besides that, it is decent and recommend it to anyone', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-09', 0, 'No', '', '', '[]', 'taste,sweetness', 'flavors', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('38c575853832bb49ab0f11a5a2f4cf0c', 'okendo', 'Alyssa M.', 'Not my favorite', 'I want to provide honest answers always and what I will say is that enjoy the effort in using clean and simple ingredients. I would just say as compared to other cheesy crackers this one does not hit the mark. It hardly comes across as a cheesy and I feel it could be improved.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-09', 0, 'No', '', '', '["clean_ingredients"]', 'ingredients', 'cheesy flavor,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('35d0cc536ac978db690118997a04d922', 'okendo', 'Alyssa M.', 'Interesting clean cookie', 'I love the fact that these are cleans and simple ingredients to one of my favorite things to eat. I enjoyed that the cookies are not too sweet, I’m always looking for a sweet treat that’s not overly sweet tasting. I wish I could say I want more after this, but it was not my cup of tea.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-09', 0, 'No', '', '', '["clean_ingredients"]', 'ingredients,sweetness', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1608d85a6d636a20ea419905ffa831c3', 'okendo', 'Katie S.', 'Improvements needed', 'Not a great texture or flavor. No one really ate them when other choices including fruit were presented. They need to find their core audience and I am not one of them', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-09', 0, 'No', '', '', '["crunch_texture"]', NULL, 'texture,flavor,appeal', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('db103f34afe22dc48f5a703ed5f7b842', 'okendo', 'Olya S.', 'Great quality!', 'Amazing ingedient list and taste! It melts in your mouth, and I love how tiny they are! So cute and easy to bite them! Also, you can taste they they a good quality and well made, not too sweet, but a perfect taste and combination of good stuff. Tastes so different from other commercially made cookies, this one is great that even my kids loved them!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '[]', 'taste,texture,size,quality,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e21008438c8081105db78c60132b2d2d', 'okendo', 'rachelh720_8314', 'Tastes like a pretzel with a nice thin crunch', 'They’re really ugly but the taste is mostly like a pretzel! A little salty and tasty. Nice and thin and crunchy texture. I’d buy again for GF friends and family', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-08', 0, 'No', '', '', '["great_taste","crunch_texture","repeat_purchase"]', 'taste,texture,gluten-free', 'appearance', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5979b58d10c6808b023f30acf92debd8', 'okendo', 'Samantha M.', 'NOPE', 'Portion is good crispness good chocolate my favorite appearance good aroma good it has a after taste i will not go in thestore looking for this product to buy', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '["crunch_texture"]', 'portion,crispness,chocolate,appearance', 'aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f56517d6071b5daeb6f1f02b971de586', 'okendo', 'Stephanie E.', 'Delicious', 'So good and delicious! Surprised how good they taste. Light and delicious. Good ingredients. I feel like the are a perfect snack. I would recommend these to everyone!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-08', 0, 'No', '', '', '["great_taste"]', 'taste,texture,ingredients,snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b75098fd7450ff363dd406cb99f941c9', 'okendo', 'Stephanie E.', 'Delicious', 'Delicious! Such a good healthy snack when you need a sweet tooth. Just enough to feel full. I feel like this are a great snack! Healthy and tastes great!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '["great_taste"]', 'taste,sweetness,portion', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b17109d5ecb832d5084c6de8434f9f79', 'okendo', 'Tram L.', 'Warm ginger cinnamon flavor with a satisfying chew', 'These ginger cinnamon snacks have a warm, comforting flavor with a nice balance of spice and sweetness. The texture is pleasantly chewy without being too sticky or tough. The ingredients taste high quality, and the flavor lingers in a nice way without being overpowering. They feel like a satisfying treat, especially if you enjoy ginger-based snacks or seasonal spice flavors.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-08', 0, 'No', '', '', '["crunch_texture"]', 'flavor,texture,ingredients,spice', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('18ab7f589330e0293b1d0f23b3cca8df', 'okendo', 'Tram L.', 'Crispy, lightly salted pretzel thins that are conv', 'The pretzel thins are very convenient for quick snacking and easy to portion. They have a nice crispy texture and a satisfying crunch without being too hard. The taste is enjoyable with a balanced saltiness that isn’t overwhelming, and the aftertaste is clean. They pair well with dips or are great on their own when you want something light and crunchy.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-08', 0, 'No', '', '', '["crunch_texture","texture_issue"]', 'convenience,texture,taste,aftertaste,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8a60a6de0d3bf0f70d49d2b307e07e9c', 'okendo', 'Karsen K.', 'Not a favorite', 'Unfortunately we felt like these were too flour-y tasting and would not recommend. Sweetness and texture were fine but flavor and after taste just were not ideal.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '["crunch_texture"]', 'sweetness,texture', 'flavor,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7ae0efd70aeaac5c0e308cd017b39e66', 'okendo', 'Karsen K.', 'Just okay', 'My kids and I tried these and wanted to like them but overall consensus was they’re just ok. Texture and size are fine but they’re just a little dull tasting. Everything else was fine and they weren’t horrible but I just wouldn’t say they’re a solid replacement for cheese-less crackers :)', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-08', 0, 'No', '', '', '["crunch_texture","good_replacement"]', 'texture,size', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('38f6d894f9cb11925e06afb471bc687c', 'okendo', 'Oanh S.', 'Good chips', 'This type of chips are delicious, thin, and has a slightly salty, cheesy flavor. The packaging is beautiful and eye catching, and it has a convenient zip closure for resealing when you haven’t finished eating them all.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-08', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,texture,flavor,packaging,closure', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('722a1cb96f0ffd41e7d99ebaa458f14f', 'okendo', 'Darci B.', 'Cookie crunch and tasty', 'A perfect little one or two bite cookie. The Everybody Eats chocolate chip cookie bites are a nutty rasting subtle chocolate tasting and satisfying. I wouldnt hesitate giving it to all my family members even my 3yr old.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '["great_taste","crunch_texture","stale"]', 'size,taste,chocolate,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d7317fe99286b6ba4e5e253b37a2d946', 'okendo', 'Kara M.', 'Missed mark', 'The Every Body eat Cheese-Less thins were mid. They do taste cheeseless 🙁 They are paper thin and kind of taste like a diet food. Aftertaste is slightly gritty. “Cheese flavor” comes from the nutritional yeast. These are GF, vegan, and baked, not fried. Although I love clean ingredient foods, this one missed the mark. I did try the chocolate chip cookie bites from this company and they are delicious! Can’t recommend the cheese-less thins though.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-08', 0, 'No', '', '', '["great_taste","dairy_free_vegan","clean_ingredients"]', 'ingredients', 'taste,texture,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('73245a0254bc5b2168f3c3105efc9e38', 'okendo', 'Thao N.', 'Love this chocolate chip cookie', 'Love this chocolate chip cookie bites, good size for my daughter, sweet enough for who dont like too much sugar like me. Great flavor with just right softness.okir', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '[]', 'size,sweetness,flavor,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('825a66ae9d17eabe2e35635ec8fab690', 'okendo', 'Thao N.', 'Little crackers is good snack', 'This little cracker is good snack, thin, cheesy, less salty, i think this good for veterian, packaging easy to open. My husband want to try with dip.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-08', 0, 'No', '', '', '["packaging"]', 'thin,cheesy,salty,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c4e74ff9a62dc89671ab8c415e5717db', 'okendo', 'Erika G.', 'Cookie snack', 'These were my favorite. They are crunchy sweet and feel indulgent without being too sugary. Great if you are wanting something sweet but still mindful.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-08', 0, 'No', '', '', '["crunch_texture"]', 'crunchy,sweet,indulgent,sugary', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d9bcd07ccf072e3dc81a5494dd00e1e6', 'okendo', 'Erika G.', 'Great snack', 'I tried the Cheese less thins and they are super crunchy light and very flavorful. They are savory and makes them a great snack to munch on. They are healthy but don’t taste like it.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-08', 0, 'No', '', '', '["crunch_texture"]', 'texture,flavor,snack,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('afe6e2b9941f40fb1b91461b042b3c0f', 'okendo', 'Yelena T.', 'Healthy but too dry', 'I like the idea of eating healthy cookies especially since my son has gluten allergies. These cookies were okay, but you could tell that you''re eating a healthy version of a cookie. They were also too dry in my opinion, as I see the gluten free flour blend  might be the source of that. I also found myself looking for more chocolate pieces in the cookies as I was choosing the cookies from the bag. Maybe if it has more chocolate pieces, it would off-set the dry texture. Overall they are fine, but not my favorite. They are good for my son, but for me, as someone who is health conscious but without allergies, I might consider something different. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('be5a3549cbfae7effab03809dd4a3bb2', 'okendo', 'Sierra L.', 'Chocolatey!', 'The Every Body Eats Chocolate Chip Cookie Bites have amazing flavor and I love that they are a gluten free and cleaner option! My son loved them and I didn’t feel guilty letting him have these as a treat!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-07', 0, 'No', '', '', '["gluten_free"]', 'flavor,gluten free,treat', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3e42b3c97ca620b997c5236952c80922', 'okendo', 'Sierra L.', 'Crispy', 'The Every Body Eats Cheese-less Thins are perfect for anyone looking to eat cleaner or that suffers from a gluten allergy. They are a great alternative to the commonly known option. I thought they had great tastes and just enough salt.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","good_replacement"]', 'taste,salt,alternative', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1e216b6a7dd9894d0dfeb6249ea47821', 'okendo', 'Yelena T.', 'Missing salt on them', 'I wasn''t sure what to expect with these health chips, considering they don''t have cheese. The chess-less thins actually tasted very good overall flavor wise. They were very thin and crispy in texture. But my batch seemed to have minimal salt on them. The pieces that had the salt on them equivalent to the image on the bag tasted perfect. The ones that were missing salt, were very bland. That''s why I didn''t give it full 5 stars. Overall these are a great healthy alternative snack, as long as they actually look like they are supposed to.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('da2fa1c293f707df533eab83bb505833', 'okendo', 'Jaimie F.', 'Not bad, but not great', 'We were so excited to try the Every Body Eat Cheese-less Thins & while they were perfect (certified gluten free) for my celiac kiddo, he didn’t seem to love the taste. I tried them as well and felt like they were good & crispy but they did leave an aftertaste. Overall I’m not sure I’d buy them if I wasn’t in a pinch for something certified gluten free & safe for him.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["crunch_texture","gluten_free"]', 'crispy', 'taste,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bd4a79a0b80afee72294fee53716bec5', 'okendo', 'Tara O.', 'Surprisingly good!', 'These were shockingly good! Very thin and crispy. Slight cheese taste, not overpowering. Some had yummy salt flakes on them. This would be a healthy alternative from Cheeze-its (sp?). Loved all the health claims.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["great_taste","crunch_texture","good_replacement"]', 'texture,cheese taste,salt flakes', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ffba9680cf159c3207e1afd6e3121599', 'okendo', 'Katie S.', 'Lacks flavor', 'So I gave everybody in my family to try these Cheez-It replacement snacks, and although they were very crunchy, the flavor did not hit the mark if there were subtle improvements definitely will try again thank you', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["crunch_texture","good_replacement"]', 'crunchy', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b61e7773c53842973d46f71606ac1f30', 'okendo', 'Ali D.', 'Not a fan- tastes stale', 'The taste of these is less desirable than their salty cracker snacks. The taste reminds me of old, stale food, wood tasting. It also leaves quite and aftertaste and chocolate chip cookie shouldn’t.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-07', 0, 'No', '', '', '["stale"]', NULL, 'taste,aftertaste,staleness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('25d8cc3085077514dda69d16a2c107ef', 'okendo', 'Ali D.', 'Yummy salty snack', 'These vegan cheese crackers were delicious! Unfortunately I ate them all. The test was excellent, kind of cheesy, right amount of salt and other flavors. I liked how light and thin they were and all the natural ingredients. I will buy these again and try some of their other snacks. Bye bye Cheeze-it’s, here’s a healthy alternative.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["great_taste","dairy_free_vegan","good_replacement"]', 'taste,texture,ingredients,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bd7040f88f96fcd4df58ac5bac76ab69', 'okendo', 'MISS L.', 'Kind of dry and calorific', 'These were pretty dry in texture without a ton of flavor. And as you can see, some of them didn’t even contain any chocolate chips. I do appreciate the clean ingredients and the mini size however!', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-07', 0, 'No', '', '', '["crunch_texture","clean_ingredients","bland_flavor"]', 'ingredients,size', 'texture,flavor,chocolate chips', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4df4c8326efc151cb873cd85ae6d3605', 'okendo', 'Tanya W.', 'Natural and allergy friendly!', 'The Every Body Eat Chocolate Chip Cookie Bites are my new favorite. They taste delicious. I like crunchy texture, mix of sweet and slightly salty taste and tasty chocolate aroma. I like eating it as a snack and dessert. Good combination of chocolate chips, oat flour, flex seeds and maple, can sugar makes them perfect addition to my pantry.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-07', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'taste,texture,chocolate aroma,ingredients,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2cea54c3714c512a36b78f90b81cf055', 'okendo', 'Tanya W.', 'Thin, cheesy and crunchy!', 'I’m watching my calories and prefer healthy snacks. The Cheese-less_Thins by Every Body Eat is a delicious and natural snack. I appreciate simple ingredients list and the fact that the thins were baked, not fried. It has crunchy light texture with yummy cheesy flavor. The bag is resealable that makes storage convenient.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","packaging"]', 'texture,flavor,ingredients,packaging,preparation', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('749b89689e6de77235a3735324224918', 'okendo', 'MISS L.', 'Easy to polish off', 'I could totally hoover this bag down in one sitting! My biggest gripe is that this bag contains so few crackers! They’re super light and crispy,—best for snacking rather than being sturdy enough for dipping. Delicious just the same!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-07', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture,taste', 'quantity,dipping', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('771c817599537678fdfbbf18748ec118', 'okendo', 'Kara M.', 'Tasty, clean ingredient mini cookies!', 'The Every Body Eat chocolate chip cookie bites are amazing! They’re gluten free, vegan, and free from the top 14 allergens, corn, and seed oils. I love love love the clean ingredients! 1 serving is 5 cookies, which is a pretty good amount! There are 5 servings per 5oz bag, so 25 cookies per bag. They are little bigger in size than the width of a quarter, so it’s easy to eat a few quickly. The flavor is perfect and they have a crunch and slight crumbly consistency. To me, they are not too sweet and the lightness of the cookie leaves an after taste that makes you want the next one. The bag comes sealed and is resealable to maintain freshness if they last that long! Will be purchasing more of these! Note: quick search online and the cookies are available at Hyvee, Walmart, Amazon, Target. Costs was $5-$6/5oz bag, so not a cheap snack.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-07', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","clean_ingredients","packaging"]', 'flavor,texture,sweetness,size', 'price', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
