INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a571db1b639b9cc7ef18fed6aee5d00f', 'okendo', 'Ngoc L.', 'Every Body Eat Cheese-less Thins', 'I was pleasantly surprised by these Cheese-less Thins from Every Body Eat! They’re crispy, light, and full of flavor without being heavy or greasy. Even though they’re dairy-free, they still have a really satisfying, savory taste.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c1fa5d7a9ec8f196fdad25d331b39525', 'okendo', 'MaryEllen M.', 'Okay', 'I didn’t like the dough; it wasn’t saltines, and the ingredients weren’t good. The texture was too hard, and there was no aroma. overall, I would not buy this product again or recommend it.', 1, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-07', 0, 'No', '', '', '["crunch_texture","texture_issue"]', NULL, 'dough,ingredients,texture,aroma', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
