INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b4a18fe19585ba075f07547bd1afd1ef', 'okendo', 'mariela A.', 'the soft cookies', 'the shape of these cookies is perfect i love the chocolate aroma the mouthfeel is delicious the dough is soft the texture is unique i recommend them these cookies are crunchy', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'shape,chocolate aroma,mouthfeel,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('95253fc23449b108a41f94151369642d', 'okendo', 'Dori F.', 'Nice snack option', 'These Every Body Eat Cheese-Less Thins are a total lifesaver for school snack time since they’re gluten-free, vegan, and allergy-friendly. I’m always on the hunt for things that aren’t fried, and since these are baked and made with simple ingredients like brown rice flour and nutritional yeast, I can feel good about the kids reaching for them. They have this amazing crunch and savory flavor from the paprika and garlic that makes you forget they''re dairy-free. It’s such a relief to have a delicious, "clean" option in the pantry that everyone—even the pickiest eaters—actually wants to munch on!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","clean_ingredients","false_advertising"]', 'crunch,flavor,taste,texture,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d6570a965d894e6e6621a6e9f49e93d7', 'okendo', 'Dori F.', 'Yummy!', 'Oh my goodness, you have to try these! Finding a snack that my kids actually love and that doesn''t make me stress over ingredient labels feels like a total "mom win." These Every Body Eat Chocolate Chip Cookie Bites are a permanent staple in our pantry now because they’re gluten-free, vegan, and—best of all—totally allergy-friendly, so they’re safe for school lunches. They have that perfect, satisfying crunch that’s so hard to find in "clean" cookies, and I love that they use real stuff like cassava flour and maple sugar instead of a bunch of fillers. Honestly, I usually end up sneaking a handful myself with my afternoon coffee because they’re just that good. If you''re looking for a treat that tastes like a "real" cookie but keeps things simple and safe, these are definitely it!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","good_replacement"]', 'taste,texture,ingredients,gluten-free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
