INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d58b9772101c796d3fb5280b2e937dec', 'okendo', 'Daisy M.', 'Must try!', 'These cookies were so yummy! I was scared of the ginger but it was not strong enough to make it taste all the ginger. However it complemented the cookie itself. It was crunchy but soft in the middle! I will definitely be buying a handful of these cookies', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,ginger,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2bc8d2d507ea604d8b78e6e87039c0de', 'okendo', 'Daisy M.', 'Definitely a must try!', 'I loved these pretzels, they are delicious! You cannot tell it’s a “healthy” pretzel because they taste so good! I love all the simple ingredients and how it’s baked and not fried! It’s is also vegan and gluten and grain free! Definitely will buy them again!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","dairy_free_vegan","clean_ingredients"]', 'taste,ingredients,baked', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
