INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d7f19eb05b733b66e474c68809653e0f', 'okendo', 'Celine Y.', 'Good cookie bites for kids', 'My kids love these cookie bites， easy to grab for quick breakfast. They are not too sweet，tasty and crunchy，and they kind of melt in your mouth. Healthy snack，I will definitely buy more for my family.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,sweetness,convenience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('93edc41bc8e72d801dbc5290fc9941b7', 'okendo', 'dianal74_5631', 'Small pieces', 'Honestly this Cheese less things are like plain pasta, didn’t inspire me to share with family or friends, the size is small and the texture was weird, I don’t know but feels like something is missing for my taste', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["crunch_texture"]', NULL, 'taste,size,texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('24a1823a082a5e8328f2e4d74c721e43', 'okendo', 'Indrani B.', 'Gluten free healthy choco chip bites.', 'I was so excited to taste these cookies because I am always looking for healthy snack options for myself and especially for my kids.One of my kid is gluten sensitive but he loves cookies.This cookie bites are gluten free and tastes very similar to the regular ones which is a big plus.It contains many good and healthy ingredients like oats,flax seeds,carrot fibre and more.It is not sugar free but it uses cane and maple sugar in place of artificial sweeteners and unnecessary sweetness.On top of it these are vegan and tastes yummy.It is a good and healthy snack alternative .Highly recommended.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","gluten_free","dairy_free_vegan","good_replacement"]', 'taste,texture,ingredients,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dfe7afa8123f74eb883d357ac8a0b167', 'okendo', 'Katerina C.', 'Perfect snack 😋', 'These Every body eats chocolate chip cookie bites are actually very good! Not very many chocolate chips nice and crunchy not very sweet for cookies and there''s no aftertaste in my mouth after I eat them! The size of them are perfect for your child/children friends, or yourself these are perfect and they have so many ingredients that are good for you in them! I totally recommend these! Quick and easy preparation for snack to throw in your bag for any hike or whatever your heart''s desire 😉 thank you @influenster for the opportunity to try these cookies out for my honest opinion', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["crunch_texture"]', 'taste,texture,size,convenience', 'chocolate chips', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('012898ac222d6c046a8f1366681641eb', 'okendo', 'Indrani B.', 'Healthy and tasty cheese bites', 'Everybody eat cheeseless thins are one of the best snack that taste great and are also very healthy.The ingredient list is clean and short,which I really like.They are made with brown rice flour and extra virgin olive oil,and they are completely gluten free.Perfectly crunchy and the sea salt on top makes them very tasty.I loved them so much that I finished the whole packet myself.My kids enjoyed them too and as a parent you feel completely guilt free giving this snack to your kids.Very satisfied…highly recommended.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,ingredients,gluten free,texture,kids', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cc836fc4c6fa83dbc964339faaeb2d44', 'okendo', 'Katerina C.', 'Perfect snack 😋', 'These Every body eats cheese less thins are actually pretty good! I nice hint of garlic and sea salt, if you eat cheese you would never know that these don''t have cheese! Very crunchy maybe a little too hard, but very crunchy, good to keep in your bag for any time during the day!  Very easy preparation 👌 thank you @influenster for the opportunity to try these cheese less crackers totally recommend these to every body there''s no maintenance needed not messy! Very reliable any time during the day', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["crunch_texture","texture_issue"]', 'garlic flavor,cheese taste,convenience,messiness', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ccc2142620f19d292e7bd1b14d32c056', 'okendo', 'Quyen D.', 'Every Body Eat Chocolate Chip Cookie Bites have th', 'Every body eat chocolate chip cookie bites are such a satisfying little treat. The saltiness is perfectly balanced with the sweetness, giving each bite a rich, crave- worthy flavor. The bite size is just right-soft with a pleasant chew, not dry or crumbly. The chocolate chips taste generous and real, melting nicely as you eat. They always feel fresh, and for the quality and portion you get, the value is excellent. Definitely a go-to snack when I want something sweet but not overwhelming.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["bland_flavor"]', 'saltiness,texture,chocolate chips,freshness,value', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b43e4dbf9ba8542840ced69e4b0f98c4', 'okendo', 'Mrudula C.', 'Satisfying sweet treats', 'Every Body Eat Chocolate Chip Cookie Bites bring back the classic cookie vibes in a fun, bite-sized treat. Each one packs a crunchy punch with a smooth, chocolatey finish that feels like a guilty pleasure, but it''s made with simple, wholesome ingredients.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["crunch_texture"]', 'texture,flavor,size,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5d177d82a9e770d438afc0c104fdc9bb', 'okendo', 'Quyen D.', 'Every Body Eat Cheese-less Thins have clean ingred', 'Every body eat cheese less thins are a surprisingly delicious snack with clean, simple ingredients that feel good to eat. They’re light and crisp, with a sastisfying crunch that performs well on their own or paired with dips without falling apart. The taste is savory and well-balanced, proving you don’t need cheese for big flavor. The thin, lightweight texture makes them easy to snack on without feeling heavy, and for the quality and portion you get, they’re a great value. A solid go-to for anyone looking for a tasty, plant- based crunch.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","value_price"]', 'taste,texture,ingredients,value,durability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f5f85789d9080881ee82e3e7a38bfa02', 'okendo', 'Mrudula C.', 'Healthy and tasty', 'Crunchy, irresistible, and totally dairy-free! Every Body Eat Cheese-Less Snack Thins pack a real cheesy punch without any cheese. With bold, savory flavors and wholesome ingredients, they taste as good as they make you feel. Made with clean, gluten-free, and allergen-friendly ingredients, these snacks are a treat everyone can enjoy!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","stale"]', 'texture,taste,dairy-free,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('49a9a276cd1ba2cdc50ef431a4c44a5a', 'okendo', 'Monique K.', 'Sooo delicious!', 'Insanely delicious! I feel like I can’t stop eating them once I start! Delicious cookie- low sugar and so incredibly crispy and tasty! They are some of the best cookies i have had!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","addictive"]', 'taste,texture,sugar content,addictive', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6be8efcc0004969a4ae690bffa00481f', 'okendo', 'Tiffany C.', 'Great Ingredients with Great Taste!', 'These are great little cookies! Perfect for a small snack or even to satisfy a sweet tooth after lunch! I love that the ingredients are simple and honestly can’t believe these are gluten free!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","gluten_free","false_advertising"]', 'taste,size,ingredients,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e5902a767088b24130a744b7bb229536', 'okendo', 'Joey G.', 'Good', 'The cookies are healthy and super crumbly. If you are looking for something healthy to satisfy your sweets craving this is the product. Simple and clean ingredients!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["clean_ingredients"]', 'texture,ingredients,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5834dcb01545ddbcb3fc1286b8eb58e2', 'okendo', 'Joey G.', 'Love', 'These are soooo yummy and healthy. I love the crispiness and thinness of this snack! The ingredients are great and simple. My kids love it as well.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,crispiness,thinness,ingredients,kid friendly', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('046117a77389b49e9592c0b904a13775', 'okendo', 'Bethany P.', 'Pretty good for GF!', 'Yummy fort snack for this kiddo!  Gluten free and great ingredients that actually tastes decent is hard to do but they did a nice job!  The texture is a little crumbly and still has a bit of a sandy taste (like lots of gluten free foods) but it’s better than lots of stuff out there!  If you are looking for a store bought chocolate chip cookie treat and you need something gluten free, these are a good option.  I would not replace a typical cookie with these for people without dietary restrictions, they will be disappointed.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,ingredients', 'texture,sandy taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3de3f74ff557abc19210b68aba3fcb6c', 'okendo', 'Bethany P.', 'Disappointing cheese flavor', 'Such a disappointment! The nutritional profile is good, gluten free but the cheese flavor is not quite right and very mild.  I was hoping for a better cheese cracker like the ones we had as kids but it is not a swap in my opinion.  The only positive was the texture and feel of the cracker. They had a great mouth feel and crunch but the taste just wasn’t there. We won’t purchase these again.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["crunch_texture","gluten_free","good_replacement"]', 'texture,crunch', 'cheese flavor,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ab3ecbc06b61e2c19303e96691ad8946', 'okendo', 'Andria L.', 'Crunchy lil sweet treat', 'These little chocolate chip cookies are the dry and crunchy type. With that being said, I did enjoy these and had a hard time having only a few. I especially appreciate that they are made with healthier, allergen-friendly ingredients and only 7 grams of added sugar for 5 little cookies.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["crunch_texture","allergy_friendly","bland_flavor"]', 'taste,ingredients,sugar content', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('665520368aa30d2bed3c41b535682229', 'okendo', 'Isaura D.', 'Delicious and better for you!', 'My family absolutely loves eating these cookie bites. They taste amazing and I especially love the fact that they are gluten free, vegan and allergy friendly. This is a must have snack!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["great_taste","gluten_free","dairy_free_vegan","allergy_friendly"]', 'taste,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a0624483fd1d4b8ef49e4dbbba4249ff', 'okendo', 'Crista W.', 'Chocolate Chip snacks', 'I love the idea of a healthier snack cookie but these little bites were a bit too dry and crumbly.  The chocolate chip flavor was not as strong as I would have liked.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["bland_flavor"]', NULL, 'texture,chocolate flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fb68a40afc98ef9d66160551dbd79048', 'okendo', 'Isaura D.', 'Delicious!', 'Our family loved this snack! These cheese-less things are delicious and are gluten free, vegan and allergy friendly. These are a must have snack!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","gluten_free","dairy_free_vegan","allergy_friendly"]', 'taste,gluten free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6075788baa30adc6236c47c49aa60a20', 'okendo', 'Celine Y.', 'Good snack for kids', 'My son loves these！They are super crunchy and thin，with a tasty cheese style flavor. My son keeps asking for more ， and I liked that they are baked and not greasy. Great snack for kids！', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunchy,thin,cheese flavor,baked,kids snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9ad8c86a76bc5e28f816432c72b5fea0', 'okendo', 'Andria L.', 'Healthy allergen-free snack', 'These crackers make for an enjoyable allergen-free (free from major allergens like dairy and gluten) and slightly addictive snack. I love that they are super light with a crunchy texture and some are salted to perfection on the top.  My initial thought upon tasting them is that they are a bit bland, but are also cheeseless (different from a traditional cheeze-it).  Overall, they are not super flavorful but I still enjoyed them.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["crunch_texture","allergy_friendly","addictive","bland_flavor"]', 'texture,saltiness,addictive', NULL, 'flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0dd9ffea89b626132476ec6bd0fcf307', 'okendo', 'Crista W.', 'Crunchy Crackers', 'These crackers are light and airy and a super think crunchy treat.  Unfortunately the flavor was a bit off and I missed the cheesey cracker taste.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["crunch_texture"]', 'texture', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('31fcea9de6e04f200fd54e9b82adaac9', 'okendo', 'Elizabeth S.', 'Not great!', 'Not great. They are super crumbly and dry. They did not taste great either. They had a little bit of sweetness like a cookie, but also a very strange undertone. I’ve had better gluten free cookies.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-06', 0, 'No', '', '', '["gluten_free","bland_flavor"]', NULL, 'texture,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('58a6160bb6a83280e5496979ee43f614', 'okendo', 'Elizabeth S.', 'Not a lot of flavor', 'These are thinner than I was expecting . They have little to no flavor. Kind of like cardboard. A little salt, garlic or onion would go a long ways.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-06', 0, 'No', '', '', '["bland_flavor"]', NULL, 'thickness,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('881ccfed8e254592048683c7d0cbb13b', 'okendo', 'Hana T.', 'Yummy chocolate chip cookies!', 'These chocolate chip cookies are good. They are not too sweet and not too hard to bite. They are crunchy and rich. This cookies are made with organic glyphosate free out flour. The cookies are gluten free, vegan and allergy friendly. They are small bites. The only problem is that it can be a little messy when eating these cookies.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","texture_issue"]', 'sweetness,texture,flavor', 'messiness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dd9581913e0e330902f678943c8703a1', 'okendo', 'Hana T.', 'Healthy backed crackers', 'This is a healthy baked crackers snack. It is made with healthy ingredients such as virgin olive oil, potato starch, brown rice flour and salt. The crackers are light, thin and crispy with cheesy flavor. They are not too salty which I prefer. It is gluten free, vegan and allergy friendly.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","too_salty"]', 'texture,flavor,saltiness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
