INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('94711e0832be7f1405dcfb7a0155c3e5', 'okendo', 'Elaine C.', 'Healthy snack you won’t feel bad about!', 'Love the clean ingredients and the crunch! It is much thinner than I expected and could use a little more salt but overall I love that the ingredients are transparent and healthy!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["crunch_texture","clean_ingredients"]', 'ingredients,crunch', 'thickness,salt', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
