INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a27d688cdc8bd2ae17b00f46cbdb8887', 'okendo', 'Nadine P.', 'Healthy & Delicious', 'We loved the cookies! They were very crumbly, yet delicious and soft. They were gone within minutes. I love that they are allergen-free and contain healthy ingredients. We will absolutely buy them again and include them in our regular snack rotation.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'texture,taste,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('61a17c31cbf217b1b2a93ec45c682c8c', 'okendo', 'Nadine P.', 'Healthy, but not very tasty', 'Our family wasn’t a big fan of the cheese-less thins. While they are much healthier than similar snack products and are allergen-free, they are very dry, thin, hard, and taste a bit bland. They were left mostly untouched on our table.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["great_taste","allergy_friendly","bland_flavor"]', NULL, 'texture,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8dee95c33136eb0d069a4396dae22cd3', 'okendo', 'Nwanneka I.', 'Tasty', 'The Every Body Eat Cheese -less Thins is tasty. I received it for free in exchange for my honest opinion. It’s crunchy and makes a great healthy snack. I like that it’s made with healthy ingredients. The ingredients are boldly written on the. Front of the bag so, you know what you are actually eating. The sizes a great for portion control.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,ingredients,portion size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('04ecb247c5273c4d372acaa31f2b7883', 'okendo', 'Manisha P.', 'Light and Tasty!', 'The chips are super light, cheesy and almost taste like healthy doritos. The ingredients are very clean with no added junk. The crackers were very flavorful and not bland. I ate the whole bag yesterday in 1 sitting. They are addictive and certainly a product I will buy! I dont feel guilty after eating them.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["great_taste","addictive","bland_flavor"]', 'texture,cheesy,taste,ingredients,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('644f66daccb7a43457faceb4946d6f8c', 'okendo', 'Nwanneka I.', 'Delicious.', 'The Every Body Eat Chocolate Chip Cookie Bites is delicious.  I like that it’s made with great healthy ingredients. It’s gluten free and a great choice for people who have allergies.  I like that the ingredients are boldly written on the front, that way you know what you are eating . I like the mini sizes so you for portion control. It’s tasty. It a bit dusty and crumbles easily. Other than that, it’s very tasty.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","gluten_free","allergy_friendly"]', 'taste,size,packaging', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2271fb91a714f6ce8f7eaae34d7f7ac9', 'okendo', 'Salma E.', 'So tasty', 'Amazing flavor of chocolate chip cookies and they look so cute any tiny perfect bite. The packaging is good and it a great size bag for snacking through the day.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","packaging"]', 'flavor,appearance,size,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
