INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3ee5bf5a59fbb1f856e39d555f7a96ad', 'okendo', 'Kawai H.', 'Great snack', 'Cookies are fantastic.  My kids are always looking for a tasty snack and we have found one in these.  Great flavor with just the right softness and crunch.  Great for our busy family as well are always in the go!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'flavor,texture,convenience,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dd74ba8cf73079f3ac9d103ab707e8ff', 'okendo', 'Kawai H.', 'Yum!', 'These are so yummy!  My kids are always looking for a something to snack o and they love these!  Easy to grab on the go, doesn’t go bad or stale with the closure package.  Great addition to our snacks!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["great_taste","packaging","stale"]', 'taste,convenience,packaging,kids', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bcf496d703182fd3b76d2b13cb476af0', 'okendo', 'MELISSA B.', 'Perfect allergy free little treat', 'First off, I love that these do not have any of the allergens that I am avoiding. The packaging is great and keeps the cookies crisp and doesn’t impart any flavor or smell to the cookies. The cookies smell great, like chocolate and oats, they are crispy and crumbly and perfectly sweet. They taste like oats and chocolate and are the perfect tiny treat. I will definitely buy these again.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["crunch_texture","allergy_friendly","packaging"]', 'packaging,texture,taste,smell,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('34f570f9f082812cc3b4087c26480ab7', 'okendo', 'MELISSA B.', 'Allergy free option if you enjoy the taste', 'The packaging of this product is great, as it keeps the crackers crisp and doesn’t give them a displeasing taste. The best part of this product is that it doesn’t have any of the allergens I am avoiding. I opened the package and the smell was strong, but not in the best way. It wasn’t bad just not that appetizing (perhaps due to the nutritional yeast). The crackers themselves were very crisp and have a lightly salty taste, but definitely not cheesy. That is where is goes awry. The aftertaste of these chips is bad. I don’t know what it is exactly, but it is very unpleasant. Maybe it is just me, but I couldn’t get past it. I tried them at three different times to make sure it wasn’t due to something I ate or drank prior, but it is always the same thing. I just can’t get past the aftertaste of these chips, no matter how healthy and allergy free they are.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["crunch_texture","allergy_friendly","packaging"]', 'packaging,texture', 'smell,aftertaste', 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c12770f69f5922fba565b26bf8cdb563', 'okendo', 'Gloria C.', 'Great value', 'Great taste and value, I like that they’re flourless and without any added sugar. I been trying to eat cleaner but snacks are a must sometimes, my daughters liked them so I’ll definitely be getting more', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","value_price"]', 'taste,value,flourless,no sugar', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('90d82f0d88e651eae0ac96d694e60abb', 'okendo', 'Gloria C.', 'Great taste', 'I’m on a gluten-free diet, and it’s been challenging to find snacks that I enjoy and are gluten-free. These are amazing! I love the flavor and texture. Plus, they’re great for my digestive system, so I’ll definitely be eating more of them.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'flavor,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
