INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d5248f4fee5be1d51255df398804b430', 'okendo', 'Apple M.', 'Cookie goodness', 'Every Body Eat chocolate chip cookie bites delicious and crunchy. Worth every bite with its clean ingredients.I received this complimentary for product testing.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","value_price"]', 'taste,texture,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c76b6b74e40ff81ca2448bcc8f5971f1', 'okendo', 'Apple M.', 'Every Body Eat crackers', 'Every Body Eat Cheese-less thins are so tasty and crispy. Taste like cheese without the cheese. Such a good clean snack. I received this complimentary for product testing.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,clean snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('48598c38c8829283f44e0232c850e77e', 'okendo', 'Mikala W.', 'Healthy cookie', 'I was also surprised by this snack. The cookie has a nice texture and great flavor.  Great for after school or on the go.  Also has a list of good ingredients.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-05', 0, 'No', '', '', '["crunch_texture"]', 'texture,flavor,convenience,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('675fa3c7f700068bed4c3a10acfb3765', 'okendo', 'Mikala W.', 'Cheese-less thins', 'I was surprised by this snack.  Even though the crackers a very thin.  They have a great crunch and flavor.  It paired perfectly with my work lunch. The ingredients are a nice healthy alternative.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["crunch_texture","good_replacement"]', 'crunch,flavor,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('695a4df0d68731eea9ca79dbdbc0f717', 'okendo', 'Lindsey M.', 'A miss', 'These were definitely a miss.  While the ingredients sound great, they honestly were extremely bland.  It lacked some sort of explosive flavor.  The crunch was good, though.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-05', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', 'crunch,ingredients', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('63b93dc489efde05c09d3f590ceb5e58', 'okendo', 'Brigitte C.', 'Good Flavor with a Crunchy Bite', 'I love that these chocolate chip cookies are gluten-free, vegan, and certified non-GMO. They have a nice crunch, though they’re a bit on the dry side. The flavor is good—you can definitely tell they’re made with oat flour, but it’s not unpleasant and works well overall.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","bland_flavor"]', 'flavor', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2c90464549b6ff1602db624d81eed227', 'okendo', 'Brigitte C.', 'Clean Ingredients, Underwhelming Flavor', 'I appreciate that these cheese thins are non-GMO, gluten-free, and seed-oil free. The texture is excellent—super crunchy and more like a chip than a cracker. Unfortunately, the flavor falls short and doesn’t really deliver that classic cheese-cracker taste.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture","gluten_free","clean_ingredients"]', 'texture,crunchiness', 'flavor,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9f7a9ce00ad85efa74e4ab8f55f86f60', 'okendo', 'Alysha O.', '5/5', 'These were actually surprisingly very good. My 4 and 6 year old enjoyed them as well. I appreciate the fact that it was made of healthy ingredients. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fbeb720568af8f1bc88f73f60125efcb', 'okendo', 'Kass H.', 'Amazing cookies', 'Yall! I cannot scream from the rooftops enough about this brand! I do have issues with gluten and they did not appear as much as they do now that I''ve gotten older. When I was younger, my parents often said that I was just faking it or to stop complaining, but I''m glad now to have confirmation it was not just me making things up. Which is why I''m so glad I got the chance to try these Everybody Eats Chocolate Chip Cookie bites!! 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bfe61bafbce8aeb6639d11af01da74a7', 'okendo', 'Jennifer R.', 'Great to-go healthy cookie!', 'The Every body eats chocolate chip bites came in a perfect size bag. I love the bold colors. They were a crunchy cookie, not doughy. I would prefer a little more chocolate flavor, but they still had a sweetness taste about them. I love the wholesome ingredients.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","stale"]', 'packaging,colors,texture,ingredients', 'chocolate flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('01b986474747433914fd6478626dd8ab', 'okendo', 'Jennifer R.', 'A tasty snack with healthy ingredients!', 'Every body eat cheese-less crackers were a nice surprise to try. The impressive 17 cracker serving size was a nice snack. The healthy ingredients are a comfort compared to other brands and the preservatives. For being cheese-less, they tasted and smelled like a cheese cracker. Packaging is clearly printed of ingredients for food sensitive people.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["great_taste","packaging"]', 'serving size,ingredients,taste,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('54311c38aa8763951821a0ae97cafe20', 'okendo', 'Darci B.', 'Perfect balance of crunch and taste', 'The Every Body Eats Cheesless thins are the snack that satisfies cravings of salt, "cheese" and crunch without compromising any food allergies. Its amazing how much they taste like cheese using alternative ingredients.  They have a little bit of bite to them being the perfect snack  i just wish the bag was bigger because trully its easy to finish in one sitting. .I highly recommend.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture","allergy_friendly","good_replacement"]', 'taste,texture,cravings', 'portion size', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5c71950977e7006c8294ed1d25bdc698', 'okendo', 'Brandi B.', 'Gluten Free chocolate chip cookies', 'I liked these. They are not your typical cookie bite but they are like crumbly little bites of tasty almost shortbread style cooked with chocolate chips in them.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["great_taste","gluten_free"]', 'texture,taste,shortbread style,chocolate chips', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6b6cf87f0b207f0932d8394919752ccc', 'okendo', 'Brandi B.', 'Not the best cheese cracker', 'I did not like these. If they were marketed as a different kind of snack, maybe they''d be acceptable. But these are not good. This basically is supposed to be a cheez-it style cracker snack. The crackers are super thin and very crunchy and hard. They do not taste cheesy, not even nutritional yeast cheesy. It''s like a weird funky chemical flavor. Maybe someone else would like them, but not for me.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture"]', NULL, 'texture,flavor,thickness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('15f0b2ffa3076127f70a1778170010aa', 'okendo', 'Lindsey M.', 'Great GF snack', 'These chocolate chip cookie bites are really tasty for being gluten free.  I really struggle to find good snacks that don’t have junk ingredients.  I have to say that I’m a fan.  They are crunchy but not too hard.  There is not an overload of sugary residue or taste that leaves behind aftermath.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","texture_issue"]', 'taste,gluten free,ingredients,texture,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b4a5f3e0d3c2e90eeb8e6b9ec936936d', 'okendo', 'Natasha M.', 'Taste like cardboard', 'These are awful they taste like cardboard i couldn''t even bring myself to finish them. I do not recommend these at all as they do not taste cheesy at all.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '[]', NULL, 'taste,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ffc43cd199000d52b8526e36d5bec84e', 'okendo', 'Kass H.', 'Delicious and healthy', 'You guys! Everybody Eats Cheese-less Thins have got me! As soon as I started eating, I couldn''t stop! They are so good and if you have issues with eating more than one bag of small chips and still not being satisfied, these are for you! The are so crunchy and healthy! They are gluten free and are school safe too! They are top 14 allergen free plus corn snacks. (gluten free, dairy free, nut free, soy free, and even corn free!). 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('208b00ce5c6342f5b3c299508885910a', 'okendo', 'Mallory C.', 'No thanks', 'I love a good cheese cracker but this isn''t it. They''re very thin and have a good crunch but they don''t taste like cheese. I know it says they''re cheese-less but it''s still not good. There''s not a strong taste of anything except for garlic on the backend. I wouldn''t recommend if you''re looking for a satisfying cheesy cracker.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture"]', 'texture', 'cheese flavor,thickness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('df5cb486f168d453ff070461a07fcd6f', 'okendo', 'Mallory C.', 'Maple cookie', 'Finding a good gluten free chocolate cookie is like looking for the holy grail. These Every Body Eat cookies will not be my top pick. They have a good crunch and consistency but the taste just isn''t there. They use maple sugar and it''s overpowering. It''s mainly a maple chocolate chip cookie. If you love maple syrup this cookie is definitely for you.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","gluten_free"]', 'crunch,consistency', 'taste,maple', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('95ad9178669c0a551da00b25faa0e558', 'okendo', 'Britney G.', 'New take', 'New take on a classic flavor cookie. Easy on-the-go snack.great for special diets or watching snack intake. Thoughtful eats from a thoughtful company.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '[]', 'flavor,convenience,diet', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6081d25e6abf9aeee19642d319219ff5', 'okendo', 'Britney G.', 'Crisp', 'Thin, crispy take on a cracker. Not much "cheese" flavor. Very crispy and thin. Easy on the go snack. Great for special diets and regulated eating.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture"]', 'texture,portability,diet friendly', 'cheese flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('76a2c8b83e621a975b9be11052b00663', 'okendo', 'Karina S.', 'Good and healthy option!!', 'These Chocolate Chip Cookie Bites have great presentation and thoughtful packaging, and I appreciate the quality ingredients and how they hold up without too much melting. The texture and overall sensation were fine, but the taste wasn’t my favorite, even though they worked well as a fun filled treat for my daughters during our home movie session in the snowstorm.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","packaging","stale"]', 'packaging,ingredients,melting', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4f1c3b6e703653736ec63062a6b253d9', 'okendo', 'Karina S.', 'The Best Crunchy Cheese-less snack!', 'OMG Cheese-less Thins have a light cheesy taste, delicious flavor, with and great smell, and I love that they have variety that is safe for allergies and easy to follow instructions.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'taste,flavor,smell,variety,instructions', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('298e6d8f1df06b44c7e9ec8f54c72711', 'okendo', 'Judy C.', 'Tasty', 'The everybody eat chocolate chip cookie bites are crispy yet the chocolate melts in your mouth. The packaging keeps them fresh overtime so you can enjoy them slowly. The sweetness level is just right. Great with a cup of milk.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'texture,packaging,sweetness,pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('da4d5f95bc7126a35ac43ad2a796d78c', 'okendo', 'Judy C.', 'Average', 'The cheese less thins make an attempt at being vegan style thin crackers but the taste is mostly vegetable like. The cracker is very thin and crispy. There is no smell or stickiness to the cracker.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan"]', 'texture', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
