INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cf69181b550cd124f7d5a286e30fd939', 'okendo', 'prmaria_6927', 'Bite sized cookies', 'These are bite sized chocolate chip cookies. I enjoyed the size and thickness. Decent flavor and not at all overly sweet. The family enjoyed them.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '[]', 'size,thickness,flavor,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7e6421cb32ad37c1452fb77f6f7d756d', 'okendo', 'prmaria_6927', 'Thin and crispy', 'I typically go for healthier options of food - looking for organic, less sugar, whole ingredients and sustainability claims. That said, this wasn’t very tasty. I did enjoy the thin, crispy texture but flavor was missing.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3f770b386670e27dd8cf6ffd9f1c450e', 'okendo', 'yuez3_5616', 'Crunchy', 'A mini bite chocolate chip cookie with flour and potato starch, a ingredient that I like. The cookie is crunchy, and allergy friendly. Contains rich, melty ,chocolate gems in every bite.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'texture,chocolate,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('71cae6c73f0afba361d100b48361b908', 'okendo', 'Mahya B.', 'Tasty!', 'Loved the taste of these cookies. They are crispy and perfect dipped in milk or with tea. The flavor is great as well and doesn’t taste chalky or weird like some gluten free treats.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,texture,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('246cf5311ce45681d7c1c272a35356db', 'okendo', 'yuez3_5616', 'Crunchy', 'Used brown rice flour, potato starch, virgin olive oil health ingredients . Thin crunchy sea salt, cheese flavor. Everybody eat, we should give it a try.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture"]', 'texture,flavor,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ce72575f0a83aed2ba83d61d28a189df', 'okendo', 'sandyrodriguez_4162', 'The perfecf tiny sweet treat', 'Although a full portion includes several of these tiny cookies, they’re so delicious that just having one could perhaps be enough to  satisfy your sweet tooth. I loved them and could not tell that they had been made without many of the ingredients found in other cookies. These are specifically made without the main allergens that affect people. Since I’m not allergic to anything that was not my concern, but I’m very glad. I tried the cookies because they are delightful. I would recommend them for anyone but especially people who might be sensitive to certain ingredients..', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'taste,portion', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f91894c45d3563b94c768e260d05929e', 'okendo', 'sandyrodriguez_4162', 'Dangerously delicious', 'I was expecting this product , which is made without the top 14 food allergens, to be similar to a cracker that I could eat with cheese on top. When I opened the bag, I discovered that there was no need to add anything. This snack is extremely flavorful, so delicious that you run the risk of finishing the whole bag by yourself in one sitting because it’s just that good. However, it’s not exactly similar to a cracker, I would say it’s more similar to a chip. Absolutely fantastic!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'flavor,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('25aaaaf4df05a4fa72dbe85ebf79621a', 'okendo', 'Samantha M.', 'MORE', 'Instructions was understandable.The value is good.Storage is good taste is good.Assembly is good.Nothing about this product that I would change our recommending.These products to everyone', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '[]', 'instructions,value,storage,taste,assembly', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bb798e1cc21264888b5cd8d5cb2c62ad', 'okendo', 'kcv1118_4940', 'Great for people with food allergies!', 'This company is so neat! I love their story that was written on the card with the freebie.  I don’t like these cookies (I have Celiac Disease) but my daughter doesn’t and she loved them.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["allergy_friendly"]', 'story', NULL, 'cookies', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b878fc40418e170b822472f51ae2ca63', 'okendo', 'kcv1118_4940', 'Delicious and free of most allergens!', 'These are so good! I have a better understanding of the company now that I read the card in the packaging. I have Celiac Disease so not being able to eat Chee$e-Its was a bummer. I really like these and can’t believe there is no cheese in these. Highly recommend', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["great_taste","allergy_friendly","packaging","false_advertising"]', 'taste,cheese flavor,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e93ce98acbf7e0b99f5a1f6f014af144', 'okendo', 'zwithgivenchy_4924', 'kinda crumbly but nice otherwise', 'The lightly sweet flavorful chocolate in this cookie is nice. The value is great because its shareable and the packaging easy to open & close. I love the vanilla aroma too', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["packaging"]', 'chocolate flavor,value,packaging,vanilla aroma', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8897874de3b1da8e69a90cd434ed6562', 'okendo', 'zwithgivenchy_4924', 'love cheese its? try these', 'the ingredients are light, clean, & nutritious. the size of the snack is shareable. the taste is a lighter more delicate cheese-it-type snack. the scent is very paprika garlicky. and the appearance are like chips meets a cracker hybrid.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '[]', 'taste,scent,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dd273feba3c1e667a46ac16673055cce', 'okendo', 'apricotwolf_3785', 'Yummy!', 'These little chocolate chip cookies are nice because they are crunchy they have lots of chocolate chips in just one bite and they are sweet, but not too sweet at the same time', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture,chocolate chips,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('35dbd9bc3dbcb2378df631b5de65967e', 'okendo', 'apricotwolf_3785', 'Surprisingly delicious!', 'These chips are such an interesting flavor because they taste and look like they have cheese, but they are in fact cheese less which totally works because they happen to be super addicting and have a nice snap to them being ultra thin it just works', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["great_taste"]', 'flavor,texture,addictive,cheese-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('49861199ddc77a35b64a5246715dcaba', 'okendo', 'swatir6_5284', 'Yummiest cookie', 'OMG these cookies are just sooo good. Love the size. Gluten free not much sweet, yet taste not compromised. No eggs considering my friends with allergies. Love the ingredients. Crunchy, choclaty  all that a kid in you may love. Thanks for the introduction influenster. It blew my mind.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly"]', 'taste,size,texture,chocolate', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c7758f48cd72e76c294cd5a6bb904fd0', 'okendo', 'fleureverfleury_6215', 'On Top Ice Cream', 'I love the ingredients in these, but they are very maple flavored. The maple over powers all of the other flavors so if you aren’t a maple fan, these aren’t for you. They are very crunchy, but also very dry. I didn’t care for them alone, but on top of yogurt or ice cream they worked great crumbled up. I think anytime you go into a healthier option thinking it will taste similar to its less healthy counterpart, there’s room for disappointment.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["crunch_texture","broken_crumbs","bland_flavor"]', 'ingredients,versatility', 'maple flavor,taste', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d1601b239c61f49b912c8d66bfcf1aae', 'okendo', 'lily25_5267', 'Ok', 'Not a fan, cookies are a bit dry. I understand it’s supposed to be a healthier version but there’s no flavor to it. And has a weird after taste to it.', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-04', 0, 'No', '', '', '["bland_flavor"]', NULL, 'texture,flavor,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a089c8b8ea6548a76e2cbbf00b0f4d5f', 'okendo', 'lily25_5267', 'Ok', 'Yo be honest these don’t have the best taste, they are to thin and not to much cheese flavor to it, packaging is nice it’s resealable. Nice ingredients.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["packaging"]', 'packaging,ingredients', 'taste,thickness,cheese flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('070c42fa2c54a52b762661db226c1490', 'okendo', 'fleureverfleury_6215', 'Salty Snack Satisfied', 'I love the ingredients in these, but the flavor takes some getting used to. I think anytime you go into a product thinking it will taste similar to its less healthy competitor, you leave room for disappointment. These don’t taste cheesy at all. They are more garlic and salt than anything. The crunch is good and they satisfy a salty craving. It’s a snack you can feel good about, but it’s not similar to any other option.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-04', 0, 'No', '', '', '["crunch_texture"]', 'ingredients,crunch,salty', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d273764f5b68ff1983df671df267bbe2', 'okendo', 'hartman_rn_8572', 'Clean ingredient cookies', 'Mini chocolate chip cookies with great ingredients. Tastes very good without the guilt of eating cookies. Bag is easy to close with zip closure. Will definitely buy more.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["clean_ingredients","packaging"]', 'ingredients,taste,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7ae98928cd0b1fb3a26f9e37a39a186c', 'okendo', 'hartman_rn_8572', 'crunchy clean crackers', 'Love the crunchy texture of the cracker. Great, clean ingredients that make me feel less guilty. Easy stove bag with a zip closure. Definitely would purchase this product again.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["crunch_texture","clean_ingredients","packaging"]', 'texture,ingredients,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e8815a4477958bc9a73be2ea359de016', 'okendo', 'brittanyyalvarezz_8416', 'Cheese It’s but butter!', 'These were amazing. I loved the crunchiness of the crackers. They weren’t overly cheesy either. They smelled so good the moment i opened the bag. It was like i was eating healthy cheese it’s and i honestly dislike cheese it’s. these are like wheat thins but cheesy. 10000/10 highly recommend!', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunchiness,cheese flavor,smell,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f15045ea91a40f20e8a2269fe92dc471', 'okendo', 'brittanyyalvarezz_8416', 'healthy cookies!', 'my first impression before eating them was that they may not even taste like a chocolate chip. they were crispy but tasted fresh. the packaging was super cute and appealing! after eating them i immediately wanted more!!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["crunch_texture","packaging"]', 'taste,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4038a71c65ea612304db848f29e90030', 'okendo', 'app2024_464', 'Dairy free', 'They are surprisingly delicious. Super crunchy, light and full of flavor. Perfect for snacking on their own or pairing with dips. A great dairy free option that doesn’t feel like you’re missing out!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan"]', 'taste,texture,versatility,dairy free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1051eb0f0180dbdfe6e02fa7d4834575', 'okendo', 'dorisy_4912', 'Great product.', 'My kids loved these and I love how they reseal back in the bag. Nice little healthy sweet treat to add to their lunch boxes. They did say that they tasted the salt on them. They like the texture and it wasn’t too crumbly for being gluten free.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["crunch_texture","gluten_free","packaging"]', 'texture,resealable,gluten free', NULL, 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4b68969585fc77389630967ae3caf3cc', 'okendo', 'dorisy_4912', 'Good healthy snack.', 'The taste is not the best. I love the protein count on them. We also love that it is gluten free and stays fresh in the resealable bags. I would say that the portion sizes are accurate and enough. I would eat them but my kids didn’t enjoy them', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["gluten_free","packaging"]', 'protein,gluten free,freshness,portion size', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f9d9fa8897028ca796a8bd912e1d5c32', 'okendo', 'tessad27_6848', 'Not bad, would be a great cookie crunch or crumble', 'This cookie actually has a pretty good flavor, judging by the looks of it i was expecting something chalky and bland. It is very crunchy and would benefit from more chocolate. I think the texture is a nice snack and would be great to add a cookie crumble on top of yogurt or ice cream.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', 'flavor,texture', 'chocolate', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f4512ab624fdf872321d594d469b9361', 'okendo', 'tessad27_6848', 'A flavorless cracker with a great texture', 'I wish these were not marketed as a cheese flavor. I found them almost flavorless. They needed more salt especially. Having said that the texture was really pleasant and the cracker itself is strong and would be great to use with dips.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', 'texture,strength,dips', 'flavor,salt', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5939fa7e1fb489e76b0884be146d27ca', 'okendo', 'Lanni N.', 'I like 👍', 'I really enjoyed these cheese-less thins! They are super crispy with a light, crunchy texture and not greasy at all .The flavor is surprisingly good even without cheese- savory, well- seasoned,and satisfying.they smell fresh when you open the bag and taste great on their own or paired with dips a great option for anyone looking for a lighter, dairy-free snack that still feels indulgent.', 4, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan"]', 'texture,greasiness,flavor,freshness,dairy-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6c6d7eb06e45f235e425bbff3b1a00e5', 'okendo', 'mamazelenock_6501', 'So good, reminds me of Famous Amous cookies', 'So yummy! The cookies are a little messy/crumbly, but have a nice crunch. They are bite size but still able to dip in milk. No bitterness or saltiness.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,size,flavor', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
