INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0ec44c57f358a5a6beaed0ab1baa27f6', 'okendo', 'saraf2788_6281', 'Great gluten free option', 'These were good but not my favorite. They have a nice flavor to them but are a little too dry for my liking. I like that they are a great gluten free option and contain no seed oils. I’m excited to try other flavors', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["gluten_free","bland_flavor"]', 'flavor,gluten free,ingredients', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('19ca74f33fdca5732a37869b7e480389', 'okendo', 'saraf2788_6281', 'Great cheez it alternative', 'These were delicious. They have a nice crunch and taste like cheese while being cheese-less. These are a great gluten free alternative. I love that they have protein and no seed oils in them. I will definitely be buying these again.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","good_replacement"]', 'taste,texture,gluten free,protein,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d72b4ce878b8a54a48e142de2080e271', 'okendo', 'caylac28_6477', 'Perfect', 'Super crispy and savory with light cheesy taste. Baked, not fried, so they feel less heavy. Perfect snack on their own. Eats to finish the bag. Highly recommended', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["crunch_texture"]', 'texture,flavor,preparation,heaviness,addictive', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6a99cbe1f91710f234fcde3960dd071c', 'okendo', 'caylac28_6477', 'Healthy treat', 'Crunchy with a nice chocolate chip flavor. It’s not overly sweet but still satisfying when you want a quick treat. It doesn’t taste diet. Yummy.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture,chocolate flavor,sweetness,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2a6636132de1fec9716988c6b74e7fb4', 'okendo', 'ortegafambam24_3404', 'Love', 'Finding inclusive treats that don''t compromise on flavor can be tough, but these Every Body Eat snacks are a standout for anyone managing dietary restrictions or simply looking for cleaner ingredients. These bite-sized treats are perfect for satisfying a sweet tooth while sticking to wholesome ingredients.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9101bf8e2e12d8b6f78e365c2d5fee1c', 'okendo', 'ortegafambam24_3404', 'Buy more', 'Finding a snack that is both allergy-friendly and actually tastes good can be a challenge, but these Every Body Eat Cheese-Less Thins are a total win for anyone navigating dietary restrictions or just looking for a cleaner snack option.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["allergy_friendly"]', 'taste,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2ae5a4582fa2289b5cc37a6d75a49d3f', 'okendo', 'jberry1210_4364', 'Great', 'These chocolate chip cookie bites are really satisfying for a gluten-free and vegan treat. They are crunchy on the outside with a nice dense bite and the chocolate chips are evenly distributed so you get chocolate and almost every bite. The sweetness is balanced and not overly sugary. with a subtle maple/caramel flavor from the sugar used. Only downside is if you’re looking for a soft cookie these actually might surprise you but overall, they taste great and I’d be happy to buy again.', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","repeat_purchase"]', 'chocolate chips,sweetness,flavor,taste', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3bcd53c3290b97f87b0169a031e2603c', 'okendo', 'jberry1210_4364', 'Good', 'These cheese thins are actually pretty good. They are super crunchy, light and have a savory cheesy vibe thanks to the nutritional yeast without tasting fake or overpowering the paprika and the garlic give her that nice depth and they’re not overly salty. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('267b914674f96f47c8edd0d793522cce', 'okendo', 'damarys_2635', 'Healthy snack', 'Overall I like the ingredients and the appearance of the packaging and the texture of the snack. The flavor was more on the dry side but I could taste the chocolate in the cookie.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["crunch_texture","bland_flavor","packaging"]', 'ingredients,packaging,texture,chocolate', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('911dd6b2852490ef3152625430c0603f', 'okendo', 'damarys_2635', 'Great taste', 'Great cheesy taste loved the texture and  the freshness. The ingredients and portions are listed there made gluten free dairy free which is a plus for me I can definitely taste the sea salt and garlic. I would definitely recommend great value and packaging.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","value_price","packaging"]', 'taste,texture,freshness,sea salt,garlic', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5d03c5b3cc5e99f2c0c568191ec7d2fc', 'okendo', 'dinorah77_8198', 'Good cookies with clean ingredients', 'They’re good, but the flavor is more flour forward than chocolate -forward. The Chocolate taste is very mild, and you can definitely notice the oat and cassava base mora than the chips. I do appreciate the clean ingredients and that they feel like a lighter snack, but they’re not super indulgent. Overall good but not a full 5 stars for me.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["clean_ingredients"]', 'texture,ingredients', 'taste,indulgence', 'flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b365938aa6695780827a356c263bee78', 'okendo', 'dinorah77_8198', 'Everybody Eat – Cheese-Less Thins Review', 'These are really delicious! They’re perfectly toasted with a light, salty cheese-like flavor that’s not overpowering. I love how crunchy and satisfying they are- definitely a greater snack I would buy again!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture","repeat_purchase"]', 'taste,texture,flavor intensity', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('245ab326343c875a80767bce9702e067', 'okendo', 'mamapeg84_8129', 'Your New Favorite Guilt-Free Snack', 'These are DELICIOUS! I love the ingredients and how clean they are. These crackers are free of seed oils, gluten, and sugars. They were so easy to snack on. I''m shocked there isn''t an ounce of cheese on them, making them vegan-they tasted so cheesy and good!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","dairy_free_vegan"]', 'taste,ingredients,texture,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('796af51625dcfe780947d6e6b174aa78', 'okendo', 'mamapeg84_8129', 'Your New Favorite Guilt-Free Dessert!', 'I love the ingredients in these cookies. I specifically love that they are gluten free, seed oil free, AND they only have 7g of sugar per serving. They are just the right amount of sweet, and my whole family (including teen kids) love them!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["gluten_free"]', 'ingredients,gluten free,sweetness,sugar content,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f334dfcc24e7db0b23ec41254660fd2f', 'okendo', 'janeta87_8847', 'Tasty cookies!', 'These cookies were delicious! They’re small and bite size so if you’re not paying attention you can overeat them they’re so good! They’re airy and crumbly so it can get messy but they are so good! I would give feed these cookies to my kids! Also love the ingredients as there is no allergens and preservative.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'taste,size,ingredients', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6cd3b99df7edf2540f200b2d77b19df0', 'okendo', 'janeta87_8847', 'Tasty chips!', 'These snacks are so good!  First time trying anything from this brand and I am very impressed! The cheese crisps tastes so good and I am very conscious of ingredients when purchasing snacks especially for my kids and I approve of the ingredients. Nothing that I can not pronounce and preservatives. I also like that the bag is resealable.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'taste,ingredients,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0018c92637c90fadb35eeddc64f6fe79', 'okendo', 'elizabethg620_4273', 'Allergen free and delicious', 'These reminded me of a clean version of Famous Amos cookies. They crumbled perfectly in your mouth and the primary ingredient of oat flour gave it the taste of an oatmeal chocolate chip cookie. I’d love to try the ginger cinnamon ones next with the oat flour. Delicious allergen free snack!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-03', 0, 'No', '', '', '["great_taste","allergy_friendly","broken_crumbs"]', 'texture,taste,oat flour,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e23a3580e7b15104a270f21672e70ca6', 'okendo', 'elizabethg620_4273', 'Delicious and clean ingredients', 'These really surprised me. When I saw nutritional yeast as the cheesy ingredient, I was skeptical. Even the first bite I wasn’t sure because it wasn’t exactly a cheddar flavor. But then I couldn’t stop eating them…so much so that I forgot to take a picture of a cracker. Would totally buy again.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-03', 0, 'No', '', '', '["great_taste","repeat_purchase","clean_ingredients"]', 'taste,addictive', NULL, 'flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('190904a9b26945675870c0d1dae78b34', 'okendo', 'jinxfluencer_8162', 'Not as healthy as the cheeseless thins', 'I was really excited to try these because I have a toddler that loves cookies but obviously I can’t always give him cookies. I love that these use natural ingredients that are listed on the front of the package, but woo boy. The smell of these is… not appetizing. They taste amazing though! But because the smell is so strong (somehow smells like turmeric or curry or something along those lines) I don’t think you’ll be able to trick a toddler into eating these. They’re also really high in saturated fats', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-02', 0, 'No', '', '', '["packaging"]', 'natural ingredients,taste', 'smell,saturated fats', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('808e4dc839e52c8b2c554b0f956447f0', 'okendo', 'jinxfluencer_8162', 'Healthy snacks', 'I got these in today and ripped open the bag because I was excited to try them. I love that all the ingredients are listed on the front of the package. I expected them to look more like cheez-its because of the picture on the bag, but they’re way thinner. They taste great (but also taste healthy if that makes sense)', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-02', 0, 'No', '', '', '["packaging"]', 'ingredients,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('03bfc911ada84a9dfdb9571929babf8c', 'okendo', 'valeries227_2880', 'Just ok', 'I didn’t care for these. They didn’t have a whole lot of taste to me. They were sweet and crispy and did not leave any after taste. They seal well and seem to stay fresh.', 3, 'neutral', 6, 'Chocolate Chip Cookie Bites', '2026-02-02', 0, 'No', '', '', '["crunch_texture","packaging"]', 'sweetness,texture,aftertaste,freshness', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cad369c46f44d6b492f68974bceea99b', 'okendo', 'valeries227_2880', 'Just ok', 'I didn’t care for these but my husband said they were ok. They are very thin and crispy but not toasty like Cheeze It’s. They are light weight. If you needed to follow a strict diet then they would be good because they are dairy and gluten free. They seal well and seem to stay fresh.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-02', 0, 'No', '', '', '["crunch_texture","gluten_free","packaging"]', 'freshness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d4f8a089d6fd5dcd11e3fb9879fb6c80', 'okendo', 'lupitam101_5297', 'Delicious snack', ', these cookies have a flavor with garlic, salt and cheese they are very thin with a soft texture, but crunchy the flavor is somewhat strong, so it is felt in the first bite my children, they liked them a little, but the other family liked it c a snack that they can be eating at any time they are low in gluten their texture makes them delicious', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-02', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'flavor,texture,gluten', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('518e1dd997aa172139c6d45fdabd54bd', 'okendo', 'Sarah R.', 'Wouldn’t Recommend', 'Unfortunately, I am not a fan of these crackers.  There’s only a hint of a cheesy taste, and they almost taste stale.  I wouldn’t recommend these crackers.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2026-02-02', 0, 'No', '', '', '["stale"]', NULL, 'cheesy taste,stale', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2d7aa373b7885afb65711f2b06e0b7ad', 'okendo', 'Natasha M.', 'Not good tasting at all', 'These are not very good they are edible but have a dusty dry protein taste to them im not a fan and won''t be buying these unfortunately and that is a problem I have with most gluten free treats', 2, 'negative', 6, 'Chocolate Chip Cookie Bites', '2026-02-02', 0, 'No', '', '', '["gluten_free","bland_flavor"]', NULL, 'taste,texture,gluten free', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
