INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3f7fbf6a790506ad10a6df65622069f1', 'okendo', '_mdanner_7101', 'SO good', 'First of all, I absolutely love the minimal ingredients. I am GF and DF so this was perfect for me. This are the perfect afternoon snack. They’re crunchy and slightly cheesy (without dairy!). I will be purchasing.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-02', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients"]', 'ingredients,texture,flavor,snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
