INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('40444d04ff8d0ca6b2c65f0f755e890f', 'okendo', 'shamiman2_7931', 'Crunchy snacks', 'These cheese-less thins are light, crispy, and surprisingly flavorful on their own. They have a nice crunch with a clean, savory taste that works well for snacking or pairing with dips. A great option when you want something simple, crunchy, and not too heavy. Portion amounts of packed is perfect.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-01', 0, 'No', '', '', '["crunch_texture"]', 'texture,flavor,snacking,portion', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('aa2144a7d9f7718596c123615a0be8a3', 'okendo', 'shamiman2_7931', 'Great for snacks', 'These chocolate cookie bites are perfectly sized and packed with rich chocolate flavor. They’re crisp on the outside,soft on the inside, and super satisfying without feeling too heavy. Not too sweet,Great for snacking straight from the bag or pairing with coffee or milk.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-01', 0, 'No', '', '', '["crunch_texture"]', 'size,flavor,texture,sweetness,snacking', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
