INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a5ba80b49a9c8a18339db53a181e0238', 'okendo', 'vato_8113', 'Tastes like fresh made cookies!', 'So tiny with such big flavor! The perfect little snack that you don’t have to feel guilty about eating. They are light and airy with a rich buttery chocolate taste. Delicious!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-01', 0, 'No', '', '', '["great_taste"]', 'size,flavor,texture,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('25dac5acca8814bff94e38851449bc92', 'okendo', 'rebeccab715_8011', 'Just ok. Not cheesy enough', 'They’re just ok. They say bold cheesy flavor. I totally disagree (then again I’m from Wisconsin and maybe my expectations are higher ha!). I do like how crunchy they are. I like they have chunks of salt, and they aren’t messy. Ingredients seem decent. But overall little bland. I’ve had stronger flavored cheese snacks.', 3, 'neutral', 1, 'Cheese-less Snack Thins', '2026-02-01', 0, 'No', '', '', '["crunch_texture","bland_flavor","stale"]', 'crunchiness,salt,messiness,ingredients', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f2d3666b19581a88021151772b5223f3', 'okendo', 'vato_8113', 'Can’t just eat 1', 'Shut the front door! These little baked cracker squares 100% taste like they are made with real cheese. I cannot believe they are cheeseless. Delicious, thin, and crunchy!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-02-01', 0, 'No', '', '', '["great_taste","crunch_texture","false_advertising"]', 'taste,texture,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
