INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e1ca245aec2200bab03f33c54e91654f', 'okendo', 'tienv10_2515', 'Not my favorite', 'This flavor isn’t quite for me, and I’m not a big fan of the aftertaste. It may suit others’ preferences, but it’s not my favorite. The cookie-like texture with a strong ginger spice is a bit more intense than I prefer.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2026-02-01', 0, 'No', '', '', '["crunch_texture"]', NULL, 'flavor,aftertaste,ginger spice', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3fcb8666f4d2713c889e2d4e8843c8e4', 'okendo', 'tienv10_2515', 'Great snack', 'It’s my child’s new favorite snack! It’s quick and easy to pack, tastes great, and the bag is bigger than a typical snack size, which makes it perfect for travel.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-02-01', 0, 'No', '', '', '[]', 'taste,convenience,size,portability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
