INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('27d9b2fa0e3ea6764240c3105bed8144', 'okendo', 'cristinh6_7772', 'So good', 'I could eat this entire bag in one sitting. They are good but in a I don’t know if these are phenomenal or not so I’m going to keep eating them type of way. They are crispy delicious. For gluten and dairy free, they are very good.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-01', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan"]', 'taste,texture,gluten free,dairy free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7401cbdbe2e43983ce005b9ce631752a', 'okendo', 'tiffr_6132', 'Yum!', 'Found my new favorite snack! These cookies have a perfect crunch and just enough sweetness. Love the clean, vegan, and gluten-free ingredients and all the flavor variety. Totally delicious!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-02-01', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan"]', 'crunch,sweetness,ingredients,flavor variety,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8fa87091397d93ad976cf0f01d725df3', 'okendo', 'tiffr_6132', 'Delicious!', 'For a light, healthy snack, these crackers are perfect. I appreciate their satisfying thin crunch and delightful flavor, which provides a refreshing change from typical cheesy options. The fact they are plant-based, gluten-free, and dairy-free is an added bonus!  They have the perfect amount of crunch and they are the perfect size for snacking or dipping.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-01-31', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan"]', 'texture,flavor,size,plant-based', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('af55a4ccae9a38d5a407bb0de1ed6cf7', 'okendo', 'alondramakk_8413', 'Love it', 'The Everybody Eat Chocolate Chip Cookie Bites are such a great snack when I’m craving something sweet but still want cleaner ingredients. They’re soft, flavorful, and have a really good balance of sweetness without being overpowering. The chocolate chips add the perfect touch, and they honestly taste like a homemade treat.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-01-31', 0, 'No', '', '', '[]', 'texture,flavor,sweetness,chocolate chips,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1e71246958a89e7ba436c4d5f55582d8', 'okendo', 'alondramakk_8413', 'Like it', 'I was honestly impressed by the Everybody Eat Cheese-Less Thins. They’re super crispy, flavorful, and don’t taste bland like a lot of gluten-free or vegan snacks do. The seasoning is really well balanced, and you can definitely taste the nutritional yeast, which gives them that cheesy vibe without any dairy.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-01-31', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","bland_flavor"]', 'crispy,flavor,seasoning,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('eced40520c35a572aa557ff35267bfc9', 'okendo', 'jetjess534_7177', 'Simple ingredients', 'These are sweet and light, made with oat and cassava flour with a hint of sea salt which I love!! Vegan,  gluten free treats are not easy to come by, but this one was so good the whole bag disappeared shortly after we opened it 😁', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-01-31', 0, 'No', '', '', '["great_taste","gluten_free","dairy_free_vegan","clean_ingredients"]', 'taste,ingredients,texture,vegan,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('904d37248ea073330d2ebde3c688797a', 'okendo', 'jetjess534_7177', 'Crunch salty goodness!', 'I love a tasty gluten free snack, especially when it’s got a sea salt sprinkle and is not fried! I enjoy this with hummus or smoked salmon and they really complement other food flavors well. 3 grams of protein as well!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-01-31', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,gluten free,sea salt,not fried,protein', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c979f971a498fc61bbf23cd27fa644e2', 'okendo', 'tanekaw_5664', 'CRUNCH. CRUNCH!!!!!', 'The CRUNCH is everything!!! They have been the perfect potato chip replacement and I don’t feel an ounce of guilt after eating them. This may sound weird to most another thing I love about the thins is the texture. It is perfectly light and extra thin and full of flavor with a perfect bland of sea salt . I’ve found them to be a perfect addition to my charcuterie board while giving it it a nice little switch up from the typical cracker…. I know the label says pretzel but my taste buds describe the pretzel thins as more of a cracker.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-31', 0, 'No', '', '', '["crunch_texture","good_replacement","bland_flavor"]', 'crunch,texture,flavor,thinness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c1e5d2ec56ad9f740dee246e9efef064', 'okendo', 'isabelled198_6921', 'Soooo good!', 'Smells like cinnamon heaven! These cookie bites are a great combo of crunchy and chewy! It’s a pantry staple! Love that the ingredients are clean and they are always fresh!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-31', 0, 'No', '', '', '["crunch_texture"]', 'smell,texture,ingredients,freshness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b3054d6ee9fde5330e985a9350f6eb0a', 'okendo', 'isabelled198_6921', 'Yummy!', 'Tasty and healthy pretzel thins! Such a great snack to take on the go! Love that it’s made with great ingredients. They are gluten free and they are baked, not fried. Great snack!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-31', 0, 'No', '', '', '["great_taste","gluten_free"]', 'taste,portability,ingredients,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cba8bdcef6b77b1251bdfab28f91a7bf', 'okendo', 'heatherg392_6920', 'Treats without seed oils', 'These were soo amazing. I am so happy that there are treats made without seed oils and without a huge long list of toxic ingredients. My toddler and I ate these a little too fast. I can''t wait to get more. They are the perfect sweet treat!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-01-31', 0, 'No', '', '', '[]', 'taste,ingredients,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('97d6f9a923c4ca5493bb2394fcb423f9', 'okendo', 'dariak68_5343', 'Soft, chewy cookie bites', 'I really enjoyed Every Body Eat Chocolate Chip Cookie Bites! The texture is soft and slightly chewy, which makes them feel fresh and satisfying. The chocolate chips are well distributed, so you get a little bit of chocolate in every bite. They’re sweet but not overpowering, and I appreciate that the ingredients are simple and thoughtfully made. They look cute and appetizing right out of the bag, and they’re perfect for a quick snack with coffee or tea. Definitely a treat I would keep on hand.', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2026-01-31', 0, 'No', '', '', '["crunch_texture"]', 'texture,chocolate chips,sweetness,ingredients,appearance', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('de061c1378a3a981f85ceb0b860e0547', 'okendo', 'dariak68_5343', 'Crispy, clean-ingredient snack', 'I was pleasantly surprised by Every Body Eat® Cheese-less Thins! The texture is light and crispy, with a nice crunch that feels satisfying but not too heavy. I love that they’re dairy-free yet still have a rich, savory flavor. The ingredients are simple and clean, which is important to me. The aroma is mild and natural, and there’s no artificial aftertaste. They make a great snack on their own or paired with hummus or a light dip. Definitely a good option if you’re looking for a plant-based crunchy snack.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-01-31', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan"]', 'texture,flavor,ingredients,aroma,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e24991f72ec593f041571e707d21fa6f', 'okendo', 'heatherg392_6920', 'Healthy Cheez Its', 'These crackers are really delicious! They are gluten-free and do not contain any seed oils. They taste very similar to a cheez it but much healthier. They are super crunchy and have the perfect amount of salt.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2026-01-31', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,texture,saltiness,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
