INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8800b765bce03858ed81ec0448b707d0', 'okendo', 'ashee1987_2437', 'Love', 'These were absolutely delicious. I would totally purchase them again. I love the texture and the taste of them. It’s the perfect amount of food for a snack too.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-31', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,portion size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5713574aca3683dcaab335686b7765a7', 'okendo', 'robertswife74_6343', 'Ehhh...', 'I got this product free from Influenster for a fair and honest review. I tried these because I got them to try, however, I don''t know if I really liked them. They were nice and thin and crispy, not too much salt even though they were sea salt flavored. Initially when I took a bite into it, they tasted pretty decent. However, after a while, they had a funny app taste that I didn''t really care too much for. I would maybe use it as a chipped for a dip or something like that. When I buy it just to eat plain, probably not.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-31', 0, 'No', '', '', '["crunch_texture"]', 'texture,saltiness', 'aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
