INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9d9373c82b6985fbff367e67b07a2a0f', 'okendo', 'beckyb192_7618', 'Tastes like gingerbread', 'The ginger cinnamon was not my favorite. It smelled delicious, was very fresh, reminded me of a gingerbread . It was easy to eat, no crumbs due to small size. I would definitely buy these if I loved ginger.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-29', 0, 'No', '', '', '["great_taste","broken_crumbs"]', 'smell,freshness,size', 'flavor,ginger', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
