INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c473d04554e7f28e9a05a69168979bb6', 'okendo', 'lbdmama3_473', 'Delicious, Wholesome Cookies', 'These are delicious. The wholesome ingredients make me feel good eating them! Nice bite sized pieces, convenient packaging, and good portion sizes.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-29', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,ingredients,size,packaging,portions', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d4956ed1b3ac730ea60f23b3d7b2fa8c', 'okendo', 'laurier43_242', 'Spicy, Snappy, and Snack-Worthy!', 'The Every Body Eat Ginger Cinnamon Cookie Bites are everything I want in a snack. The cinnamon is warm, the ginger has just the right kick, and the crunch is perfect. I love the bite-sized pieces because they’re easy to grab and go. Bonus points for being made with whole-food ingredients and free of the top 14 allergens. My only tiny gripe is the crumbs, but that’s a small price to pay for cookies this good. Definitely a repeat buy.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-29', 0, 'No', '', '', '["crunch_texture","allergy_friendly","broken_crumbs"]', 'cinnamon flavor,ginger kick,crunch texture,bite size', 'crumbs', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('08c2cf8f87860eac7b3ce80a3ddccfc6', 'okendo', 'yuliyat9_618', 'Great product', 'When I opened box with product I liked aroma. Packaging is durability is good.  Product has great value and weight of the package. Overall is really good product to try.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-29', 0, 'No', '', '', '["value_price","packaging"]', 'aroma,packaging,value,weight', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8f02a08c24a77edef58593153b300a85', 'okendo', 'yuliyat9_618', 'Good product', 'When I tried this product I was feel really good texture in every bite. After checking ingredients inside that product I was amazed freshness and cleanliness.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-29', 0, 'No', '', '', '["crunch_texture"]', 'texture,freshness,cleanliness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f9a1f8493c327f71c7006f8b0066e666', 'okendo', 'laurier43_242', 'Gone Before the Party Ended', 'I grabbed Every Body Eat Sea Salt Pretzel Thins for a party since I had several gluten-free guests, and let me tell you, they were a hit with everyone! I set them out with a few yummy dips, and they were gone by the end of the night. The crunch is perfect, the flavor is spot on, and they hold up great for dipping. These are officially a party staple in my house and I’ll definitely be buying them again.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-29', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","stale"]', 'crunch,flavor,dipping', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('16bf9f49a10d7ef1eeb5db0572946fd2', 'okendo', 'margaritalaw_4409', 'Ginger Cinnamon Cookies with Great Flavor, but Ver', 'The cookies have a pleasant flavor with a well-balanced combination of ginger and cinnamon. They are not overly sweet, and the aroma is rich, making them a great match for tea.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9161b35795cc75fb129d5c6ca5383dd1', 'okendo', 'margaritalaw_4409', 'Great Crunch and Amazing with Guacamole', 'These Pretzel Thins are thin, crispy, and perfectly balanced — not overly salty, just clean, satisfying crunch. I love how versatile they are: great on their own, with cheese, hummus, or dips. My personal favorite combo is with guacamole — seriously so good.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-29', 0, 'No', '', '', '["great_taste","crunch_texture","too_salty"]', 'texture,saltiness,versatility,pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4c1734104acc3e037bb512fad2869977', 'okendo', 'erikar211_4401', 'Just okay', 'I like that the ingredients are clean and minimal. The packaging is nice. The product stayed fresh. I dont particularly care for the taste. Its bland. Given the nature of the product it was kind of expected.', 2, 'negative', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-29', 0, 'No', '', '', '["bland_flavor","packaging"]', 'ingredients,packaging,freshness', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
