INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2163501abf4e6766893cd7724239cce6', 'okendo', 'micaelak11_6897', 'Delicious, crispy and nutritious', 'Overall good crispness and snap, quality ingredients, flat pretzel texture, delicious taste. Will be purchasing these again in the near future.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-28', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crispness,ingredients,texture,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('65a57c8d029741d8ee9a79279d82f690', 'okendo', 'micaelak11_6897', 'A healthy cookie alternative', 'Good quality ingredients, mouthfeel is overall rather dry, aftertaste isn’t bad, quantity is decent for the price, crumbly and packaging is easily recognizable at the health food store after purchasing.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-28', 0, 'No', '', '', '["good_replacement","bland_flavor","packaging"]', 'ingredients,aftertaste,quantity,packaging', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('95f83750779758c62d14e70c573e9292', 'okendo', 'legigi_8262', 'When you want a pretzel and cracker!', 'Just like I have a sweet tooth. Sometimes, I sometimes need to satiate my craving for something salty and crunchy. This was perfect. Since I love crackers and I love pretzels but most of what is sold has pretty terrible ingredients. I can usually tell if I don’t feel so great after eating something. These are not greasy, and don’t make a crumbly mess. They just thick enough for crunch but not hard to bite through. I would definitely purchase this again! I can’t wait to try some of the other flavors they have!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-28', 0, 'No', '', '', '["crunch_texture","stale"]', 'texture,crunch,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f4519d07a155585d763599ed78d8cb30', 'okendo', 'legigi_8262', 'Not overly sweet, and the perfect treat!', 'These little cookies. Have a really nice crumbly texture without being dry. They are well. Balanced not overly gingery or overly cinnamony. And definitely not too sweet. They helped with my cravings when I wanted something sweet, and the bite sized cookies made it perfect to grab the serving size portion or less and be satisfied. I did hide them from my husband because they wouldn’t have lasted more than a day if I hadn’t. I loved them! Ingredient list is pretty clean. Love that, too!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-28', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', 'texture,flavor,sweetness,size,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ef185d7ad3ee77a327e75b2cece01eeb', 'okendo', 'crystalh102_3046', 'A great snack', 'The mixture of sweetness with the tough of ginger takes you away.  I would’ve never thought to combine them myself.  It feels like a playground of happiness in your mouth.  Mouthwatering.   They are cute little snacks and perfect for munchies.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-28', 0, 'No', '', '', '[]', 'sweetness,ginger,taste,size,snacking', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
