INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0aed8ce08cfb0dfc5093419a835ca5f6', 'okendo', 'olenastyle_2127', 'Crunchy, salty, and super snackable', 'These pretzel bites are so good and easy to snack on. They’re crunchy with just the right amount of see salt, not too salty and not bland. Their crunchy texture is light and crisp, and they feel satisfying without being heavy. I love grabbing a handful when I want something salty and simple. Definitely one of those snacks you keep going back to.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-25', 0, 'No', '', '', '["great_taste","crunch_texture","bland_flavor","too_salty"]', 'texture,saltiness,taste,snacking', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
