INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8550a2e64efb213db7df85f7e386e714', 'okendo', 'natalies484_6702', 'MUST try—VERY delicious!!!', 'I always like to try new, healthy foods, and was very excited to try these pretzel thins. They taste incredible and have a nice, crispy crunch. The added sea salt takes the flavor and scent to another level. The ziplock packing allows the pretzels to maintain its freshness for a long time (although they probably won’t last long in your pantry)! 
