INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8d9604fd2eedbd2d6b99ec4bc19c9865', 'okendo', 'toann15_7948', 'as good as midnight snack', 'I tried the pretzel flavor, and it was salty and crunchy. The taste was simple but very satisfying. It had a nice baked smell that made me want to keep eating it. I liked how the salt balanced the soft and chewy texture. I think the pretzel flavor is a snack that many people would enjoy.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-21', 0, 'No', '', '', '["crunch_texture"]', 'taste,texture,smell,saltiness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6c0f5d60f2e19a68a8cb9a94ac0e28b6', 'okendo', 'toann15_7948', 'Midnight snack', 'I tried sampling ginger cinnamon, and the flavor was warm and spicy. At first it was a little strong, but after a few bites I really started to enjoy it. The ginger gave it a fresh kick while the cinnamon made it sweet and comforting. It smelled really good and made me feel cozy and relaxed. I think it is a tasty treat that most people would enjoy eating.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-21', 0, 'No', '', '', '["great_taste"]', 'flavor,ginger,cinnamon,smell,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
