INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('eb13d0ebfa44c7e1abc90189e6b9434d', 'okendo', 'dungp8_902', 'Good with tea', 'Nice warm ginger flavor with a clear cinnamon finish. Crunchy at first, then slightly chewy. Not overly sweet, which I liked, though the texture can feel a bit dry. Good with tea, but not a classic soft cookie experience.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-20', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', 'ginger flavor,cinnamon finish,sweetness', 'softness', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
