INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e2f3597b9772bbffb861c76abffd1573', 'okendo', 'amandat408_4356', 'Crunchy pretzel thins- so good!', 'I love these little pretzel thins! They are crunchy and salted and taste great with dips like hummus or with some goat cheese. They are crispy and easy to eat. The ingredients seem pretty clean but they are a comfort food at the same time.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-17', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture,taste,saltiness,ingredients,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ab27b7d4b7196dae61802b5d8876bf23', 'okendo', 'amandat408_4356', 'Delightful little cookies', 'These little cookies are awesome! They are crispy, small round cinnamon ginger little delights. They smell and taste like a cinnamon treat. They are great dunked in coffee!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-17', 0, 'No', '', '', '["crunch_texture"]', 'crispy,size,cinnamon,taste,coffee pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7d51b892cb45b6ba0457c89712214045', 'okendo', 'everythingwithhira_1682', 'Great on their own or with a dip.', 'These are light, crispy, and nicely salty without being overpowering. They feel clean and simple not greasy and the crunch is really satisfying. I like that they’re baked, gluten-free, and allergy-friendly, so they feel like an easy, guilt-free option when you want something savory.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-17', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly"]', 'texture,saltiness,greasiness,baked', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('292c8e00a8900d1bf40d59f08c5f1e96', 'okendo', 'Gloria Lifschutz', 'Yummy', 'Great snack crackers. VERY tasty 😋. Healthy too!!!', 5, 'positive', 4, 'Sea Salt Chia Snack Thins', '2026-01-17', 0, 'Yes', '', '', '["great_taste"]', 'taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('adb0a81e226b9bffd07a19f9d77e8206', 'okendo', 'trangt16_5578', 'My fav snack', 'The Every Body Eat Ginger Cinnamon Cookie Bites are a cozy treat that’s been hitting the spot during my pregnancy in steamy Pembroke Pines, Florida. On flavor, the warm blend of spicy ginger and aromatic cinnamon shines through without overpowering—it’s like a mini gingerbread cookie with a subtle zing. Chewiness is spot-on: soft and tender with just enough bite to feel satisfying, not crumbly or tough. Packaging is practical with a resealable 5oz pouch that keeps them fresh and easy to stash in my bag for quick snacks. Sweetness is balanced perfectly—not cloying, thanks to natural date-based sweetness that curbs my cravings without a sugar crash. Ingredients impress with their clean profile: chickpea flour, dates, coconut oil, ginger, cinnamon, and sea salt—all gluten-free, nut-free, and vegan, making them ideal for my allergen-conscious household. Overall, these bites are delicious and guilt-free—highly recommend for anyone seeking wholesome indulgence!
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fd3f59f430843faa4c233e2573946d1c', 'okendo', 'trangt16_5578', 'Tastes good', 'The Every Body Eat Sea Salt Pretzel Thins have become my go-to snack in humid Pembroke Pines, Florida, satisfying pregnancy cravings without guilt. On texture, they’re delightfully crisp and thin, with a satisfying crunch that’s not too hard on the teeth—perfect for munching straight from the bag. Portability is excellent; the resealable 4oz pouch fits easily in my purse or diaper bag for on-the-go nibbling during errands. Freshness holds up well, staying crunchy even after a week opened, thanks to the airtight seal. Assembly isn’t needed—it’s ready-to-eat right out of the package, which is a huge plus for busy days. The condition upon arrival was impeccable, with no broken pieces or staleness, arriving fresh and intact. Overall, these gluten-free, allergen-friendly thins are flavorful and versatile—great with dips or alone!
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0c50ba09f88d9e6e518a85d832974400', 'okendo', 'marieldeleon_6139', 'Subtle ginger flavored cookie.', 'The cookies are soft but crispy. Flavor is not to sweet and it has a subtle ginger taste. They smell like winter cookies, and I liked them paired with a cup of tea.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-17', 0, 'No', '', '', '["crunch_texture"]', 'texture,sweetness,ginger taste,aroma,pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('32a7ba1018e3a4019fd4f1f62d56db7c', 'okendo', 'marieldeleon_6139', 'Perfectly crispy and salty.', 'These pretzels are so good! I’ve never been a pretzel person, but after trying these I’m definitely going to re buy! They’re crispy, thin, the perfect salty flavor. They’re good on their own or paired with guacamole for a more satisfying snack.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-17', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crispy,thin,salty flavor,texture,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d77f05340926b57cf789c7d5d29164ad', 'okendo', 'everythingwithhira_1682', 'Great taste', 'These ginger cinnamon cookie bites are such a cozy little snack. They have that perfect crunchy-at-first, chewy-inside texture, and the ginger-cinnamon flavor is warm without being overpowering. I like that they feel indulgent but still light enough to grab for a quick snack, especially with tea or coffee. Bonus points for being allergy-friendly and vegan.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-16', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan","allergy_friendly"]', 'texture,flavor,snack size,pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('51a6a459b10346d6e318411d34a0ea74', 'okendo', 'ariapro_1451', 'Super crunchy!', 'Thin, crispy, lightly salted. These are gluten free, which makes them easier on the stomach. I like to dip mine in hummus. The packaging is resealable too which makes storing is easy and keeping them fresh is even easier.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-15', 0, 'No', '', '', '["crunch_texture","gluten_free","packaging"]', 'texture,saltiness,gluten free,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
