INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('52eebba22cd1ee7a1a04b7bd4e73f45e', 'okendo', 'nmsuclg_1385', 'Taste great but no crunch', 'The flavor of these cookies was very good! They’re reminded me of snickerdoodles. They are advertised as being crunchy, then chewy, but all I got was chewiness. Since the flavor was really good I didn’t mind it, but it is something to be aware of since the crunchiness was missing. I do love that they’re gluten free and seed oil free though!', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-15', 0, 'No', '', '', '["crunch_texture","gluten_free"]', 'flavor,gluten free', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5b818427a99f59611ca8bac432b60516', 'okendo', 'nmsuclg_1385', 'Perfect Crunch and Saltiness!', 'I absolutely love these pretzel thins!! They have a really nice crunch and the perfect amount of salt. They’re very flavorful; I would l have never guessed they were gluten free and baked! They’re not low calorie but they weren’t advertised as such so treat them like you would any other snack!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-15', 0, 'No', '', '', '["crunch_texture","gluten_free"]', 'crunch,salt,flavor,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8539e5b513ddc54e8c15ed212d153b57', 'okendo', 'chen01yu_4052', 'Crispy, Light, and Addictively Snackable', 'Every Body Eat Pretzel Thins are the kind of snack you keep reaching for without feeling weighed down. They’re perfectly thin and crunchy with just the right amount of salt, making them satisfying without being heavy or greasy. They feel like a smarter snack choice, great on their own or paired with hummus, dips, or nut butter. Simple ingredients, clean taste, and an easy go-to when you want something crunchy but not overly indulgent.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-15', 0, 'No', '', '', '["crunch_texture","clean_ingredients","addictive"]', 'thin,crunchy,salt,ingredients,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f4efdaf7b782b9b8048bccbbd83c1322', 'okendo', 'chen01yu_4052', 'A Guilt-Free Cookie That Actually Tastes Good', 'Every Body Eat Ginger Cinnamon is a surprisingly delicious cookie that feels like a treat but aligns with healthy eating. The ginger and cinnamon give it a warm, lightly spiced flavor without being too sweet, and it tastes wholesome rather than processed. It’s satisfying without feeling heavy, making it perfect for a snack when you want something sweet but still nourishing. You can really tell it’s made with simple, intentional ingredients. If you’re looking for a healthier cookie that doesn’t sacrifice flavor, this one hits the mark.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-15', 0, 'No', '', '', '["great_taste"]', 'flavor,sweetness,texture,ingredients,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('43fd04854d855a32d565f5679a0230f9', 'okendo', 'diemn19_5222', 'Great taste!', 'These pretzel thins are light, crispy, and perfectly seasoned. They’re not too salty and have a great crunch. Very easy to snack on without feeling heavy. A solid gluten-free option', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-15', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","too_salty"]', 'texture,seasoning,saltiness,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
