INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5d4af86ddbc4254ad446ee9e10131ad2', 'okendo', 'chermainec_7315', 'Perfect Healthy Sweet Treat', 'It was really delicious! The perfect amount of sweetness and on par with fall/winter season! I also love that the ingredients are clean. I like that it is gluten free and vegan friendly.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-14', 0, 'No', '', '', '["great_taste","gluten_free","dairy_free_vegan"]', 'taste,sweetness,ingredients,gluten free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e5446b11efc0c0ad9975db6e51f71b99', 'okendo', 'lizberry562_5381', 'Love these pretzels!!', 'LOVE! As someone that can''t eat dairy or gluten, these are incredible. I am a HUGE fan of pretzels… I had to stop myself from eating the whole bag in one sitting. They have a great flavor and crunch, and come in convenient resealable packaging. I look forward to trying their other products. So grateful for a company making healthy products that those of us with dietary restrictions can enjoy!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-14', 0, 'No', '', '', '["crunch_texture","packaging"]', 'flavor,crunch,packaging,dairy free,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
