INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7aa4600dec4214766016f91648dc790a', 'okendo', 'hillaryh57_9381', 'The clean, crunchy snack I keep reaching for', 'These are officially my new go-to crunchy snack. Light, crispy, and perfectly salty without feeling heavy. I love that they’re gluten-free and made with clean ingredients — but still taste like a classic pretzel.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('924bc545dc6fbf4985b6c92e4f175fdd', 'okendo', 'hillaryh57_9381', 'A cozy, spiced treat that tastes way more indulgen', 'These taste like a cozy afternoon in snack form. Warm cinnamon, a little ginger spice, and that perfect crunchy-chewy bite. I can’t get over how indulgent they feel while still being vegan and allergen-friendly.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f7b0a44da5419e285ec361ba6b90e302', 'okendo', 'poonamc1_2022', 'Delicious and Clean Cookie Bites', 'I like Ginger Cinnamon Cookie Bites. The cinnamon comes through warm and slightly sweet, with a light hint of ginger (I do wish the ginger flavor was a bit stronger, though). The texture is soft and chewy inside, even if it’s a little crumbly, nothing that bothered me, but probably not the best for serving at parties. What I really love is how clean and simple they feel; you can tell they’re made with good ingredients, and it’s nice knowing they’re allergen-friendly and gluten-free. They pair really well with coffee or tea and make a comforting, feel-good treat when I want something sweet but not heavy.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-13', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","allergy_friendly"]', 'cinnamon flavor,texture,ingredients,coffee pairing', NULL, 'ginger flavor', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('12679ffe77b7b5a33519b544babe8b5d', 'okendo', 'dianes22_6934', 'Crisp', 'I got Sea Salt Pretzel Snack Thins for snacking. They are crispy and have a great pretzel flavor. I love to use them for dipping. They are gluten-free, grain-free, and dairy-free.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-13', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan"]', 'crispy,pretzel flavor,dipping', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
