INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9b9885064a218847e8e199054252fe3d', 'okendo', 'kellschen41_5149', 'Yummy!', 'I received this product for free in exchange for my honest review. The pretzel thins are very crunchy and easy to chew. The flavor is very unique because it has salt but also some spices. The pretzel thins are very yummy!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-12', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunchiness,texture,flavor,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
