INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0b90672c19348c24da149fa92d658aa9', 'okendo', 'rimab22_2172', 'Very satisfying.', 'I really enjoyed these pretzel thins. They are light, crispy, and have a nice balanced saltiness without being overpowering. The thin texture makes them easy to snack on, and they don’t feel too heavy. I liked that they weren’t overly crumbly and held up well when eaten alone or with dips. Overall, they’re a tasty and satisfying snack option.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-12', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'texture,saltiness,durability,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
