INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fde25b0d829dec49ecf92d065b96a184', 'okendo', 'rimab22_2172', 'Yummm', 'They were fresh, light, and nicely crisp with each bite. The portion size is convenient for snacking and easy to enjoy on the go. They feel satisfying without being heavy, making them a good option for a quick snack or pairing with tea or coffee. The packaging keeps them fresh, and the quality feels consistent throughout the bag.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-10', 0, 'No', '', '', '["crunch_texture","packaging"]', 'freshness,texture,portion size,portability,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
