INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d6326ac3e138af9b32f69f17f7476a67', 'okendo', 'smitaj1_4472', 'Delicious and soft', 'The ginger cinnamon cookies are delicious and soft. They melted in my mouth. It’s full of flavors and is made of clean and fresh ingredients. It’s not too sweet and has just the right amount of sweetness. The packaging keeps it fresh for a long time.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-09', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,texture,ingredients,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1e8d05dddd75fed9034cbf771ad39236', 'okendo', 'pri17cess_9510', 'Simple ingredients yet tasty and healthy', 'It smells so good when you open the bag. Very strong cinnamon scent. It is very tasty. I like the size of the small cookies. Only 8g of sugar for 5 cookies and it tastes sweet. There are tiny bits in there that gives a crunch on random bites. It has simple and readable ingredients.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-09', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients"]', 'smell,cinnamon,taste,size,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
