INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4e5e51c5a9d137995aabda112a55b6a2', 'okendo', 'carolinel110_1747', 'Love it', 'Soft, chewy, and perfectly spiced 🍪✨ These Ginger Cinnamon Cookie Bites have a cozy flavor with just the right balance of sweetness and warmth. Love that they’re gluten-free, vegan, and allergy-friendly — they taste comforting without feeling heavy. A great little treat with coffee or tea!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-09', 0, 'No', '', '', '["gluten_free","dairy_free_vegan","allergy_friendly"]', 'texture,spicing,flavor,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d2e50b46a0697c6ab284039436f79ee7', 'okendo', 'carolinel110_1747', 'New fav', 'Crunchy, light, and perfectly salty 🥨 These Sea Salt Pretzel Thins are baked (not fried), super crispy, and don’t feel heavy at all. Love that they’re gluten & grain free, vegan, and made with simple ingredients. Great on their own or with dips — an easy, tasty snack!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-09', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan","clean_ingredients"]', 'texture,taste,ingredients,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7a6d2c2f8646ec1911c7661be57341ea', 'okendo', 'tinatboysmom_8387', 'Crunchy and healthy', 'The Every Body Eat Sea Salt Pretzel Thins are crunchy and fun to eat. I was happy to see if they are baked and not fried and that they are allergy friendly. These pretzel bands could definitely be used to dip in a little guacamole for another type of healthy dip. The bag is easy to close so storage is easy and they are just the right size to go right into your mouth so there is no mess from crumbs.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-08', 0, 'No', '', '', '["crunch_texture","allergy_friendly","broken_crumbs"]', 'texture,baked,packaging,size,dipping', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3de63720aae6e42e07a35dfec2588aee', 'okendo', 'tinatboysmom_8387', 'Crunchy and chewy', 'The every body eat Ginger Cinnamon cookie bites are a small bite filled with a lot of flavor. You definitely start with a crunchy start, but it is very chewy on the inside. You can definitely taste the ginger and the cinnamon. Although there are other things such as carrot, fiber, grape juice, rice, syrup, and flaxseed in this cookie bite, you do not taste those flavors. There is Kane sugar and meatball sugar in it although they are not too sweet.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-08', 0, 'No', '', '', '["crunch_texture"]', 'flavor,texture,ginger,cinnamon,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d36c5d023315291437832ef89bcaa927', 'okendo', 'chaup12_2980', 'Try it !!!', 'The Sea Salt Pretzel Thins and Ginger Cinnamon Cookie Bites are both delicious. The pretzels are crispy and salty, and the cookies have a lovely ginger flavor. I like that they are vegan. They''re perfect as a snack while watching movies.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-08', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan"]', 'taste,texture,saltiness,vegan,snacking', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
