INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('19e94d62768af2e43c8f8132925724f4', 'okendo', 'mafernunez86_1138', 'Great product', 'Very good snack!!! Awesome flavor!! Great ingredients. Easy to care in my bag everyday for a quick bite. Love the smell and the texture good product', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-05', 0, 'No', '', '', '["crunch_texture"]', 'flavor,ingredients,portability,smell,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('35ce6b5ed0e524602d3337c755b4486d', 'okendo', 'kayleeh173_311', 'Very tasty pretzels', 'Want a healthier option for pretzels that taste good? Then these are perfect and easy for traveling. They have the perfect crunch and not over bearing where it feels like you’re going to break teeth lol. I love how the package is sealable.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-05', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'taste,crunch,texture,packaging,portability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('96b114f15b78930fb3f5c6e7f56c5c16', 'okendo', 'kayleeh173_311', 'Healthy to go snack', 'I love the flavor of these snacks, but I love they’re so healthy. It’s a sealable bag so easy to take with you to travel. They’re so easy to chewy and they do not leave a bad after taste.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-05', 0, 'No', '', '', '["great_taste","packaging"]', 'flavor,packaging,texture,aftertaste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
