INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6d0834c18dc06611b2cc3c7d31c8ceed', 'okendo', 'hollyn105_9684', 'Good to taste', 'I actually really love these cookies after so skeptical but it’s very good. Good flavor sweetness is perfect. It’s a very good cooking. I will buy these again.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-04', 0, 'No', '', '', '[]', 'flavor,sweetness,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f32e2a783e684587fbdaf67db6b403d3', 'okendo', 'kellyl396_4032', 'Taste is poor', 'I was not a fan of these. I felt that they had way too many carbohydrates for the serving size. And no protein these are things I look at from a diabetes standpoint. They were crunchy, but I felt that they lacked in flavor and were bland I wish the packaging was single serving sizes.', 1, 'negative', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-04', 0, 'No', '', '', '["crunch_texture","bland_flavor","packaging"]', 'texture', 'carbohydrates,protein,flavor,packaging', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a2013565636ae7476a684e1752d7bfff', 'okendo', 'kellyl396_4032', 'Too many different types of sugars', 'I was not a fan of the flavor however they were a nice serving size. There was lots of different types of sugar, which I was not a fan of. I felt like I was basically eating the sugar bomb. I wish they had more protein in them, the texture was as described, but not my favorite and they were consistent in shape and flavor throughout the', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-04', 0, 'No', '', '', '["crunch_texture"]', 'serving size', 'flavor,sugar content,protein', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
