INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6bb993ca5df21497945cb44462337458', 'okendo', 'solaceandfelicity_4448', '⭐️⭐️⭐️⭐️⭐️ Everybody Eat Ginger Cinnamon Cookie Bi', 'These cookie bites are so good. The moment you open the bag, you get a warm, cozy ginger-cinnamon aroma that smells like fresh-baked treats. The flavor has the perfect balance of sweetness with a gentle spicy kick from the ginger—not overpowering, just enough to make each bite exciting.
