INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('711f25dcb019bc3725c98d8a27d978b4', 'okendo', 'tupal2020_7946', 'Great flavor', 'Unlike many vegan, and gluten free snacks these have no strange aftertaste.  They chew like a cookie bite and have a nice cinnamon flavor.  They come in smaller 5oz portions in an attractive, resealable bag.   The price per portion is a bit pricey so they would be a good occasion treat but not something I would purchase for an everyday snack.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-03', 0, 'No', '', '', '["gluten_free","dairy_free_vegan","packaging"]', 'taste,texture,flavor,packaging', 'price', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4ac3b0f1e5c4b96825468614b50635c2', 'okendo', 'tupal2020_7946', 'Taste great', 'The sea salt pretzel things are a great vegan  snack option.  They are gluten and grain free but have a nice crispy pretzel taste and snap.  They are lightly salted so it is not over powering.  My only issue is that the retail price is a bit steep for the portions you receive.  It would definitely be an occasional treat and not a main staple.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-03', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan"]', 'taste,texture,saltiness', 'price,portions', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('28a242fd943a7e377c439d87baadb77f', 'okendo', 'fadouae4_9314', 'Delicious', 'You just open the package and the scent of ginger comes out. Very pleasant. This is very tasty and it didn''t last long. I will definitely buy that product again', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-03', 0, 'No', '', '', '["great_taste","packaging"]', 'scent,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f2d49dcaa9a2906ae0ab78b6750206d8', 'okendo', 'lmakrenzke_9174', 'Good!', 'These aren’t as good as the ginger cookies but they’re also a good gluten free snack. If you are looking for something salty these will do the trick. They’re really thin and light.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-03', 0, 'No', '', '', '["gluten_free"]', 'gluten free,salty,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e2bd3e3644f65a41a1715fedde38b555', 'okendo', 'lmakrenzke_9174', 'So good!', 'For a gluten free product these are so good! I will be repurchasing them. They have a great flavor and overall have good ingredients. The bag is a good size and they’re a good snack size treat.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-03', 0, 'No', '', '', '["great_taste","gluten_free"]', 'flavor,ingredients,bag size,snack size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ae2eafc47c7a1c0512811a2d060e7391', 'okendo', 'marlenee12_4347', 'Perfect Salty Snack', 'These pretzel thins were exactly what I expected. They are really thin, but packed with flavor. I loved munching on this and I can’t wait to buy some more. They are crunchy and crisp.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-03', 0, 'No', '', '', '["crunch_texture"]', 'thinness,flavor,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bff5197efa1378d4b933e21e0569badc', 'okendo', 'marlenee12_4347', 'Chewy and Delicious', 'I was so happy to try these Ginger Cinnamon cookies because they are made with simple ingredients and I feel good eating them. They are gluten and vegan, but you wouldn’t be able to tell! The flavor was balanced and the texture was chewy. I loved the size too! I appreciate packages that are resealable so these were a hit.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-03', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan","clean_ingredients","packaging"]', 'flavor,texture,size,packaging,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6094af3240e08523befba083d69c7f00', 'okendo', 'nadiac2008_3579', 'Great', 'Every Body Eat Sampling Ginger Cinnamon has a warm, inviting flavor with a nice balance of spicy ginger and sweet cinnamon. It’s comforting and smooth, making it enjoyable as a tea or wellness drink. The sampling size is perfect for trying it out before committing to a full package. Great option for anyone who likes natural, soothing spice blends.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-03', 0, 'No', '', '', '["packaging"]', 'flavor,texture,sampling size,spice blend', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
