INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ec0104872e2686d76c5285d8d57ba2f9', 'okendo', 'fluffyknowles_4003', 'Yummy!', 'My kids are seriously obsessed with these!! They are super good and weirdly filling. They wanted more after they were all done even though they’re really thin they didn’t break apart super easily or anything the whole family love them we inhaled the bag.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-02', 0, 'No', '', '', '["great_taste"]', 'taste,filling,durability', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fc8b522c35bf4b86808a2bc5084a6c73', 'okendo', 'fluffyknowles_4003', 'Tastes so good and fantastic ingredients', 'I put these in both my kids lunches and they absolutely love them! They ate the whole bag within two days, which is why I don’t have any pictures! They smell good. They taste great and they feel like they should have way more sugar than they don’t they have all natural ingredients. It’s seriously amazing.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-02', 0, 'No', '', '', '["great_taste"]', 'taste,smell,ingredients,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('75ebc4c8dc4d381a6169847cf59c8d54', 'okendo', 'katiecat_1517', 'Tasty!', 'I really enjoyed the taste and texture of these cookies. Comes in cute packaging and are easy to munch on. I appreciate the ingredients and fee quilt free eating these.  I will be purchasing these in the future!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-02', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'taste,texture,packaging,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
