INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7734142d2960dc35e4d6fc447ba3e238', 'okendo', 'natalyay4_7616', 'So yummy and addicting', 'I love these so much! The ingredients are great and clean. The are super thin and super crunchy. What a yummy yummy snack. I can’t stop eating them! Perfect with some hummus or another great dip!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-02', 0, 'No', '', '', '["great_taste","crunch_texture","addictive"]', 'ingredients,texture,taste,pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a522b76aefe0cdbf7508f20dab8af048', 'okendo', 'natalyay4_7616', 'Great ingredients!', 'These are OK. They remind me of cinnamon cereal. They have good flavor and great ingredients. But the downside is that they taste a little stale and old. Great with a good cup of tea.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-02', 0, 'No', '', '', '["stale"]', 'flavor,ingredients', 'freshness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c4df545d605af5e88a6a28ce89d0db50', 'okendo', 'jennyanne411_8239', 'Bland and underwhelming', 'I wanted to love these. The ingredients and lack of allegens excited me. The story behind the creators and their mission to provide great tasting, healthy snacks had me at hello. The packaging is perfect. It really focuses on how healthy they are and makes them look delicious! However that was not my experience after opening them. They didn''t have any salt at all on most of the bag. They are borderline TOO thin and pretty bland. Great, they''re healthy,  and most healthy snacks don''t have the most taste, but I was looking forward to something different.  Definitely on the right track though. Maybe just add more salt and work on the recipe taste wise.', 2, 'negative', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-02', 0, 'No', '', '', '["great_taste","bland_flavor","packaging"]', 'packaging', 'salt,thickness,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fdd16d000c7d6babc700b8ccb2a577a5', 'okendo', 'jennyanne411_8239', 'Dry and crumbly, bad aftertaste', 'I was excited to try these! The ingredients and lack of allergens and crap was enticing! The packaging made them look delicious and the description made me optimistic. Unfortunately, they didn''t live up to my expectations.  They were dry and crumbled when you took a bite. They smelled really good but didn''t taste good. And opposite of what was said of them, they definitely had an aftertaste and it wasn''t pleasant. They also look VERY powdery in the bag. Not like the photo on front showed. My advice would be to keep the packaging and description, they surely reeled me in. But adjust the recipe to make them more appetizing. On the right track with the goal, healthy snacking and packaging.', 2, 'negative', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-02', 0, 'No', '', '', '["great_taste","allergy_friendly","broken_crumbs","bland_flavor","packaging"]', 'packaging,smell', 'texture,taste,appearance', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e95f146c4d444b026aac2114ea646d87', 'okendo', 'klovato_8951', 'Amazing healthy snack', 'I have never tried this brand before, but I will say they are so amazing. They have such a great taste and I love how it’s free from the top 14 allergens, corn and seed oil.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-02', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
