INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ed3bdfd61c1cc161a814f0c695303c22', 'okendo', 'jennam486_7189', 'Delicious snack!!', 'These are delicious!! They taste so good, you''d never know they''re healthy. Love the clean ingredients. Some ginger products can be way overpowering but this is just the perfect hint of ginger flavor. The cookies aren''t gritty or dry either.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-02', 0, 'No', '', '', '["great_taste","clean_ingredients","bland_flavor"]', 'taste,ingredients,ginger flavor,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2f1cd63b6da6d3963a82c4f59ee6b46c', 'okendo', 'jennam486_7189', 'Addicting!!', 'These are DELICIOUS. The perfect amount of crunch without a dry, gritty feeling/taste that you get in a lot of other GF products. I''m obsessed and can''t wait to try the other flavors. Amazing with cheese, hummus, chocolate hummus, guac/salsa.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-02', 0, 'No', '', '', '["great_taste","crunch_texture","bland_flavor"]', 'taste,texture,gluten-free,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bdc9f6fd58075fb7f7885553c721d754', 'okendo', 'annieo30_9116', 'Satisfyingly salty snap', 'The Every Body Eat Sea Salt Pretzels are a total revelation for anyone used to the dense, tooth-breaking texture of standard gluten-free snacks. These thins trade the traditional knot shape for a light, hexagonal "shatter-crunch" that feels more like a gourmet pita chip than a heavy pretzel. They hit that savory craving perfectly with a generous dusting of sea salt and a toasted, nutty flavor—impressive considering they are entirely grain-free and nut-free. Whether you’re using them as a sturdy shovel for hummus or eating them straight from the bag, they provide a satisfyingly salty snap without the inflammatory ingredients or the "gummy" aftertaste of corn-based alternatives.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-01', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly","good_replacement"]', 'texture,taste,sea salt,grain-free,crunch', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a03a838e051bb83d3cd58cf489701b8a', 'okendo', 'annieo30_9116', '"clean" indulgence', 'If you’re looking for a snack that hits that "warm spice" craving without the inflammatory aftermath, the Every Body Eat Cinnamon Ginger Thins are a legitimate find.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4de7b7f67c141be9de9c1338c9e65f23', 'okendo', 'wr7_5764', 'Great pretzel crackers!', 'These crackers taste delicious and are very crispy. Has the right amount of ingredients. Smell yummy and the color is appealing. I would definitely buy again.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-01', 0, 'No', '', '', '["great_taste","crunch_texture","repeat_purchase"]', 'taste,texture,ingredients,smell,appearance', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1331a028dff9b5e52c86a8d583b89abd', 'okendo', 'wr7_5764', 'Delicious healthy cookie', 'The package looks very modern and cool. The cookies taste good and healthy. Right amount of sweetness and melts in your mouth. They are bite size and round.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-01', 0, 'No', '', '', '["great_taste","packaging"]', 'packaging,taste,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e65bc617a915fee7f70ae75d68c01718', 'okendo', 'opinionista_9049', 'Crispy, Light & Addicting!', 'I received the Sampling Pretzel Thins (4 oz) as a complimentary sample in exchange for my honest feedback, and they were so good! They’re perfectly thin, light, and super crunchy with just the right amount of salt.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b848a7830104851bbe36e0f3a547fae8', 'okendo', 'opinionista_9049', 'Warm, Spicy & Comforting Flavor!', 'I received the Sampling Ginger Cinnamon (5.0 oz) as a complimentary sample in exchange for my honest feedback, and I really enjoyed it. The combination of ginger and cinnamon is perfectly balanced — warm, slightly spicy, and very comforting. It has a natural, soothing flavor that feels both cozy and refreshing.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f4c51ce586f652f762306a0a320f021c', 'okendo', 'margarets176_1149', 'Tasty, Satisfying, Plus Clean Ingredients', 'The Ginger Cinnamon Cookie Bites have a wonderful smell upon opening. On the package they say crunchy and then chewy. They are mildly crunchy and very chewy. I love the subtle oatmeal and spice flavors. For me, after the first bite there was a slight aftertaste, but not an unpleasant one. My very picky son loves these cookies and I love the clean ingredients. The size is cute and you don’t need many cookies to feel super satisfied with the flavor and texture.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2026-01-01', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","packaging"]', 'texture,flavor,smell,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('600dc2b1ecfdef57f2e23c7405f1e94e', 'okendo', 'margarets176_1149', 'Great Taste, Snap, Crunch and CLEAN Ingredients', 'The Every Body Eat Sea Salt Pretzel Thins are a phenomenal, healthy snack. They are so crisp, crunchy and satisfying. Great by themselves, they are also wonderful with cheese, hummus and even a bit of honey. I love them more than I have ever loved a pretzel. The snap and taste is superb. My family loves them and I am so pleased with the clean ingredients as well! I am so picky when it comes to processed foods and these check all the necessary boxes for our family.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2026-01-01', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients"]', 'texture,taste,ingredients,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2be1922cdfabcd6186c32cd13a345967', 'okendo', 'emilyp1044_8074', 'Great Pretzel Alternative', 'These are amazing for a pretzel alternative. They are super crunchy. They do not easily break. They would be great for dipping and scooping without the risk of breaking mid scoop. I love that it is non GMO, free of seed oils, gluten free, and free of the top 14 allergens.  There is no weird aftertaste. The saltiness is perfect. You get a hint of salt without feeling like you have to brush any off. It’s perfectly salted. When you bite the chip there are no crumbs! My 3 year old ate them and liked them but didn’t come back for more. Probably because it is a pretzel and we aren’t normally pretzel snackers unless there is a dip involved. The only way they could be better is if they were 100% organic. I would buy them again!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-31', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly","good_replacement","broken_crumbs","stale"]', 'crunch,durability,saltiness,taste,dipping', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ab430882b344bc51831ea72bb19ef4e0', 'okendo', 'emilyp1044_8074', 'Great Healthy Cookie', 'These cookies taste great. They taste like the holidays. The ginger and cinnamon mixture is just right, not too spicy, and very flavorful. They smell just like they taste, like a cozy fall day. They are very soft crumbly cookies. Not very crunchy but also not very chewy. Just the perfect mixture between the two. There are chewy pieces of ginger inside which is amazing.   My 3 year old loves them too. The packaging was great and resealable. Ingredients list is amazing. I love that it is non GMO and free of seed oils and the top 14 allergens. Only way it could be better is if it was 100% organic. Otherwise this product is great!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-31', 0, 'No', '', '', '["crunch_texture","allergy_friendly","too_spicy","packaging","stale"]', 'taste,texture,spice level,ginger pieces,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6b9c524fb0824a171f50151430e81d4c', 'okendo', 'sedae_1131', 'Love it!', 'Yum!! I love a healthy gluten free snack aka dessert. This ginger cinnamon snack is great. Good flavor, nice crunch, extra thin, fresh and delicious! The bag is resealable to keep fresh and easy to add into my yogurt for extra flavor and another layer of goodness!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-31', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","packaging"]', 'flavor,crunch,thickness,freshness,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1c94a3170dbcfe0fc9d3e6b6c7f9bee8', 'okendo', 'sedae_1131', 'Too good', 'Delicious pretzel thins with a amazing crunch every bite. Extra thin and very flavorful. The bag is a resealable which helps keep the item fresh. The taste is great and for filling my pretzel cravings!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-31', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'taste,crunch,thickness,flavor,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
