INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('10421a34a0037c7b7c6ee28b59d127f6', 'okendo', 'tashap12_7171', 'Everybody Eat Ginger Cinnamon Cookie Bites', 'As a fan of ginger and cinnamon, I had high hopes for these! They taste pretty good, but I found them a little dry for my liking. My husband loved them though — he went to town and there were hardly any left for photos!
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8e97e461d53c74ea6d255bf2f4a184e6', 'okendo', 'jameelaf_2798', 'Gluten free snack', 'First bite - crunchy but not hard crunch. The seasoning is perfect, not too salty. It pairs well with sandwiches and hummus, tuna salad or spinach dip. I give this one a thumbs up if you''re looking for a gluten free, healthy snack.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-30', 0, 'No', '', '', '["crunch_texture","gluten_free","too_salty"]', 'texture,seasoning,pairing,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
