INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('de2076c038783d35dc3cd7a5257ea3a1', 'okendo', 'angiekay264_5580', 'Amazing taste!', 'These are fabulous and so addictive! The fact they are gluten free is amazing! They are so crisp like a chip in pretzel flavor. Great crunch and on the go bag size!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-30', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","addictive"]', 'texture,flavor,packaging,addictive', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7bdccc1bd1f2d7b9ee1fec8e4042fd2c', 'okendo', 'angiekay264_5580', 'Great taste', 'The ginger cinnamon cookie bites have a really great taste.  They taste like baby snickerdoodles.  For being dairy and gluten free these taste excellent.  My only critique is the texture which I understand considering they are free of all allergens basically', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-30', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","allergy_friendly"]', 'taste,dairy free,gluten free', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('439b9b4e66cfe8bf12b3cae7f63c86fa', 'okendo', 'meganp253_8686', 'Nice', 'I love the structure of these pretzels. It feels like a wheat thin but has pretzel flavor. The salt is very scant and unnoticeable. The bag they come in has a seal on it for freshness. I did enjoy these but they are much different than the salty pretzels I’m used to.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-30', 0, 'No', '', '', '["packaging"]', 'structure,texture,flavor,packaging', 'salt', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4c51bf7a4b9309ee0e47d64c101d940a', 'okendo', 'meganp253_8686', 'Interesting', 'I forgot how much I despise ginger until eating one of these. It is very present as a flavor in these cookies. I do love the size of them and the texture is nice and soft. Packaging is very high quality and easy to open. I love that the bag reseals for freshness. Overall, I did not enjoy these cookies but I would be interested in trying other flavors.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-30', 0, 'No', '', '', '["crunch_texture","packaging"]', 'size,texture,packaging', 'ginger flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7af1534140deaa95f4b5a0fa0cda9045', 'okendo', 'marcelam77_6053', 'Like', 'These are very very thin, with barely their salt, and don’t taste too much like pretzels. They are light, crunchy, and overall addicting. We really enjoyed these as a snack. Thee bag was gone so quick.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-30', 0, 'No', '', '', '["crunch_texture"]', 'texture,addictive', 'thickness,salt,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
