INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('17762cd411e73ccd1048008ce8100084', 'okendo', 'eldiarioafro_8021', 'My husband loves it!', 'Just delicious. I am addicted to these. As a vegan who doesn’t enjoy most desserts because they are too sweet and have too much sugar, these are AMAZING! Good for those people who are on diet.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-30', 0, 'No', '', '', '["great_taste","dairy_free_vegan","addictive"]', 'taste,sweetness,vegan,diet', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
