INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d266b8461ec58d2a848c1fa00fc4615b', 'okendo', 'lindac351_7120', 'Very addictive', 'Wow these are delicious and addictive. You can taste cinnamon and subtle sweetness in every bite. It’s good to know the ingredients are gluten free and made of non gmo. The packaging is sealed good with ziplock style.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-30', 0, 'No', '', '', '["great_taste","gluten_free","addictive","packaging"]', 'taste,cinnamon,sweetness,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b8c3a4c050feb3cde24615c3fecd6319', 'okendo', 'john Evak', 'Been Looking for THIS!', 'These thin pretzel chips are a crave satisfier for gluten/grain free people.   So happy I came upon them accidentally...I love pretzels, but all the other gluten free have corn and I am allergic to corn, so these are GREAT!.   Lite and crispy and lightly salty to please that crave.  Perfect.   Thank you.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-29', 3, 'Yes', '', '', '["crunch_texture","gluten_free","allergy_friendly"]', 'texture,saltiness,thickness,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f069398f8d0cf3de81640d4666424098', 'okendo', 'clarahernandezr_475', 'Super crunchy!', 'These were really good. The crunch is amazing—super crisp and satisfying. The sea salt flavor is well balanced and they’re great on their own or paired with dips. I’d definitely buy these again and keep them as a go-to snack.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-29', 0, 'No', '', '', '["crunch_texture"]', 'crunch,sea salt,texture,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
