INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b727d17be77cf29b743aae482308bfbd', 'okendo', 'jessicap1452_2139', 'Perfect size', 'I really enjoyed the Every Body Eat Sea Salt Pretzel Thins. They’re light, crunchy, and perfectly salted without being overpowering. I love that they’re gluten-free and allergy-friendly, yet still taste like a classic pretzel. They’re great on their own but also pair well with dips or hummus. The texture is crisp and satisfying, making them an easy snack.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-29', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly"]', 'texture,taste,versatility,convenience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('16e0bd57679655de5dcf32cd3de5d3f9', 'okendo', 'jessicap1452_2139', 'Healthy snacks', 'The Ginger Cinnamon Cookies were a pleasant surprise. They have a warm, cozy flavor with a nice balance of ginger spice and cinnamon sweetness. The cookies are crunchy but not too hard, and they feel indulgent without being overly sweet. I also appreciate that they’re made to be allergy-friendly, which can be hard to find in flavorful snacks. Great with coffee or tea!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-29', 0, 'No', '', '', '["crunch_texture","allergy_friendly","texture_issue"]', 'flavor,texture,sweetness,pairing', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e31a7fe84e32bcfcb6dadb975a9472c5', 'okendo', 'jameelaf_2798', 'Gluten free snacks', 'I am addicted to these. It''s sooo good. I wasn''t expecting it to taste this good. I thought I''d be eating a cardboard but it''s actually great. I love the flavor. I''m definitely getting more.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-29', 0, 'No', '', '', '["great_taste","gluten_free","addictive"]', 'taste,flavor,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
