INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e127c192c85d56a4e8fb2425088fbf1c', 'okendo', 'kallim11_355', 'Delicious and crunchy', 'These pretzel thins were really good! I love that they are a healthier option as well. They have a great crunch and taste when you bite into them. There was almost no salt on any of them, but that didn’t bother me or affect the taste too much for me. It was great with dip, and I could see myself buying them again.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-29', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunch,taste,dip', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
