INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f93e58fe97c097b3ec7b4a82f362c4ec', 'okendo', 'joyk24_5186', 'Love these', 'I absolutely love these pretzel thins. I’m not the biggest fan of pretzels in general because they’re too salty, but these aren’t too salted. The thinness of the pretzels gives them a nice crunch too. Highly recommend for snacking.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["crunch_texture","too_salty"]', 'saltiness,thinness,crunch,snacking', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fca2346a27419fc6b0befa4097cd8394', 'okendo', 'joyk24_5186', 'Pretty tasty cookies', 'I love cinnamon, so I was pretty excited to try these cookies. The flavor is great, but the texture can feel a bit grainy and dry. The cookies aren’t too sweet, but the texture is a bit odd.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","bland_flavor"]', 'flavor,sweetness,cinnamon', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
