INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('60a8fd6a7f849b2ecce421db7b4d10d7', 'okendo', 'beccio1_8657', 'Yummy!!', 'The cookies were delicious for being so healthy. Packaging was easy to use and easy to open. The cookies tasted like cinnamon and spice. Will definitely be looking for them again.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,packaging,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('46e47ee07762519836a1488d8b283a80', 'okendo', 'caitlinm1_3818', 'Fine flavor hard and dry', 'Good ingredients and decent flavor but they are so dry and hard that they are not really flakey like a pretzel they are like a very dry cracker. They are okay, would not buy probably. They didn’t come broken which is good they are very hard.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["broken_crumbs","bland_flavor"]', 'ingredients,flavor,packaging', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8be792b0247898866f4668c0c17676db', 'okendo', 'caitlinm1_3818', 'Interesting texture mild flavor', 'Bite size little cookies. The texture is strange they are crunchy and chewy somehow but the chewy isn’t like a soft chewy it’s more gummy but they are unique. They have a good flavor and a nice after taste of ginger but not overpowering. Good ingredients. Good package you will eat them buy the handful!', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["crunch_texture","packaging"]', 'flavor,ginger taste,ingredients,packaging', NULL, 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
