INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('374604ebb7db2b70f9778e1760bf314e', 'okendo', 'bk22_6537', 'Deliciously good', 'Ill probably buy a box of these. They smell delicious and well salted. Well flavored packaged for on the go and the texture was crisp and not chewy easy to digest and quick to reach for the next one after one after taste.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'smell,salt,flavor,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a1bd72424815f1c89a6b67b2449ba60a', 'okendo', 'bk22_6537', 'Deliciously good.', 'Ill probably buy a box of these. They smell delicious and are tasty. Well packaged for on the go and the texture was crisp and not chewy easy to digest and quick to reach for the next one.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'smell,taste,packaging,texture,digestibility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('304cdadc1e4b808864ca4a2d03e3e601', 'okendo', 'prettie_339', 'Thinny', 'Everybody Eats Pretzel Thins are light, crispy, and full of classic pretzel flavor. They have the perfect crunch without being overly salty, making them great on their own or paired with dips, cheese, or spreads. The thin shape makes them easy to snack on, and the 4 oz size is ideal for sharing or enjoying throughout the day. A tasty, versatile snack that hits the spot when you want something crunchy and satisfying', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","too_salty"]', 'texture,flavor,saltiness,versatility,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8fc59db735d003cedab308669601a060', 'okendo', 'prettie_339', 'Sweet', 'Everybody Eats Ginger Cinnamon Cookies are perfectly spiced and incredibly satisfying. The ginger and cinnamon flavors are warm and well-balanced, giving each bite a comforting, homemade taste. The cookies have a great texture—not too hard and not too soft—making them easy to enjoy anytime. They feel like a cozy treat with just the right amount of sweetness and spice. A delicious option for snack time, dessert, or pairing with coffee or tea', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","texture_issue"]', 'spicing,flavor,texture,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('453fae173097ba22d7b3efb4eebea5a7', 'okendo', 'brandin1497_3814', 'Would be really good with a dip.', 'I didn’t hate them, but personally thought they could have had a little more flavor. To eat by themselves, they weren’t great. But they’d be perfect to use with a dip of some sort. Super crispy, stayed fresh, perfect bite size.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["crunch_texture"]', 'crispiness,freshness,size', 'flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6f017e3371289229b806e0b106be7bb7', 'okendo', 'naurink_3871', 'Warm ginger-cinnamon flavor with a satisfying bite', 'I was pleasantly surprised by these Every Body Eat ginger cinnamon snacks. The flavor balance is really nice — you get a warm cinnamon sweetness with a gentle ginger kick that isn’t overpowering. The texture has a satisfying bite with a soft, slightly crumbly interior. They don’t taste overly processed, and the aftertaste is warm and comforting rather than artificial. I enjoyed them as a light snack with tea and found them easy to snack on without feeling heavy. Overall, a unique and enjoyable flavor combination.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["crunch_texture"]', 'flavor balance,texture,taste quality,snacking experience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0907739856806a2d9cf20a6d261f9739', 'okendo', 'irinas123_614', 'Fresh, flavorful, perfectly crunchy-then-chewy sna', 'These are absolutely delicious! The freshness is noticeable right away, and the aroma of ginger and cinnamon is warm and inviting as soon as you open the bag. The texture is exactly as described—perfectly crunchy at first and then pleasantly chewy, which makes them so satisfying to eat. The consistency is great, with each bite tasting the same and full of flavor. The packaging is sturdy, resealable, and keeps everything fresh. They’re very tasty, and even my daughter, who is extremely picky, loves them—which honestly means a lot to me. Such a great snack option!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'freshness,aroma,texture,flavor,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f2dbdfe7ce167b9e07a42bedc3ad72cb', 'okendo', 'jamiel121_5901', 'Delish!', 'Everybody eat pretzel thins are the perfect crunch. Just the right amount of salt. Great ingredients. And taste delicious. Also, they are completely allergen friendly.! only problem is I eat the entire bag in one sitting cause I just couldn’t stop', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', 'crunch,salt,ingredients,taste', NULL, 'addictive', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('583df847a37beeaa4018294331c479da', 'okendo', 'jamiel121_5901', 'Yum!', 'So I’m gonna start this by saying the only reason I gave it four stars instead of five is because I am not the biggest fan of ginger… With that said, they are more cinnamon forward so I definitely like them… The texture is perfection! Think of a pecan Sandi type of cookie, they kind of melt in your mouth. Just the right size to pop in your mouth. The only problem is you don’t stop. Love that these have great ingredients and are allergen friendly.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","good_replacement"]', 'cinnamon,texture,size,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b4a52f30ac95e4a3215150f275de872a', 'okendo', 'alittlepieceofcherr_4372', 'Weird', 'A bit disappointed in these since I was expecting pretzels but these were just weird crackers. They were so flat and dry and don’t really taste at all like a pretzel. The taste was ok, not pretzel like since there was barely any salt on them. Idk these just didn’t really hit the mark for me but they were ok.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["bland_flavor","not_pretzel"]', NULL, 'texture,salt,expectations', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('133f87cac2177a7d2270c8cc0bf64924', 'okendo', 'alittlepieceofcherr_4372', 'Healthy tasting', 'These are ok, the texture is chewy and crunchy at the same time which I love! The taste however is a bit dry and mildly cinnamon bun, but taste like a healthy cinnamon bun if you know what I mean! They’re fun to nibble on when you want a sweet treat thought!', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', 'texture', NULL, 'taste', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e63fb9872dd05b3f4c8e82ed16f45837', 'okendo', 'dawnk101_2656', 'Just okay', 'For me, these were just okay. A bit crumbly and dry overall. For the price I do think the value is good so I won’t rate it too poorly. They weren’t my favorite but they suffice if you have alot of dietary restrictions.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-28', 0, 'No', '', '', '["bland_flavor"]', 'value', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c8f4e1dde7dab80a33f1df20e96edc37', 'okendo', 'dawnk101_2656', 'Yummy Gluten/Grain Free Snack', 'These are great for my gluten-free friends. I actually prefer these to regular crackers. These are good tasting and have a nice crunch to them. They were gobbled up in no time on Christmas!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-28', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,texture,gluten-free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b2c29977a4e16daa40928eb4060101ef', 'okendo', 'laurag572_8018', 'Good', 'absolutely delicious. The combination of crunchy pretzels with ginger and cinnamon is perfectly balanced—warm, slightly sweet, and not overpowering. The texture is great, and they taste fresh and flavorful. They’re a unique snack, different from regular pretzels, and perfect if you like spiced flavors. I really enjoyed them and would definitely buy them again.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,flavor balance,spiced flavors,uniqueness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
