INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('88ef8e1356d1ee3510be54362b658d7e', 'okendo', 'helenl58_2325', 'Delicious', 'The cookies were surprisingly tasty and that coming from a person who is not gluten or dairy free! Tasty, crunchy, easy to eat! Sweet enough to feel,like you are having. A treat!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-27', 0, 'No', '', '', '["great_taste","crunch_texture","dairy_free_vegan"]', 'taste,texture,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
