INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a97bcbf357d8a19ed19e9369934a23ce', 'okendo', 'tanaz007_5739', 'Yummy', 'Cozy up to the comforting warmth of Every Body Eat® Ginger Cinnamon Cookie Bites! Each crunchy-then-chewy bite combines the gentle heat of ginger with a touch of sweet cinnamon spice—all from clean, gluten-free ingredients you can trust. Perfect for sharing… or not.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e55e58380decaf2febd03b71a244516d', 'okendo', 'leonorap15_1399', 'Top five best crackers on the market!', 'I use these as a dipper for a charcuterie board, and everyone raved about them! Couldn''t even tell that they''re actually good for you!! crisp, crunchy, and everything you need in a cracker', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["crunch_texture"]', 'texture,taste,charcuterie', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f2dade68b1d6393077bbc570f134dbd9', 'okendo', 'leonorap15_1399', 'Must try cookie you wouldn''t know it''s healthy whe', 'One of the greatest sweet treats I''ve ever tried gluten-free and very, very low sugar, no aftertaste, great quality, and a great cookie in itself!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-27', 0, 'No', '', '', '["gluten_free"]', 'taste,quality,sweetness,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
