INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('40ae9a745f5a544b3590d9800491f9f5', 'okendo', 'mait61_1402', 'Thin shaped pretzels that give you a light crunch!', 'Obsessed with these pretzel thins so much! I love anything thin shaped and these pretzels were exactly that, giving it a light crunch to it. For me, the sea salt flavor was for the win!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["crunch_texture"]', 'thin shape,crunch,sea salt', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0727602348c9541b230af41e5da5000b', 'okendo', 'dramaspoiler_5144', 'Versatile healthy snack', 'I like the solid taste it delivers.  It has a nice bite to it and I felt it was strong enough to handle any dip or food for an upgrade appetizer.  Easy to portion control with a resealable bag.  The easy to read ingredient was a plus', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["packaging"]', 'taste,texture,strength,packaging,ingredients', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c79e11e557aba41d451875545ae1b114', 'okendo', 'dramaspoiler_5144', 'Perfect snack', 'I like how they are bite size.  They seem very healthy as I can read the ingredients. It has the right spiceness and I found it filling.  They held well and were not too hard and not too soft.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-27', 0, 'No', '', '', '["texture_issue"]', 'bite size,spiciness,filling,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8ea10fc1a3f68ac9ee096186787b2040', 'okendo', 'anastasiias95_5739', 'Light and satisfying snack 🥨', 'The smell and aroma are fresh and lightly toasted, very inviting. The pretzel thins have a nice balance between brittleness and chewiness, with a crisp bite that isn’t too hard. They break cleanly without crumbling too much. The portion size feels just right for a snack or sharing, a simple, enjoyable, and well-made pretzel snack.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["crunch_texture","texture_issue"]', 'aroma,texture,portion size,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
