INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8832870c3735ddd37e4a719ea42ca87e', 'okendo', 'pinky21_3882', 'Warm Cinnamon Flavor, but a Little Too Sweet', 'The Everybody Eat Ginger Cinnamon Cookie Bites have a great soft, chewy texture and a warm cinnamon flavor that reminds you of a fresh-baked treat. However, they were a bit too sweet for my liking. They’re still a nice option if you enjoy sweeter snacks made with clean, allergy-friendly ingredients.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-27', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'texture,cinnamon flavor,ingredients', 'sweetness', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3eafd68ab41bde41b4f7fcb1b03dd84e', 'okendo', 'pinky21_3882', 'Crunchy and Clean, But Needs a Little More Salt', 'I tried the Everybody Eat Sea Salt Pretzel Thins, and I really liked the crunch and the clean, allergy-friendly ingredients. They’re light, crispy, and easy to snack on. My only critique is that they could use a bit more salt to boost the flavor. If you enjoy a mild, simple pretzel taste, these might be perfect for you.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'crunch,texture', 'salt level', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9c3559651435977f7afe8ca50617e47c', 'okendo', 'antoinetteb30_7676', 'Crunch factor', 'The packaging was good and intact. The appearance was as expected. Sweetness was there too. Ingredients are as listed on the package. The mouthfeel is crunchy and fresh.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["crunch_texture","packaging"]', 'packaging,appearance,sweetness,mouthfeel', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('35f13ec30c46d2bc7c90692d63cb17e8', 'okendo', 'candyt16_1391', 'Good snacks when you hungry', 'Everybody Eats Ginger Cinnamon offers a warm, comforting flavor that stands out without being overpowering. The ginger brings a gentle spice that feels cozy and energizing, while the cinnamon adds a smooth sweetness that balances everything nicely. Together, the flavors feel natural and well-blended, not artificial or too strong. What makes it especially enjoyable is how versatile it feels. The taste is bold enough for people who enjoy spice, texture is soft but mild enough that it won’t be overwhelming. It leaves a pleasant, lingering warmth that makes you want another bite. Overall, it’s a satisfying choice for anyone who enjoys classic, comforting flavors with a bit of a kick. It’s simple, flavorful, and easy to enjoy. It has all these ingredients: sat flour cassava flour, Totato starch lam fruit oil maple sugar cane sugar crystallized ginger ax seed, cinnamon, ranilla, salt, juice, and serot fiber.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-27', 0, 'No', '', '', '["crunch_texture","stale"]', 'flavor,ginger,cinnamon,texture,spice', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('952e728abf294f5f6ebb247c46ee5c44', 'okendo', 'antoinetteb30_7676', 'Interesting bite', 'The smell is just basic and nothing fancy. The appearance was very nice, as advertised.  The aroma I really didn''t like very much. The bite and mouthfeel were fine.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-27', 0, 'No', '', '', '[]', 'appearance,mouthfeel', 'aroma', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3747f1dda01ee2ec216d854b8ca0989a', 'okendo', 'queenl22_5777', 'Every Body Eat® Pretzel Thins are a safe, great-va', 'I really enjoyed the Every Body Eat® Pretzel Thins—they feel safe and thoughtfully made, which gives me confidence when sharing them with my family. The value is great for a 4oz bag, and there’s no assembly needed, making them super convenient. The packaging was clean and well-sealed, and the pretzels themselves looked fresh and appetizing. Overall, a simple, tasty snack that delivers on quality and appearance.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-27', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,value,convenience,packaging,freshness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
