INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5e22b3c4acb5a0665807937f7f077b2f', 'okendo', 'brendab214_6371', 'Delicious', 'Everybody Eat Ginger Cinnamon Cookie Bites are delicious! The ginger and cinnamon flavors are warm and comforting without being overpowering. Even though the packaging style feels a bit old-fashioned, the cookies inside taste fresh and homemade. They’re perfect with tea or coffee and make a great snack. I would definitely buy them again.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-26', 0, 'No', '', '', '["great_taste","packaging","stale"]', 'flavor,freshness,taste', 'packaging', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9940326bc40d688bfae001a9b0f81de8', 'okendo', 'brendab214_6371', 'Good', 'These Sea Salt Pretzel Snack Thins are delicious! They are perfectly crispy with just the right amount of salt. I love that they’re light but still satisfying. Great on their own or with hummus and cheese. I will definitely buy them again.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-26', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,texture,saltiness,lightness,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8f4af74934fe7494925c87cb791c81f0', 'okendo', 'hanguyen59_2602', 'Very crispy', 'These pretzel thins deliver a satisfyingly crisp, salty crunch with clean, allergen-friendly ingredients that make them great for snacking on their own or with dips.I love that they’re gluten-free, grain-free, and free from the top 14 allergens. .', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-26', 0, 'No', '', '', '["crunch_texture","gluten_free","allergy_friendly"]', 'texture,ingredients,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('aef96ee0e26a0866b6e4bc2c1505f148', 'okendo', 'hanguyen59_2602', 'Tasty', 'These ginger cinnamon cookie bites deliver a warm, cozy spice with a nice balance of ginger heat and sweet cinnamon, and I love the crunchy-then-chewy texture made from clean, allergen-friendly ingredients. They’re gluten-free, vegan, and free from the top 14 allergens, making them a great snack for me with dietary restrictions.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-26', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly"]', 'spice balance,texture,ingredients,dietary restrictions', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('238929a97b29a829dfe9c0386b5105fa', 'okendo', 'elizabethannarrowoo_4280', 'All flavor no bad stuff', 'Wonderful texture, great packaging, very fresh, easy to store a little bit of sweetness, just perfect for any salty cravings that you may have off all flavor no junk love it.So much will be buying more of these products', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["crunch_texture","packaging"]', 'texture,packaging,freshness,sweetness,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('27c4af71e9a23ffdebb5031ea5b7c50a', 'okendo', 'elizabethannarrowoo_4280', 'No junk just great flavor', 'Wonderful appearance, a little spice with gingerbread, very sweet and very satisfied with these these take care of my sweet tooth have a lot of good nutrients in them, I love them so much and they''re pretty healthy too with having carrot stuff in it.  I will be buying more of these products', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '[]', 'appearance,spice,sweetness,taste,carrot', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('14a5cd692ef2613adf5ef4e9a48e9d07', 'okendo', 'ginawu512_7368', 'Ok product', 'It’s ok. Because it’s gluten free it doesn’t come together in your mouth. It’s crumbly… and not in a way you want for pretzel? Overall it’s ok I just wouldn’t buy it.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["gluten_free"]', NULL, 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f61f53b7c4e459af53c597cb488c02e2', 'okendo', 'yurik97b7_2473', 'Gluten and Allergan free!', 'Unlike the thins from this brand which really enjoyed, I don’t think I’m a huge fan of this particular flavor of cookies because of the ginger. I’m not a ginger fan. the taste of ginger is very faint though. I think if I had a different flavor I would have enjoyed them more. The texture is nice and soft/slightly chewy. I still enjoy the fact that it is free of many allergans and is vegan!', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","allergy_friendly"]', 'texture,vegan', 'ginger flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('39b08c19666e97bceda7dafc454d02d7', 'okendo', 'ammaa5_5298', 'Golden, crunchy pretzels with a clean and classic', 'The pretzels look fresh, golden, and evenly baked with a clean, classic pretzel shape. They have a nice crunch appearance and look well-seasoned without being messy. Very appetizing and visually appealing straight from the bag.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["crunch_texture"]', 'appearance,texture,seasoning,shape,freshness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d3bd7ecf9f90b3c6b7e2f20181eb8929', 'okendo', 'ammaa5_5298', 'Crunchy, satisfying, and perfect for a quick snack', 'A flavorful, crunchy snack with the perfect blend of ginger warmth and cinnamon sweetness.easy  package to open😍 Visually appealing with a fresh, well-seasoned look.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["crunch_texture","packaging"]', 'flavor,texture,ginger,packaging,appearance', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('93d6962e6f71a1e6298cc0e5366cd2cd', 'okendo', 'sandrale1401_6889', 'Light, crispy pretzel thins with great crunch, fre', 'These Every Body Eat Pretzel Thins were a great surprise. They are thin, light, and very crunchy, which makes them extremely enjoyable to snack on. The flavor is simple but well done, with just the right amount of salt. They taste fresh straight out of the bag and hold up well when paired with dips like hummus or cheese. I like that they don’t feel greasy or heavy, and they’re easy to eat without feeling overly filling. The texture stays crisp, and the pretzels don’t crumble easily, which is a big plus. The packaging kept them fresh, and the portion size is convenient for sharing or enjoying over several days. Overall, these pretzel thins are a solid, high-quality snack option that I would absolutely buy again.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["crunch_texture","repeat_purchase","packaging","stale"]', 'texture,flavor,freshness,pairing,portion', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7f1f19eecbc2aca69d9bb3898fe7a558', 'okendo', 'sandrale1401_6889', 'Warm, flavorful ginger cinnamon snack made with qu', 'I really enjoyed the Every Body Eat Ginger Cinnamon snack. The flavor is warm and comforting, with a nice balance between ginger and cinnamon that isn’t overpowering. The texture is satisfying, and it feels like a high-quality, thoughtfully made product. I also appreciate the clean ingredients, which make it a great option for a mindful snack. Overall, it’s a tasty and unique treat I would definitely buy again.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["great_taste","crunch_texture","repeat_purchase","clean_ingredients"]', 'flavor,texture,quality,ingredients,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ecd1c2304d736b91dc7f8cc93792d6c1', 'okendo', 'xiaol7_3514', 'Great snacks', 'Very tasty very crunch the flavor is really good , satisfying my stomach. The ingredients are gluten free which is bonus. The package is simple and good highly recommended', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","packaging"]', 'taste,texture,flavor,gluten free,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('51128d55a151f10d71bfaf578c3d6dd4', 'okendo', 'xiaol7_3514', 'Great treat', 'Very tasty cookie, very soft and chewy . The cinnamon and ginger mot too powerful. It’s a great little snack highly recommended it I would buy it again', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["great_taste"]', 'taste,texture,cinnamon,ginger,snack', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9a753965ef4c427d8bee56b1e733840a', 'okendo', 'wincit_522', 'Ok', 'Vegan cookies were ok. Kinda dry and chalky and crumbly. They taste and have the texture of nut cookies so a little dry. Would go well with a cup of tea. Not bad vegan option.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["crunch_texture","dairy_free_vegan","bland_flavor"]', NULL, 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7a440398520c409708bb7f59d72b48e8', 'okendo', 'candyt16_1391', 'Love this crunchy snack', 'Everybody Eats Sea Salt Pretzels are a solid go-to snack when you want something simple but satisfying. I love that the pretzels have a nice crunch without being too hard, and the sea salt is evenly distributed, giving good flavor without being overwhelming but it would be better if it a little less salt. They taste fresh and clean, not overly processed, good size not too thick which makes them easy to snack on straight from the bag. What really stands out is how balanced they are, salty enough to be tasty, but not so salty that you need a drink after every bite. They’re great on their own, but they also work well with dips like hummus or peanut butter. Overall, Everybody Eats Sea Salt Pretzels are a reliable, tasty snack that feels classic and well-made. It has these ingredients: tapioca starch palm fruit oil chickpea flourPotato starch chicory root fiber sea salt rosemary extract. I recommend this brand and will buy it again.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["great_taste","crunch_texture","texture_issue"]', 'crunch,freshness,size,flavor balance', NULL, 'salt level', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4f5cea76048b46041437c717a4683b56', 'okendo', 'marcelam77_6053', 'Addicting', 'These cookies are actually really good, they’re very small, but packed with lots of flavor. Contrary to what the package says, these cookies have zero crunch to them, they are more on the soft chewy side, than crunch. However, they still are very good cookies.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["crunch_texture","packaging"]', 'flavor,taste', 'size', 'texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1e08f8c4a1621541761cefafcbc4c1e1', 'okendo', 'nhubaby_7049', 'Cookie Snack', 'My kids also enjoy these Every Body Eat Ginger Cinnamon Cookie Bites. They’re soft, lightly crunchy, and have a warm ginger and cinnamon flavor that feels perfect for the holiday season. During Christmas break, these are easy for snacking at home while playing games or watching videos. I like that they’re gluten-free and vegan, so I feel good offering them as a family-friendly treat. Sweet but not too much, and very comforting.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan"]', 'texture,flavor,sweetness,gluten-free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b07308edce5c7af30dfa05c7f527205e', 'okendo', 'nhubaby_7049', 'Light & Crunchy Snack', 'My kids really enjoy these Every Body Eat Sea Salt Pretzel Thins. They’re thin, crunchy, and lightly salted, making them easy to snack on. During the Christmas holiday break, these have been a great option for staying at home—my kids like to nibble on them while playing games or relaxing. I also like that they’re baked, not fried, so they don’t feel heavy or greasy. Being gluten-free and vegan is a nice bonus, especially for a family-friendly snack everyone can enjoy.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan"]', 'texture,saltiness,baked,gluten-free,vegan', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('401a32ea02ccb68d08bfa3602067211e', 'okendo', 'schereen_8546', 'Clean ingredients and taste good and fresh', 'They’re very thin, super crispy, and lightly salted, which makes them easy to snack on without feeling heavy. The texture is great and the flavor is simple but satisfying. A nice, crunchy snack that tastes good on its own or paired with dips.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["crunch_texture","clean_ingredients"]', 'texture,flavor,thickness,saltiness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('60a722580f9bd0b42b19e92ab103c639', 'okendo', 'schereen_8546', 'Tastes really good', 'I’m usually not a sweet-tooth person, but I genuinely love these Everybody Eat Ginger Cinnamon Cookie Bites. They taste great without being overly sweet, and the ginger cinnamon flavor is warm and comforting. The texture is light and almost feels homemade, which I really appreciate. On top of that, they’re gluten free, vegan, and allergy friendly, so I feel good about what I’m eating. These are perfect with coffee or tea and definitely a treat I’d buy again.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-25', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","repeat_purchase"]', 'taste,flavor,texture,sweetness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0694cfc00afeabf2878fbfad7367b257', 'okendo', 'jessicab1565_6298', 'Yummy', 'There is so much to say about these they were mind blowing I wasn''t expecting them to taste so great being gluten free, but you can''t even tell. The smell was Devine and they were so crappy and the bag is a great size.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-25', 0, 'No', '', '', '["great_taste","gluten_free"]', 'taste,gluten free,smell,bag size', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
