INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('05636e601bf7bfa4abd70a8be5d3ecf1', 'okendo', 'carolynxcullen_9513', 'Perfect thin crisps to snack on!', 'These salted pretzel crisps are so delicious when dipping with some hummus or peanut butter! My bf is a health nut and he approved of these gluten and grain free crisp thins! Easy go-to snack you won’t feeling guilty about!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'taste,dipping,texture,convenience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bfe7c2b77da38cec33d4f8b452b2c1e8', 'okendo', 'carolynxcullen_9513', 'Delicious little bites!', 'Love these healthy little snack bites! The ginger cinnamon bites taste just like little gingerbread crisp cookies. Perfect to satiate a mini sweet craving but knowing it is healthy with all natural ingredients, gluten free, and seed oil free!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free"]', 'taste,texture,ingredients,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('743a542cdd088f20c95f383866f86ba2', 'okendo', 'vesnaa2_9309', 'Must have on the go', 'Perfect snack when you are craving something salty unhealthy. Texture is smooth and feels like a mouthful from one piece. Packaging is conveniently easy to open and close for longer freshness smells divine.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["crunch_texture","packaging"]', 'texture,packaging,smell,saltiness', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9e099e66119c47ca735e11ee8f80261f', 'okendo', 'vesnaa2_9309', 'Perfect snack on the go!', 'What a yummy treat. It’s perfect size for on the go. You got a lot in the package and quantity is simply unbelievable mouthful and melts in your mouth. Chewines is smooth.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["great_taste","packaging","false_advertising"]', 'taste,size,quantity,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6e806bbad29280c3e8f18e1f138e4deb', 'okendo', 'sherylr20_5525', 'Pretzel but better than a normal pretzel.', 'These don’t have any aftertast I love that these are pretzels but not taste wise. I would eat these due to how love the crunch like a chip but is a pretzel. The freshness of the resealable bag is a game changers on freshness and keep your snacks from being stale.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["crunch_texture","packaging","stale"]', 'aftertaste,crunch,freshness,packaging', 'taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
