INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f6e588d9de5661ff6ac1058a1895b1cb', 'okendo', 'sherylr20_5525', 'Yummy morsels', 'These are really good I love the taste of cinnoman with the lack of the ginger taste. These little bite size morsels are berry good and fresh with every bite. These little easy to snack storage ads a great uniqueness to the packaging.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["great_taste","packaging"]', 'taste,freshness,size,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b35efbed23eb82c8468f0f3cd8bfaef0', 'okendo', 'xyzlychee_4159', 'Messy but a solid healthy choice', 'It’s great that this product is gluten-free vegan and allergy friendly. However, the texture was not like a cookie, more like a brownie. The taste was definitely healthy, and I also did not like the texture as it crumbled and felt messy to eat. However, the portion size is good. A serving size is five cookies and only 140 cal.', 3, 'neutral', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["crunch_texture","gluten_free","dairy_free_vegan","allergy_friendly","broken_crumbs"]', 'portion size,calories', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('1b87eee4e14b1a0f10af53b88009ddb2', 'okendo', 'angiem466_9945', 'Perfect crunch for pretzel snacks!', 'These sea salt thin pretzels are delicious! They have the perfect crunch and light sprinkled with sea salt. They break easily to chew it and don’t hurt your teeth like some other brands do. Flavor and texture are my favorite. The bag is easy to use with a closure to save some for later. I really enjoyed this brand and I would give it more starts if I could! Will be rebuying! I tried the ginger cinnamons bites as well and I want to try all of the flavors!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunch,texture,flavor,packaging,salt', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('36fad145d8ca0c5217176e8638e74335', 'okendo', 'angiem466_9945', 'Perfect snack for your purse, office, gym, or just', 'These were simply perfect in every way. It’s a crunchy yet softness in the texture. The blend of cinnamon and ginger make it delicious as a snack and the problem is only that I finished the entire bag right away and now I need to buy more. It’s not only delicious but I also love the clean ingredients. The packaging is easy to open and love that it has a closure if you want to save some for later. A perfect treat! Will be rebuying from this brand.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","packaging"]', 'texture,flavor,ingredients,packaging,taste', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d489d349c7ae323ee7ceb6b84942c15a', 'okendo', 'jackief2_573', 'Good alternative', 'I love pretzels and these pretzel thins were okay. They are thin and have minimal salt so there isn’t much flavor with each bite. It is healthier so if you’re on a strict diet these might be a good option for you.', 4, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["good_replacement"]', NULL, 'salt,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('89f59ed9c481bbff4cb0e4dfc853928a', 'okendo', 'jackief2_573', 'Delicious!', 'Cinnamon cookie bites are so good! For being extremely healthy with limited ingredients I was surprised on how flavorful the cookies were! I am confident sharing with my friends and family without worrying about allergies which is great. Perfect bit size also.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["great_taste","allergy_friendly"]', 'flavor,ingredients,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8c718c70e058855c484d041b3b7b8a1c', 'okendo', 'karisss_3536', 'Did not enjoy this', 'I really tried to enjoy this pretzels snacks as it is very crunchy which I typically like in a snacks but the flavors weren’t nice to taste. Also it has a weird aftertaste which I didn’t like but the aroma was nice and it seems really fresh. I also like the sizes and the look but I just didn’t enjoy the taste.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["crunch_texture"]', 'crunchiness,aroma,freshness', 'flavor,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('d21901532dfadd71b81c974e4ffa11ed', 'okendo', 'hai2_9843', 'Taste good', 'The package looks appealing. The taste is ok if you like ginger and cinnamon. Very strong and flavorful. Highly recommend for those who like ginger and cinnamon snack.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["packaging"]', 'packaging,ginger,cinnamon,flavor', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
