INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2a0908cc845a741aa16037ed6cdfdb1f', 'okendo', 'lisav1124_9295', 'They look good but taste awful', 'I was so excited to try these, when you open the bag they smell just like pretzels but that’s where it ends. It tastes like burnt cardboard, crunches like wood, and the after taste is awful. Just yuk.', 2, 'negative', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["crunch_texture"]', 'smell', 'taste,texture,aftertaste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5dbfb3b02cb8edd56617a326d699e2db', 'okendo', 'holliec53_3346', 'Flavorless', 'The everbody eat sea salt pretzels are pretty tasteless. They do not remind me of pretzels but more like a cracker. They dont have good flavor. The ingredients are good for those with dietary restrictions, which is nice to have options.', 2, 'negative', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["bland_flavor"]', 'ingredients', 'taste,texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ec29c191ecc4677e5ab9230d39dd24c5', 'okendo', 'holliec53_3346', 'Dry', 'The every body eat ginger cinnamon bites are very dry. They sorta have a cardboard taste. I appreciate the clean ingredients and they are absolutely great for someone who has food restrictions. The ingredients are clean. The texture and flavor just arent there for me.', 2, 'negative', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["crunch_texture","clean_ingredients","bland_flavor"]', 'ingredients,restrictions', 'texture,flavor', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
