INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9fbea9d75862a1169b23db758c83f9bf', 'okendo', 'melisb33_3721', 'Allergy-friendly pretzel crackers!', 'These pretzel crackers have the benefit of being allergen friendly, free from 14 allergens! The packaging showed a cracker with plenty of salt on top, but when I tried these, there wasn''t alot of salt on top. There crackers could definitely use more salt. That said, they do taste pretzel-like, and would probably be awesome with a good, flavorful dip.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["allergy_friendly","packaging"]', 'taste', 'salt,packaging', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7882c5dcee3c7bf66513834dde1935b0', 'okendo', 'melisb33_3721', 'Delicious cookie bites!', 'These were delicious little gingery cookie bites!!! I love that they are made with wholesome ingredients and allergen-free too. The cookies are crunchy at first, then they get somewhat chewy, which is the first time I''ve had a cookie like that...unique and fun to experience. The ginger taste is perfect, neither too spicy or too mild.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-24', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly","too_spicy"]', 'taste,texture,ingredients,ginger', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
