INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6a6da7edad23a6f3009db610f1877ccc', 'okendo', 'yurik97b7_2473', 'Nice crunch, great for dips.', 'I’ve been on a health journey and I’ve been trying to cut out seed oils and glutens. I’m not gluten intolerant but trying to see if my body will be better without it. Sometimes I find it difficult to find snacks that fit certain allergies or accommodate different diets but this cracker covers it all.  I really enjoy the crisp texture of these crackers. It goes so well with many dips, tuna, hummus or even snacking on its own. The crisps holds it shape well. I’m eager to try the other flavor in the thins and will be keeping these on hand!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-24', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', 'texture,versatility,dietary needs', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
