INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('eb4099f1781c0c77efb9a8cb0d4380f3', 'okendo', 'hanna_nick_8957', 'Perfectly Thin Pretzels with Great Flavor', 'These pretzel thins are super crunchy and have just the right amount of sea salt. They taste light but still satisfying, and you’d never guess they’re gluten and grain free. Perfect for snacking on their own or with dips.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["crunch_texture"]', 'crunchiness,salt level,taste,gluten free,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('25d463c8097decc031bb9b826ef024dd', 'okendo', 'hanna_nick_8957', 'Gluten free.', 'These ginger cinnamon cookie bites are seriously delicious. They have a perfect balance of warm spice and sweetness, and the texture really is crunchy at first and chewy inside. It’s hard to believe they’re gluten free because they taste just like a homemade cookie.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","false_advertising"]', 'taste,spice balance,texture,gluten free', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bf5345cbd73450e53003571412c7d92b', 'okendo', 'mariac1233_141', 'Great taste & crispy.', 'The Everybody Eat pretzel thins have a clean flavor with a light & crisp mouthfeel, balanced saltiness, a clean aftertaste, and come in a simple, sturdy package. I love to enjoy them with hummus.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'flavor,texture,saltiness,aftertaste,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
