INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5d49d8752f1bbd26421ec972b1ffe21e', 'okendo', 'lizmckeough_2675', 'Surprised its this good', 'I like it way more than I expected to I was a little skeptical honestly because I thought it would be crumbly and gross but the texture was actually nice', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["crunch_texture"]', 'texture,expectations', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a57ade4637452c07fb3c92e5f679d926', 'okendo', 'yahairar30_7684', 'Pretzel', 'I love eating something salty after every meal, but it''s hard to find something tasty and nutritious. Every Body Eats pretzels are the perfect healthy snack; they''re made with wholesome ingredients, making them the ideal choice. The packaging is perfect for taking to work. I love their flavor and thin texture.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'flavor,texture,ingredients,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('92bb32b407aac638a1128f56d5b5d527', 'okendo', 'yahairar30_7684', 'Great cookies', 'I love eating something sweet after every meal, but it''s hard to find something delicious and nutritious. Every Body Eats cookies are the perfect healthy snack option. They''re made with wholesome ingredients, making them the perfect choice. The packaging is perfect for taking to work, and the flavor and texture are unique.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture","packaging"]', 'taste,ingredients,packaging,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
