INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4268f2a7a3984fba59892f46042b1704', 'okendo', 'vl22_6209', 'Online', 'Once you order and pay, it arrives at the promised time. Tasty, very nice. Has small bent bamboo tongs to pull out a bag or two and keep your hands clean. The resin on the bamboo skin is sticky and you end up having to wash your hands anyway but - nice thought.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["great_taste"]', 'taste,tongs', 'bamboo', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
