INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('69b752b33554df024d5e0bfbbd054a76', 'okendo', 'jessicaann1990_8057', 'Nice pretzels', 'These are actually good. Our two year-old literally eats them with the 14 year-old and they like them a lot. It has a thickness and just the amount of salt. It needs to taste good.', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["stale"]', 'taste,thickness,salt', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7fc4384446805cb0dca6f3ba11b6603b', 'okendo', 'jessicaann1990_8057', 'Not for everyone', 'These are nasty. Even the two year old will not even eat them. The flavor is not there but just a bit of cinnamon. The texture is like unbaked cookies.', 2, 'negative', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["crunch_texture","stale"]', NULL, 'flavor,texture,taste', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3e761d227c3b049113e3bdc0f1e046ed', 'okendo', 'olivebelle_2606', 'Everybody Eat sea salt pretzels thins are crunchy', 'These gluten free sea salt pretzel thins are so crunchy & delicious. A nice amount of sea salt, never fried all baked. It uses ingredients that you can easily understand, everything is wholesome and healthy. The perfect little bite to scoop up your favorite dip. Its so refreshing to see healthy snacks that are made without 14 allergens. I would definitely buy this again and try other flavors. I would buy this again when I see it on shelves.  I would recommend this.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture","gluten_free","allergy_friendly"]', 'crunchy,sea salt,baked,ingredients,dip', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2da2fe851ef371d073f4bdb246f31e89', 'okendo', 'olivebelle_2606', 'Everybody Eat ginger cinnamon cookie bites are del', 'These gluten free cinnamon ginger cookies are delicious. A nice soft chew with little bits of sweet crystallized ginger. It uses ingredients that you can easily understand, everything is wholesome and healthy. The perfect little bite. Its so refreshing to see healthy snacks that are made without 14 allergens. I would definitely buy this again and try other flavors. I would buy this again when I see it on shelves.  I would recommend this.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["great_taste","gluten_free","allergy_friendly"]', 'taste,texture,ginger,ingredients,allergens', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f1864bd2c79f1a919ea24b6cc06e0267', 'okendo', 'ginawu512_7368', 'Good for gluten free buyers', 'Could be great, it was just crumbly and didn’t really meld together. It’s expected as it’s gluten free. Flavor is good and packaging looks expensive. I don’t know if I would go out of my way to buy these.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["gluten_free","packaging"]', 'flavor,packaging', 'texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6548bcab94cefe84dc59b894a8ecfada', 'okendo', 'tatumm1_6139', 'Great for dipping!', 'So satisfying! These crunchy pretzel thins are perfect for dipping. Crunchy consistency like a chip without all of the guilt. Serving size allows for proper snacking!', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["crunch_texture"]', 'crunchy,dipping,serving size,consistency', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e4a3a1392b5d33759a9fe51ca7ebea64', 'okendo', 'tatumm1_6139', 'YUM!!!', 'SANTA left these in my stocking & boy what a treat! These taste exactly like snickerdoodle cookies, but with better ingredients. They are not dry at all, and the resealable package helps to keep the moisture locked in.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["great_taste","bland_flavor","packaging"]', 'taste,ingredients,texture,packaging', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5780e6e541bf19c8986a4f97112e657f', 'okendo', 'thiziriselena_7182', 'Light, crisp pretzel thins with a balanced flavor', 'These pretzel thins from Every Body Eat are light, crisp, and very fresh. The flavor is well balanced with a mild saltiness and just a touch of sweetness, making them easy to snack on without feeling heavy. I like their thin, even appearance and crunchy texture. They feel easy to digest compared to heavier snacks, and they pair well with dips or can be enjoyed on their own. Overall, a clean-tasting and satisfying snack option.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8243b84695aaef9043b4110535a14b2b', 'okendo', 'thiziriselena_7182', 'Crispy, flavorful ginger cinnamon snacks with a wa', 'My family and I really enjoyed these ginger cinnamon snacks from Every Body Eat. They are very crisp and fresh, with a warm aroma as soon as you open the bag. The ginger and cinnamon are well balanced—not too spicy, but flavorful and comforting. The texture is light and crunchy, and the aftertaste is clean with a subtle sweetness. They feel like a good-quality snack and a nice option with tea or coffee. Overall, great value for the taste and ingredients.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["crunch_texture","value_price","too_spicy"]', 'texture,flavor,aroma,aftertaste,value', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9112980ebe2602f03e3bc4de0959714e', 'okendo', 'sydneyy10_5403', 'Love them!', 'This being free of the top 14 allergens is amazing and so nice to see for our son who is allergic to peanuts. No guessing needed on reading labels! The taste is also great. I like how thin the pretzels are and the sea salt is ever so slight it makes these a perfect snack.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["allergy_friendly"]', 'taste,thickness,sea salt', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f6b50bf8bc13c77fdfcba8dd6a19ed08', 'okendo', 'sydneyy10_5403', 'Amazing!!', 'First off, as an allergen family (son is allergic to peanuts) having an option that is clear cut free of the top 14 allergens is super impressive and amazing for my kid! And yes, he loves them! The taste is a chewy ginger cookie that doesnt hit too hard on the calories. I love these!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["allergy_friendly","texture_issue"]', 'taste,texture,calories', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
