INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c44e3388659faeae0f25d5f6b95e51fb', 'okendo', 'victorias818_5321', 'Soft, cozy, perfectly spiced cookie bites with a p', 'I genuinely loved these cookie bites more than I expected. The texture is the first thing that stood out to me — they’re soft and slightly chewy on the inside, with just the right amount of stickiness that makes them feel fresh and comforting, but not messy at all. They don’t crumble, don’t fall apart, and feel pleasantly stainless on the hands, which makes them perfect for snacking on the go.
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('6391541acf8afef79842a4c26213db2c', 'okendo', 'kareens7ae1_4284', 'Delicious 💕', 'This Cinnamon ginger cookies are a delightful treat that perfectly combines the warm, spicy flavors of cinnamon and ginger. Their texture is invitingly soft and chewy, making each bite enjoyable. The balance of sweetness and spice creates a comforting taste, perfect for any occasion. Overall, these cookies offer a cozy and aromatic experience that appeals to those who love spiced baked goods.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'flavor,texture,taste,aroma', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f0c96adc73271783ad7c4253daca381a', 'okendo', 'kareens7ae1_4284', 'Delicious💕', 'The  Every Body Eat Sea salt pretzel thins offer a deliciously crunchy snack that combines the classic pretzel flavor with just the right amount of salt. Their thin texture makes them light and perfect for dipping or enjoying on their own. The flavor is well-balanced, making them a satisfying choice for a quick snack or as an addition to cheese boards and parties. Overall, they are a tasty and versatile option for pretzel lovers.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["great_taste","crunch_texture"]', 'crunch,texture,flavor,saltiness,versatility', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8cb48b7cf669e58c632ded169d10ad52', 'okendo', 'nessaa37ad_3116', 'Descent', 'It’s not heavy a descent snack. Doesn’t look like traditional pretzel. Smooth texture after chewing. Descent portion size. It’s not too salty. It’s a nice snack if your into pretzels', 3, 'neutral', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["crunch_texture","too_salty"]', 'weight,texture,portion size,saltiness', 'appearance', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('a5c94c5680728c1b5c7584c8b7ff43d2', 'okendo', 'nessaa37ad_3116', 'It’s fair', 'It looked like under baked cookie. The taste is odd. It didn’t have a crunch it’s more of a soft texture. The cookies are small in size. It’s not sticky. I like that you can actually take the ginger in the cookie. I’m not a fan though it’s fair.', 2, 'negative', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["crunch_texture"]', 'ginger', 'appearance,taste,texture,size', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8275a7fe158eade8c45a51b6635c985c', 'okendo', 'salahm1_8587', 'Smaller bags may preclude binging', 'absolutely love these! As someone with a newish dairy and wheat allergy, these are my go-to substitutes for Cheez-Itz! They are thin and crispy, taste cheesy, and salty. If I was a snack judge, this product would take the Blue Ribbon. Their cost per ounce is a bit stiff, which is my only ding. But as a snack product, I give them my highest rating, and I buy the 6-pack version often. Light, crisp and flavorful.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-23', 0, 'No', '', '', '["crunch_texture","allergy_friendly","good_replacement"]', 'texture,taste', 'price', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cadefed867ac915005c7954626da8e2b', 'okendo', 'salahm1_8587', 'Love these!! Healthy and tasty!', 'These taste great tasting, are healthy and really hit the spot! I have these almost daily as a replacement for unhealthy chips! If you''re looking for a good light snack that''s healthy and very flavorful, these are definitely going to become your favorite, haha!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-23', 0, 'No', '', '', '["great_taste","good_replacement"]', 'taste,snack,replacement', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
