INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('fb02cd4fb821301b52cea6cb4cbd9b9b', 'okendo', 'tabithaa96dd_5664', 'Cinnamon goodness', 'I received this in exchange for a review. The package was sealed tight but easy to open. When you open you can smell the cinnamon and see the cinnamon swirls on the cookies. The taste was good a bit of an aftertaste and the consistency is a little dry but not terrible. I didn’t notice any chewiness but it was a typical cookie crunch, this is a good alternative snack with good ingredients.', 4, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-21', 0, 'No', '', '', '["crunch_texture","good_replacement","bland_flavor","packaging"]', 'cinnamon,ingredients', NULL, 'taste,texture', '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
