INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('e4d574c8869fb75bf1a495cfc14686b5', 'okendo', 'samantham1758_5832', 'Every body eat ginger cookies', 'These were absolutely not it. They taste like just the batter. The dry batter. I couldn’t get through it and spit it out. I really looked forward to it because I actually like ginger snap cookies. There was no stick in it whatsoever because it was dry. The packaging itself is okay as it has a resealable bag.', 1, 'negative', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-20', 0, 'No', '', '', '["bland_flavor","packaging"]', 'packaging', 'taste,texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('f831cc7ad59546fda3b4fd54081f7cd3', 'okendo', 'amym508_7288', 'Salty snack', 'The perfect size to pop into your mouth as a crisp and fresh bold taste. There’s no after flavor left in your mouth. You have the perfect amount of salt and crunch.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-20', 0, 'No', '', '', '["crunch_texture","stale"]', 'size,taste,aftertaste,salt,crunch', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3facb477aa9f67dd00fa4915e75d41cd', 'okendo', 'amym508_7288', 'Perfect bite size portion', 'The perfect bite-size amount for a snack it’s got a hint of ginger with cinnamon and sugar. The aroma is like Christmas not sticky, not crunchy. It has the perfect hint of vanilla. It has a soft texture with a little bit of crunch.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-20', 0, 'No', '', '', '["crunch_texture"]', 'ginger flavor,cinnamon,aroma,vanilla,texture', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('b847357daf14c3655efcbb1fd1f45dde', 'okendo', 'lisav1124_9295', 'Surprisingly good!', 'I was hesitant to try these, I won’t lie, because all of the gluten free foods I’ve tried have been garbage, but these cookies are actually GOOD and don’t taste like garbage! The blend of flours, ginger and cinnamon are perfect. The texture is not gritty and they hold up being dunked in coffee. They are perfect bite sized as well, 5 cookies for 140 calories. Def recommend!', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-20', 0, 'No', '', '', '["crunch_texture","gluten_free","stale","false_advertising"]', 'taste,texture,flavor,durability,size', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
