INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ce5e26845ba7b7dea44f4b6c4aefbb74', 'okendo', 'alonal7_9249', '🤍', 'Crunchy, fresh pretzel thins with great flavor and a light. satisfying texture. Easy to snack on and well packaged. Easy to eat, bite-sized pieces. Light and crunchy, comfortable to snack on. No instructions needed, ready to eat. No assembly required. Lightweight and perfect portion for snacking. No assembly needed.', 5, 'positive', 14, 'Sea Salt Pretzel Snack Thins', '2025-12-19', 0, 'No', '', '', '["crunch_texture","packaging"]', 'texture,flavor,packaging,size,convenience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5b1ce125e3927f06b9af9e35c846d456', 'okendo', 'alonal7_9249', '🤍', 'I really enjoyed trying Every Body Eat Ginger Cinnamon snacks. The flavor is warm and balanced, you can clearly taste the ginger with a nice cinnamon finish that isn’t too sweet.The pieces were fresh, crunchy, and well packaged with no breakage.. I like that the portion size is perfect for a quick snack or with tea. Overall, it feels like a high-quality, thoughtfully made product with clean ingredients and great taste. Flavorful ginger cinnamon snack that tastes fresh, crunchy, and perfect for a quick, satisfying treat. Durability Well packaged.stayed fresh. and didn’t break during handling..', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2025-12-19', 0, 'No', '', '', '["great_taste","crunch_texture","clean_ingredients","packaging"]', 'flavor,texture,packaging,portion size,quality', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
