INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7a1e1124be77341ada8a435b343e755f', 'okendo', 'Brenda G.', 'Ordered Cheeseless & White Pepper Garlic', 'Ordered 2 boxes white & 1 box cheeseless. 12 packages in all. ALL ARE BASICALLY CRUSHED! I sent email with pics. No response!!! Called both numbers no one to take left message!! Would never order again b/c of lacking customer service! Contents will need to be discarded b/c can''t use for spreads or dips or anything except crumbs! This is so sad as I cannot eat gluten, dairy, eggs, and this was a much hoped for solution.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2025-03-05', 0, 'Yes', '', '', '["broken_crumbs","packaging"]', 'gluten-free,dairy-free', 'packaging,texture', NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('63ed7a8ff86d984e0ccac508ece56c3b', 'okendo', 'Lynn S.', 'Delicious and good for people with colitis', 'I usually eat 2 packs of these a day, which probably isn''t super healthy but they''re such a good snack. I have colitis and other health issues and the crackers are one of the only snacks that I can eat and not get sick from. They''re life saver when I don''t have time or energy to cook or if I want to enjoy a snack. Everything else on the market makes me sick', 5, 'positive', 1, 'Cheese-less Snack Thins', '2025-02-18', 0, 'Yes', '', '', '["great_taste"]', 'snack,taste,convenience', NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
