INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('2fbd70ca8158ed50b85fde947b1ebb31', 'okendo', 'Amy I.', 'Absolutely Delicious Cookies!', 'Our family of 7 LOVES these cookies! Every flavor is delicious and has healthier ingredients than any other gluten free cookie we have tried! We love them straight out of the bag or as a fabulous topping to coconut milk ice cream. Will be buying more for sure!', 5, 'positive', 9, 'Cookie Bites Variety Pack', '2024-10-12', 0, 'Yes', '', '', '["great_taste","gluten_free"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
