INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cd4a334a81da6d01cfe06b7bfb918e2b', 'okendo', 'Benji S.', 'Burst of Cookie Flavors', 'Love these. I''ve ordered twice. I would pick a favorite but each one I put in my mouth is my favorite at that moment. I don''t always eat clean and I don''t have food allergies but I buy these because they''re delicious. Just two or three make a great little dessert.', 5, 'positive', 9, 'Cookie Bites Variety Pack', '2024-10-12', 0, 'Yes', '', '', '["great_taste","allergy_friendly"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('dc91e94209c8c05010667d67f886fc4b', 'okendo', 'Lori M.', 'Cranberry Vanilla Cookie bites', 'Light and crispy texture with a hint of sweetness and sour from the cranberry. Perfect.', 5, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2024-10-02', 0, 'Yes', '', '', '["crunch_texture"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
