INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('128c124da66256a32eb09d61bcba7817', 'okendo', 'MzVee', 'Chocolateyyyyy', 'Everybody Eats Chocolate Chip Cookie Bites are a delightful treat that perfectly encapsulates the classic flavor of chocolate chip cookies in a convenient, bite-sized form. These cookie bites are ideal for snacking or satisfying a sweet craving without the guilt. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('cd93412d3c1503fc18339b91596738e4', 'okendo', 'lgandola', 'like little snickerdoodles!', 'We received these cookies for free in exchange for an honest review and we really enjoyed them! We tried all three cookie flavors and this one reminded us of little snickerdoodles. Yum! Such a little bite of goodness. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('51c63a0dff4914f51d1038162477b0af', 'okendo', 'lgandola', 'yum!', 'We received these cookies for free in exchange for an honest review and we really enjoyed them! We were curious to try this particular flavor, as it''s pretty unique. We don''t really have anything to compare it to ... it''s it''s own unique little bite of goodness! What we really love the most about Everybody Eat cookies is that they''re void of basically any allergen you could ever think of. Seriously. And what''s impressive is that they don''t lack flavor, which is often the case when you buy allergen free treats. Everybody Eats claim s''big flavor'' and it''s true! The texture was a little more crumbly than we would have preferred, but that was the only things close to a ''con'' that we could even think of. These are tasty cookies and we were grateful we got to try them!', 4, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2024-09-25', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5cca29c19b5a832966884174ff81473e', 'okendo', 'lgandola', 'yum', 'We received these cookies for free in exchange for an honest review and we really enjoyed them! They were kind of like Famous Amos cookies, but what''s great about these cookies is that they''re void of basically any allergen you could ever think of. Seriously. And what''s kind of impressive is that they don''t lack flavor, which is often the case when you buy allergen free treats. They claim ''big flavor'' and it''s true! The texture was a little more crumbly than we would have preferred, but that''s just being nitpicky. These are tasty cookies and we were grateful we got to try them!', 4, 'positive', 6, 'Chocolate Chip Cookie Bites', '2024-09-25', 0, 'No', '', '', '["great_taste","crunch_texture","allergy_friendly"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('771c540ab7bbfea030d43fba15b11404', 'okendo', 'Sarah', 'Favorite flavor', 'This cookie has so much flavor and tastes so good with having so many good ingredients. These ones are hard to put down and hit the sweet spot.', 5, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2024-09-25', 0, 'No', '', '', '["great_taste"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
