INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('9bc6807fe3848e1a4ed5faecb56b0e5a', 'okendo', 'Karissa A.', 'Healthy Sweet Treat Alternative', 'The every body eat cookies are made with ingredients we know and are allergy free for a great school snack!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2024-09-19', 0, 'No', '', '', '["allergy_friendly","good_replacement"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('344d6fd4b7f74dcd4284d68736ce066a', 'okendo', 'Isabella P.', 'The best flavor out of the 3 cookies.', 'Unlike my other 2 reviews for the choco chip & the cranberry vanilla, (4-stars each,) , this one truly deserves 5 stars! The texture and flavor were both a perfect combo - I really wouldn''t change anything about the Ginger Cinnamon. I agree with the other reviews, that the flavor was perfectly balanced- not too weak, and not too strong! 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('c35028085d95fa7d53978bc40dfd6a04', 'okendo', 'Isabella P.', 'One of my favorites!', 'I loved everything about this cookie, but I would love it even more if there was more of a ''cranberry'' flavor in it. The flavor wasn''t as strong as I hoped it would be, but it was still delicious. 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('bb09f98bcaafce475e246816b52ef0e5', 'okendo', 'Cyndi', 'Very Tasty', 'These are delicious and healthy. My entire family loves these delicious cookie bites. The flavor of the Ginger Cinnamon is very true and tasty. The make a great snack, dessert or just a nice way to treat yourself. They are gluten-free, which is a plus for when our son-in-law visits. Great for kids and adults alike.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2024-09-17', 0, 'No', '', '', '["great_taste","gluten_free"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5e7c060f59eb7d25a0036a58a916ddae', 'okendo', 'Isabella P.', 'Amazing cookies, but could use a little improvement!', 'I loved everything about the chocolate chip cookies, but I think the flavor/texture part could use a little tweaking. The texture was very grainy, so maybe if that could be adjusted, then I would give it 5 stars! The chocolate chips themselves were great, but maybe up the actual ''chocolate'' flavor? 
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0fa6abcb215a863a0043ecdbd043817f', 'okendo', 'Cyndi', 'These Are My Favorite Flavor', 'My family loves these delicious cookie bites. This is their favorite treat. These are perfect to pack as your kids'' school snack as they are allergy free. They make a wonderful after school snack, a great dessert or just a nice way to treat yourself after a long day. They are perfect for any occasion. They are gluten-free, which is a plus for when our son-in-law visits. Great for kids and adults alike.', 5, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2024-09-17', 0, 'No', '', '', '["great_taste","gluten_free","allergy_friendly"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
