INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('22df9899a621c6237a3978fab0de494f', 'okendo', 'Lisa J.', 'Delicious Flavor Combination!', 'Not only is this tasty, but it helps me feel so much better to know that the ingredients are clean. I am excited for these cookie bites to become available in my area!', 5, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2024-09-17', 0, 'No', '', '', '["great_taste"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('3df60b5cd2cb16c198225aad65394a2f', 'okendo', 'Melinda', 'Soft and full of flavor', 'These were hands down the favorite at my Tryazon hosted event where my family was chosen to receive these new cookies to try. This flavor was the only one with a softer, chewy texture. The flavors were perfectly balanced. Strong enough to taste everything, but not so strong that kids would think they are too spicy. These are kind of like a snickerdoodle but better.', 5, 'positive', 8, 'Ginger Cinnamon Cookie Bites', '2024-09-17', 0, 'No', '', '', '["crunch_texture","too_spicy"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('4fddb2ba608d8c644c765dd48426d829', 'okendo', 'Melinda', 'Hits the sweet spot', 'My family was chosen to try these new cookies form Tryazon in exchange for honest feedback. I had several families over with kids to taste test these and everyone liked them! Most said they would prefer a few more cranberry pieces to improve the texture. These were a little dry, but still the best allergen free cookie on the market! No kid with allergies would feel like they are missing out on anything when eating these!', 5, 'positive', 7, 'Cranberry Vanilla Cookie Bites', '2024-09-17', 0, 'No', '', '', '["crunch_texture","allergy_friendly","bland_flavor","false_advertising"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('68a1aad1e52ab4483d8aef91e7a4e7aa', 'okendo', 'Melinda', 'Best GF cookie', 'These are very similar in texture to a crunchy chips ahoy, but a little more crumbly. The flavor is good - maybe not as sweet, but I prefer it that way. A big favorite with the kids in my life. It''s wonderful to have a cookie option like this that is TOTALLY allergen free that I don''t need to worry about my friends'' kids with severe allergies. There are some crumbs left on the bottom of the bag, but instead of being sad about that, just use it as topping on yogurt!', 5, 'positive', 6, 'Chocolate Chip Cookie Bites', '2024-09-17', 0, 'No', '', '', '["crunch_texture","allergy_friendly","good_replacement","broken_crumbs"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
