INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('35f89d55f0abef01bcec5d9f94ee9d47', 'okendo', 'Deana', 'Great cracker!', 'These have great texture with such a nice, crisp crunch! They are very flavorful with the perfect amount of heat. I appreciate that they are made with healthy ingredients and feel good about serving them to my family.', 5, 'positive', 3, 'Fiery Chile Lime Snack Thins', '2024-05-21', 0, 'No', '', '', '["crunch_texture"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('7d2bed3c9043b38825c4bc97a1c325a1', 'okendo', 'Sheila T.', 'Delicious crispy texture and wholesome flavor!', 'These Every Body Eats Cheese-less crackers have a wonderfully crispy texture! The crackers are very thin but still sturdy, and they are very fresh! The flavor is wholesome and something I''d describe as ''earthy cheddar'', more muted than the artificial-flavored mass-market cheese crackers but still very enjoyable. I like that they taste healthier and ''clean''. They are perfect by themselves or with a little spread or toppings!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2024-05-21', 0, 'No', '', '', '["great_taste","crunch_texture"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8ab1caee76c4842bcecbd37a035a9fce', 'okendo', 'lilstegs', 'Delicious!', 'I really love these crackers. I love that they are gluten and corn free as well as allergy friendly. I like the simple ingredients. I thought the chili lime had a great taste and a HUGE kick to it!', 5, 'positive', 3, 'Fiery Chile Lime Snack Thins', '2024-05-20', 0, 'No', '', '', '["great_taste","allergy_friendly","clean_ingredients"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
