INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('13c7ac44d8c83c4e6bae443ff19c5dea', 'okendo', 'Brittany K.', 'Cheesy crackers without the dairy', 'Every Body Eat Cheese-Less Thins are great for anyone seeking a flavorful, crunchy snack without the dairy. These thins have a satisfying crunch and a great flavor that makes them irresistible. They are perfect for those with dietary restrictions. Highly recommended for cheese lovers and anyone needing an allergy friendly snack.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2024-05-18', 0, 'No', '', '', '["crunch_texture","allergy_friendly"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8ef57a842152a221339379e6378be4a2', 'okendo', 'Katesy', 'Dense and not flavorful', 'I was expecting these to have the taste or texture of some traditional cheese crackers, but they just don''t. They''re very dense and dry, and they don''t have a rich flavor at all. They''re okay for eating with dips, but I don''t enjoy them on their own.', 2, 'negative', 1, 'Cheese-less Snack Thins', '2024-05-17', 0, 'No', '', '', '["crunch_texture","bland_flavor"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('ee98b5448b4dcdf4729e9a29400fc80f', 'okendo', 'Hopela', 'Healthy, but Bland', 'I was offered a coupon by Tryazon to try a free package of every body eat crackers. I tried the Sea Salt Chia flavor. I liked how there are only 8 ingredients in these thins, and I recognized all of the ingredients. I also liked how the package had a self-seal feature. They are also low in calories. 16 crackers were 140 calories.
