INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('8de7f112cc2245981914421bda9933d4', 'okendo', 'Misty', 'Awful', 'Walked into Whole Foods to buy our usual Earth Balance cheddar squares only to find out that they are not made anymore. Sales associate suggested these since we manage multiple food allergies in our house. Bought a bag, walked to the car with my nine-year-old son and opened them up to try for the first time. We both just looked at each other and made a horrible stink face. These are not good. Like eating cardboard yeast. $5 wasted and will never buy again.', 1, 'negative', 1, 'Cheese-less Snack Thins', '2022-08-26', 0, 'No', '', '', '["allergy_friendly","repeat_purchase","clean_ingredients","stale"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
