INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('20eab01f15a4759f9000d3497cfbed03', 'okendo', 'Marla G.', 'Each Flavor Delicious', 'We enjoyed tasting all of the flavors. One really has a nice kick. One has a great cheese flavor. I''ve already ordered a second pack.', 5, 'positive', 5, 'Snack Thins Variety Pack', '2022-05-05', 0, 'Yes', '', '', '["great_taste"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
