INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('05547dcd0f9a5d9d07875f7993d0fecb', 'okendo', 'Picky e.', 'Surprisingly delicious!', 'Saw them a Price Chopper for under $5 (still pricey), and doubted that these would be very cheesy. I was very surprised that there was enough cheese flavoring along with the other spices to make these very snack-worthy (though not super-infused liked Fish Crackers or Cheez-its). The yeast hasn''t bothered me at all, and there is none of the terrible after-taste that you get with high protein chips and cheese puffs (really horrible flavor). I definitely recommend these for the lactose intolerant, paleo followers, or anyone who tends to avoid milk products, but they''re fin for anyone. They''re Kosher, gluten-free and non-gmo for those who care. Enjoy!', 5, 'positive', 1, 'Cheese-less Snack Thins', '2022-02-18', 0, 'No', '', '', '["great_taste","gluten_free"]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('0c35c2dbd6552141a7a731adeec20896', 'okendo', 'Kris R.', 'I love them.', 'I love them.', 5, 'positive', 1, 'Cheese-less Snack Thins', '2021-12-03', 0, 'Yes', '', '', '[]', NULL, NULL, NULL, '2026-08-23T16:26:17.000Z', 'reviews-export-2026-08-19-172713165.csv (production import)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, positive_keywords, negative_keywords, mixed_keywords, imported_at, source_file) VALUES ('5aeb3eb89a6b63ceb6d579ac9b3312ed', 'okendo', 'Cynthia D.', 'Game changer!!', 'I have been looking for a cracker that actually had some flavor to it. These fit the bill. I add them to my soup, as a side with a GF sandwich, or just eat right out if the bag. 
